import React from 'react';
import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import { DataProvider } from './context/DataContext';
import { AO02Provider } from './context/AO02Context';
import { Sidebar } from './components/common/Sidebar';
import { Header } from './components/common/Header';
import { ToastContainer } from './components/common/ToastContainer';
import { GlobalSearchModal } from './components/common/GlobalSearchModal';
import { AutomatedFaultModal } from './components/datacenter/AutomatedFaultModal';
import { CoolerDetailModal } from './components/datacenter/CoolerDetailModal';

// Pages
import { Overview } from './pages/Overview';
import { DataCenter } from './pages/DataCenter';
import { Forecasts } from './pages/Forecasts';
import { Resources } from './pages/Resources';
import { Alerts } from './pages/Alerts';
import { RootCause } from './pages/RootCause';
import { DataManagement } from './pages/DataManagement';
import { AuditLogs } from './pages/AuditLogs';
import { Settings } from './pages/Settings';

function AppModals() {
  return (
    <>
      <GlobalSearchModal />
      <ToastContainer />
      <AutomatedFaultModal />
      <CoolerDetailModal />
    </>
  );
}

export function App() {
  return (
    <AO02Provider>
      <DataProvider>
        <BrowserRouter>
          <div className="flex h-screen w-screen overflow-hidden bg-slate-50/50 text-slate-900 font-sans">
            {/* Collapsible Left Navigation Sidebar */}
            <Sidebar />

            {/* Main App Container */}
            <div className="flex flex-col flex-1 h-screen overflow-hidden">
              {/* Top Minimalist Header */}
              <Header />

              {/* Scrollable Content Viewport */}
              <main className="flex-1 overflow-y-auto">
                <Routes>
                  <Route path="/" element={<Overview />} />
                  <Route path="/datacenter" element={<DataCenter />} />
                  <Route path="/forecasts" element={<Forecasts />} />
                  <Route path="/resources" element={<Resources />} />
                  <Route path="/alerts" element={<Alerts />} />
                  <Route path="/root-cause" element={<RootCause />} />
                  <Route path="/data-management" element={<DataManagement />} />
                  <Route path="/audit-logs" element={<AuditLogs />} />
                  <Route path="/settings" element={<Settings />} />
                  <Route path="*" element={<Navigate to="/" replace />} />
                </Routes>
              </main>
            </div>

            {/* Floating Modals and Toasts */}
            <AppModals />
          </div>
        </BrowserRouter>
      </DataProvider>
    </AO02Provider>
  );
}

export default App;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Search,
  Server,
  Cpu,
  AlertTriangle,
  ArrowRight,
  X,
  Compass
} from 'lucide-react';
import { useData } from '../../context/DataContext';

export const GlobalSearchModal: React.FC = () => {
  const { isSearchOpen, setIsSearchOpen, racks, resources, alerts, setSelectedRackId } = useData();
  const [query, setQuery] = useState('');
  const navigate = useNavigate();

  // Listen for Cmd+K / Ctrl+K
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        e.preventDefault();
        setIsSearchOpen(true);
      } else if (e.key === 'Escape') {
        setIsSearchOpen(false);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [setIsSearchOpen]);

  if (!isSearchOpen) return null;

  const q = query.toLowerCase().trim();

  const matchedRacks = racks.filter(
    (r) => r.label.toLowerCase().includes(q) || r.tenant.toLowerCase().includes(q)
  );

  const matchedResources = resources.filter(
    (res) =>
      res.name.toLowerCase().includes(q) ||
      res.type.toLowerCase().includes(q) ||
      res.tenant.toLowerCase().includes(q)
  );

  const matchedAlerts = alerts.filter(
    (a) =>
      a.title.toLowerCase().includes(q) ||
      a.metric.toLowerCase().includes(q) ||
      a.tenant.toLowerCase().includes(q)
  );

  const navigationShortcuts = [
    { label: 'Overview Dashboard', path: '/' },
    { label: 'Data Centre 3D Digital Twin', path: '/datacenter' },
    { label: 'Capacity Forecasts & Exhaustion', path: '/forecasts' },
    { label: 'Resource Inventory & Telemetry', path: '/resources' },
    { label: 'Early Warning Alerts', path: '/alerts' },
    { label: 'Root Cause Diagnostics (RCA)', path: '/root-cause' },
    { label: 'Data Management & CSV Ingestion', path: '/data-management' },
    { label: 'Audit Trail & Event Logs', path: '/audit-logs' },
    { label: 'Platform Settings & Thresholds', path: '/settings' },
  ].filter((p) => p.label.toLowerCase().includes(q));

  return (
    <div className="fixed inset-0 z-[9999] flex items-start justify-center pt-20 px-4 bg-slate-900/50 backdrop-blur-xs select-none">
      <div
        className="fixed inset-0"
        onClick={() => setIsSearchOpen(false)}
      />

      <div className="relative w-full max-w-xl bg-white rounded-xl shadow-2xl border border-slate-200 overflow-hidden z-10 flex flex-col max-h-[75vh]">
        {/* Input bar */}
        <div className="p-3 border-b border-slate-200 flex items-center gap-2.5 bg-slate-50">
          <Search className="w-4 h-4 text-slate-400 shrink-0" />
          <input
            type="text"
            placeholder="Search racks, resources, alerts, or jump to page..."
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            autoFocus
            className="w-full bg-transparent text-sm text-slate-900 placeholder:text-slate-400 focus:outline-none"
          />
          <button
            onClick={() => setIsSearchOpen(false)}
            className="p-1 rounded text-slate-400 hover:text-slate-600"
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        {/* Results listing */}
        <div className="overflow-y-auto p-2 space-y-3 text-xs">
          {/* Quick Racks */}
          {matchedRacks.length > 0 && (
            <div>
              <div className="px-2 py-1 text-[10px] font-mono uppercase tracking-wider text-slate-400">
                Server Racks ({matchedRacks.length})
              </div>
              <div className="space-y-0.5">
                {matchedRacks.slice(0, 4).map((r) => (
                  <button
                    key={r.id}
                    onClick={() => {
                      setSelectedRackId(r.id);
                      setIsSearchOpen(false);
                      navigate('/');
                    }}
                    className="w-full text-left p-2 rounded-md hover:bg-slate-100 flex items-center justify-between group transition-colors"
                  >
                    <div className="flex items-center gap-2">
                      <Server className="w-3.5 h-3.5 text-slate-400 group-hover:text-blue-600" />
                      <span className="font-mono font-semibold text-slate-800">{r.label}</span>
                      <span className="text-slate-400">• {r.tenant}</span>
                      <span className="text-slate-400">({r.row})</span>
                    </div>
                    <div className="flex items-center gap-2">
                      <span className="text-[11px] font-mono text-slate-500">{r.tempC}°C</span>
                      <ArrowRight className="w-3.5 h-3.5 text-slate-300 group-hover:text-slate-600" />
                    </div>
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* Resources */}
          {matchedResources.length > 0 && (
            <div>
              <div className="px-2 py-1 text-[10px] font-mono uppercase tracking-wider text-slate-400">
                Resources ({matchedResources.length})
              </div>
              <div className="space-y-0.5">
                {matchedResources.slice(0, 4).map((res) => (
                  <button
                    key={res.id}
                    onClick={() => {
                      setIsSearchOpen(false);
                      navigate('/resources');
                    }}
                    className="w-full text-left p-2 rounded-md hover:bg-slate-100 flex items-center justify-between group transition-colors"
                  >
                    <div className="flex items-center gap-2">
                      <Cpu className="w-3.5 h-3.5 text-slate-400 group-hover:text-indigo-600" />
                      <span className="font-medium text-slate-800">{res.name}</span>
                      <span className="text-[10px] px-1.5 py-0.2 rounded bg-slate-100 font-mono text-slate-600">
                        {res.type}
                      </span>
                    </div>
                    <span className="font-mono text-slate-600 font-semibold">{res.utilPercent}%</span>
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* Alerts */}
          {matchedAlerts.length > 0 && (
            <div>
              <div className="px-2 py-1 text-[10px] font-mono uppercase tracking-wider text-slate-400">
                Alerts ({matchedAlerts.length})
              </div>
              <div className="space-y-0.5">
                {matchedAlerts.slice(0, 3).map((alt) => (
                  <button
                    key={alt.id}
                    onClick={() => {
                      setIsSearchOpen(false);
                      navigate('/alerts');
                    }}
                    className="w-full text-left p-2 rounded-md hover:bg-slate-100 flex items-center justify-between group transition-colors"
                  >
                    <div className="flex items-center gap-2">
                      <AlertTriangle className="w-3.5 h-3.5 text-amber-500" />
                      <span className="font-medium text-slate-800 truncate max-w-sm">{alt.title}</span>
                    </div>
                    <span className="text-[10px] font-mono uppercase font-bold text-amber-600">
                      {alt.severity}
                    </span>
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* Page shortcuts */}
          {navigationShortcuts.length > 0 && (
            <div>
              <div className="px-2 py-1 text-[10px] font-mono uppercase tracking-wider text-slate-400">
                Navigation Shortcuts
              </div>
              <div className="space-y-0.5">
                {navigationShortcuts.slice(0, 4).map((shortcut) => (
                  <button
                    key={shortcut.path}
                    onClick={() => {
                      setIsSearchOpen(false);
                      navigate(shortcut.path);
                    }}
                    className="w-full text-left p-2 rounded-md hover:bg-slate-100 flex items-center justify-between group transition-colors"
                  >
                    <div className="flex items-center gap-2">
                      <Compass className="w-3.5 h-3.5 text-slate-400 group-hover:text-blue-500" />
                      <span className="text-slate-700">{shortcut.label}</span>
                    </div>
                    <span className="font-mono text-[10px] text-slate-400">{shortcut.path}</span>
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>

        <div className="p-2 border-t border-slate-100 bg-slate-50 flex items-center justify-between text-[11px] text-slate-400 font-mono px-3">
          <span>Search with instant keyboard navigation</span>
          <span>ESC to exit</span>
        </div>
      </div>
    </div>
  );
};

