import React, { useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import {
  Search,
  Bell,
  RefreshCw,
  Building2,
  ChevronDown,
  Activity,
  CheckCircle2,
  AlertTriangle,
  X,
  ExternalLink
} from 'lucide-react';
import { useData } from '../../context/DataContext';
import { TenantName } from '../../types';

const TENANTS: TenantName[] = [
  'All Tenants',
  'Acme Cloud',
  'FinTech Core',
  'HealthTech Alpha',
  'RetailStream'
];

const PAGE_TITLES: Record<string, { title: string; category: string }> = {
  '/': { title: 'Infrastructure Overview', category: 'Operations' },
  '/datacenter': { title: 'Data Centre Digital Twin', category: 'Facilities' },
  '/forecasts': { title: 'Capacity Forecasts', category: 'Intelligence' },
  '/resources': { title: 'Resource Monitoring', category: 'Telemetry' },
  '/alerts': { title: 'Early Warning Alerts', category: 'Incidents' },
  '/root-cause': { title: 'Root Cause Analysis', category: 'Diagnostics' },
  '/data-management': { title: 'Data Management & Ingestion', category: 'Data Pipeline' },
  '/audit-logs': { title: 'Audit Trail & Event Log', category: 'Governance' },
  '/settings': { title: 'Platform Settings', category: 'Configuration' },
};

export const Header: React.FC = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const {
    currentTenant,
    setCurrentTenant,
    lastUpdated,
    triggerRefresh,
    alerts,
    setIsSearchOpen,
    isSimulating,
    setIsSimulating
  } = useData();

  const [isTenantMenuOpen, setIsTenantMenuOpen] = useState(false);
  const [isAlertsOpen, setIsAlertsOpen] = useState(false);
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);

  const activeAlerts = alerts.filter((a) => a.status === 'active');
  const criticalCount = activeAlerts.filter((a) => a.severity === 'critical').length;

  const currentMeta = PAGE_TITLES[location.pathname] || {
    title: 'CapacityIQ',
    category: 'Console',
  };

  const handleRefreshClick = () => {
    setIsRefreshing(true);
    triggerRefresh();
    setTimeout(() => setIsRefreshing(false), 600);
  };

  return (
    <header className="h-14 border-b border-slate-200 bg-white/95 backdrop-blur-md px-4 flex items-center justify-between sticky top-0 z-30 select-none">
      {/* Left: Page Title & Breadcrumb */}
      <div className="flex items-center gap-3">
        <div className="flex flex-col">
          <div className="flex items-center gap-2">
            <span className="text-[11px] font-mono uppercase tracking-wider text-slate-400">
              {currentMeta.category}
            </span>
            <span className="text-slate-300">/</span>
            <h1 className="text-sm font-semibold text-slate-900 tracking-tight">
              {currentMeta.title}
            </h1>
          </div>
        </div>
      </div>

      {/* Center: Live Simulation Status */}
      <div className="hidden md:flex items-center">
        <button
          onClick={() => setIsSimulating((prev) => !prev)}
          title="Click to toggle live sensor simulation"
          className={`flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-mono transition-all border ${
            isSimulating
              ? 'bg-emerald-50 text-emerald-700 border-emerald-200'
              : 'bg-slate-100 text-slate-600 border-slate-200'
          }`}
        >
          <span
            className={`w-2 h-2 rounded-full ${
              isSimulating ? 'bg-emerald-500 animate-pulse' : 'bg-slate-400'
            }`}
          />
          <span>{isSimulating ? 'Simulation Active' : 'Simulation Paused'}</span>
        </button>
      </div>

      {/* Right: Tenant selector, Search, Last updated, Refresh, Notifications, Profile */}
      <div className="flex items-center gap-2">
        {/* Tenant Selector Dropdown */}
        <div className="relative">
          <button
            onClick={() => setIsTenantMenuOpen(!isTenantMenuOpen)}
            className="flex items-center gap-1.5 px-2.5 py-1.5 rounded-md border border-slate-200 hover:border-slate-300 text-xs font-medium text-slate-700 hover:bg-slate-50 transition-colors"
          >
            <Building2 className="w-3.5 h-3.5 text-slate-500" />
            <span className="max-w-[110px] truncate">{currentTenant}</span>
            <ChevronDown className="w-3.5 h-3.5 text-slate-400" />
          </button>

          {isTenantMenuOpen && (
            <>
              <div
                className="fixed inset-0 z-40"
                onClick={() => setIsTenantMenuOpen(false)}
              />
              <div className="absolute right-0 mt-1 w-44 rounded-md border border-slate-200 bg-white shadow-lg py-1 z-50 text-xs font-medium">
                <div className="px-3 py-1.5 text-[10px] uppercase font-mono tracking-wider text-slate-400 border-b border-slate-100">
                  Select Tenant Context
                </div>
                {TENANTS.map((tenant) => (
                  <button
                    key={tenant}
                    onClick={() => {
                      setCurrentTenant(tenant);
                      setIsTenantMenuOpen(false);
                    }}
                    className={`w-full text-left px-3 py-1.5 hover:bg-slate-50 flex items-center justify-between ${
                      currentTenant === tenant
                        ? 'text-blue-600 font-semibold bg-blue-50/50'
                        : 'text-slate-700'
                    }`}
                  >
                    <span>{tenant}</span>
                    {currentTenant === tenant && (
                      <CheckCircle2 className="w-3.5 h-3.5 text-blue-600" />
                    )}
                  </button>
                ))}
              </div>
            </>
          )}
        </div>

        {/* Global Search Button */}
        <button
          onClick={() => setIsSearchOpen(true)}
          className="flex items-center gap-2 px-2.5 py-1.5 rounded-md border border-slate-200 text-slate-400 hover:text-slate-700 hover:border-slate-300 hover:bg-slate-50 transition-colors text-xs font-sans"
          title="Search resources, racks, alerts (Ctrl+K)"
        >
          <Search className="w-3.5 h-3.5" />
          <span className="hidden lg:inline text-slate-400">Search...</span>
          <kbd className="hidden lg:inline font-mono text-[10px] bg-slate-100 text-slate-500 px-1.5 py-0.5 rounded border border-slate-200">
            ⌘K
          </kbd>
        </button>

        {/* Refresh & Timestamp */}
        <div className="hidden sm:flex items-center gap-1.5 text-xs text-slate-400 font-mono">
          <span className="text-[11px]">
            {lastUpdated.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })}
          </span>
          <button
            onClick={handleRefreshClick}
            disabled={isRefreshing}
            className="p-1.5 rounded-md text-slate-500 hover:text-slate-800 hover:bg-slate-100 transition-colors"
            title="Poll telemetry now"
          >
            <RefreshCw className={`w-3.5 h-3.5 ${isRefreshing ? 'animate-spin text-blue-600' : ''}`} />
          </button>
        </div>

        {/* Notification Bell with Badge & Dropdown */}
        <div className="relative">
          <button
            onClick={() => setIsAlertsOpen(!isAlertsOpen)}
            className="p-1.5 rounded-md text-slate-600 hover:text-slate-900 hover:bg-slate-100 transition-colors relative"
            title="Active Early Warning Alerts"
          >
            <Bell className="w-4 h-4" />
            {activeAlerts.length > 0 && (
              <span className="absolute top-1 right-1 w-2 h-2 rounded-full bg-rose-500 ring-2 ring-white" />
            )}
          </button>

          {isAlertsOpen && (
            <>
              <div
                className="fixed inset-0 z-40"
                onClick={() => setIsAlertsOpen(false)}
              />
              <div className="absolute right-0 mt-2 w-80 rounded-lg border border-slate-200 bg-white shadow-xl z-50 overflow-hidden text-xs">
                <div className="p-3 border-b border-slate-100 flex items-center justify-between bg-slate-50">
                  <div className="flex items-center gap-2">
                    <span className="font-semibold text-slate-800">Early Warning Alerts</span>
                    <span className="px-1.5 py-0.2 rounded bg-rose-100 text-rose-700 text-[10px] font-mono font-bold">
                      {activeAlerts.length}
                    </span>
                  </div>
                  <button
                    onClick={() => {
                      setIsAlertsOpen(false);
                      navigate('/alerts');
                    }}
                    className="text-blue-600 hover:text-blue-800 font-medium text-[11px] flex items-center gap-1"
                  >
                    <span>View all</span>
                    <ExternalLink className="w-3 h-3" />
                  </button>
                </div>

                <div className="max-h-64 overflow-y-auto divide-y divide-slate-100">
                  {activeAlerts.length === 0 ? (
                    <div className="p-4 text-center text-slate-400">
                      No active capacity alerts
                    </div>
                  ) : (
                    activeAlerts.map((alt) => (
                      <div
                        key={alt.id}
                        onClick={() => {
                          setIsAlertsOpen(false);
                          navigate('/alerts');
                        }}
                        className="p-3 hover:bg-slate-50 cursor-pointer transition-colors space-y-1"
                      >
                        <div className="flex items-center justify-between">
                          <span className="font-semibold text-slate-800 text-[11px] truncate max-w-[180px]">
                            {alt.title}
                          </span>
                          <span
                            className={`text-[9px] font-mono px-1 rounded uppercase font-bold ${
                              alt.severity === 'critical'
                                ? 'bg-rose-50 text-rose-700'
                                : 'bg-amber-50 text-amber-700'
                            }`}
                          >
                            {alt.severity}
                          </span>
                        </div>
                        <p className="text-[11px] text-slate-500 leading-tight">
                          {alt.recommendedAction}
                        </p>
                        <div className="text-[10px] font-mono text-slate-400 flex items-center justify-between pt-0.5">
                          <span>{alt.predictedExhaustion}</span>
                          <span>{alt.timestamp}</span>
                        </div>
                      </div>
                    ))
                  )}
                </div>
              </div>
            </>
          )}
        </div>

        {/* User Profile Avatar / Menu */}
        <div className="relative">
          <button
            onClick={() => setIsProfileOpen(!isProfileOpen)}
            className="flex items-center gap-2 pl-1 rounded-full focus:outline-none"
          >
            <div className="w-7 h-7 rounded-full bg-slate-900 text-white flex items-center justify-center font-mono text-xs font-semibold ring-1 ring-slate-200">
              TJ
            </div>
          </button>

          {isProfileOpen && (
            <>
              <div
                className="fixed inset-0 z-40"
                onClick={() => setIsProfileOpen(false)}
              />
              <div className="absolute right-0 mt-2 w-52 rounded-md border border-slate-200 bg-white shadow-lg py-1 z-50 text-xs">
                <div className="px-3 py-2 border-b border-slate-100">
                  <div className="font-semibold text-slate-900">Tejas Sharma</div>
                  <div className="text-slate-500 text-[11px]">Lead SRE & Capacity Architect</div>
                </div>
                <button
                  onClick={() => {
                    setIsProfileOpen(false);
                    navigate('/settings');
                  }}
                  className="w-full text-left px-3 py-2 hover:bg-slate-50 text-slate-700"
                >
                  Preferences & Thresholds
                </button>
                <button
                  onClick={() => {
                    setIsProfileOpen(false);
                    navigate('/audit-logs');
                  }}
                  className="w-full text-left px-3 py-2 hover:bg-slate-50 text-slate-700"
                >
                  Audit Activity
                </button>
                <div className="border-t border-slate-100 my-1" />
                <div className="px-3 py-1.5 text-[10px] text-slate-400 font-mono">
                  CapacityIQ v2.4.0 (Enterprise)
                </div>
              </div>
            </>
          )}
        </div>
      </div>
    </header>
  );
};

sources.src/components/common/Sidebar.tsx:
import React, { useState } from 'react';
import { NavLink } from 'react-router-dom';
import {
  LayoutDashboard,
  Box,
  TrendingUp,
  Cpu,
  AlertTriangle,
  GitBranch,
  Database,
  FileText,
  Settings,
  ChevronLeft,
  ChevronRight,
  ShieldCheck,
  Server
} from 'lucide-react';
import { useData } from '../../context/DataContext';

export const Sidebar: React.FC = () => {
  const [isCollapsed, setIsCollapsed] = useState(false);
  const { alerts, racks } = useData();

  const activeAlertsCount = alerts.filter((a) => a.status === 'active').length;
  const criticalCount = alerts.filter((a) => a.status === 'active' && a.severity === 'critical').length;

  const navItems = [
    { to: '/', label: 'Overview', icon: LayoutDashboard },
    { to: '/datacenter', label: 'Data Centre', icon: Box },
    { to: '/forecasts', label: 'Capacity Forecasts', icon: TrendingUp },
    { to: '/resources', label: 'Resource Monitoring', icon: Cpu },
    {
      to: '/alerts',
      label: 'Alerts',
      icon: AlertTriangle,
      badge: activeAlertsCount > 0 ? activeAlertsCount : null,
      isCritical: criticalCount > 0
    },
    { to: '/root-cause', label: 'Root Cause Analysis', icon: GitBranch },
    { to: '/data-management', label: 'Data Management', icon: Database },
    { to: '/audit-logs', label: 'Audit Logs', icon: FileText },
    { to: '/settings', label: 'Settings', icon: Settings },
  ];

  return (
    <aside
      className={`h-screen bg-white border-r border-slate-200 flex flex-col justify-between transition-all duration-200 sticky top-0 z-40 select-none ${
        isCollapsed ? 'w-16' : 'w-60'
      }`}
    >
      {/* Top Branding Section */}
      <div>
        <div className="h-14 border-b border-slate-200 flex items-center justify-between px-3.5">
          {!isCollapsed && (
            <div className="flex items-center gap-2.5">
              <div className="w-8 h-8 rounded-lg bg-blue-600 text-white flex items-center justify-center font-bold shadow-xs">
                <Box className="w-4 h-4" />
              </div>
              <div className="flex flex-col">
                <span className="font-bold text-slate-900 text-sm tracking-tight leading-none">
                  Capacity<span className="text-blue-600">IQ</span>
                </span>
                <span className="text-[10px] font-mono text-slate-400 mt-0.5">
                  AI PREDICTIVE OPS
                </span>
              </div>
            </div>
          )}

          {isCollapsed && (
            <div className="w-8 h-8 mx-auto rounded-lg bg-blue-600 text-white flex items-center justify-center font-bold shadow-xs">
              <Box className="w-4 h-4" />
            </div>
          )}

          <button
            onClick={() => setIsCollapsed(!isCollapsed)}
            className="p-1 rounded-md text-slate-400 hover:text-slate-700 hover:bg-slate-100 transition-colors"
            title={isCollapsed ? 'Expand sidebar' : 'Collapse sidebar'}
          >
            {isCollapsed ? <ChevronRight className="w-4 h-4" /> : <ChevronLeft className="w-4 h-4" />}
          </button>
        </div>

        {/* Navigation Link List */}
        <nav className="p-2 space-y-1">
          {navItems.map((item) => {
            const Icon = item.icon;
            return (
              <NavLink
                key={item.to}
                to={item.to}
                className={({ isActive }) =>
                  `flex items-center gap-3 px-3 py-2 rounded-md text-xs font-medium transition-all group relative ${
                    isActive
                      ? 'bg-blue-50 text-blue-700 font-semibold'
                      : 'text-slate-600 hover:text-slate-900 hover:bg-slate-50'
                  } ${isCollapsed ? 'justify-center px-0' : ''}`
                }
              >
                {({ isActive }) => (
                  <>
                    <Icon
                      className={`w-4 h-4 shrink-0 transition-colors ${
                        isActive ? 'text-blue-600' : 'text-slate-400 group-hover:text-slate-600'
                      }`}
                    />

                    {!isCollapsed && (
                      <span className="truncate flex-1">{item.label}</span>
                    )}

                    {!isCollapsed && item.badge !== null && (
                      <span
                        className={`px-1.5 py-0.2 rounded-full text-[10px] font-mono font-bold ${
                          item.isCritical
                            ? 'bg-rose-100 text-rose-700'
                            : 'bg-amber-100 text-amber-800'
                        }`}
                      >
                        {item.badge}
                      </span>
                    )}

                    {/* Tooltip for collapsed mode */}
                    {isCollapsed && (
                      <div className="absolute left-full ml-2 px-2 py-1 bg-slate-900 text-white text-[11px] rounded shadow-md whitespace-nowrap opacity-0 pointer-events-none group-hover:opacity-100 transition-opacity z-50">
                        {item.label}
                        {item.badge !== null && ` (${item.badge})`}
                      </div>
                    )}
                  </>
                )}
              </NavLink>
            );
          })}
        </nav>
      </div>

      {/* Bottom Facility Status Widget */}
      <div className="p-3 border-t border-slate-200">
        {!isCollapsed ? (
          <div className="p-2.5 rounded-lg bg-slate-50 border border-slate-200/80 space-y-1.5 text-xs">
            <div className="flex items-center justify-between">
              <span className="text-[11px] font-mono text-slate-500 uppercase">Facility PUE</span>
              <span className="font-mono font-bold text-emerald-700">1.18 (Optimal)</span>
            </div>
            <div className="flex items-center justify-between text-[11px] text-slate-500">
              <span>Active Racks</span>
              <span className="font-mono text-slate-800">{racks.length} Online</span>
            </div>
            <div className="w-full bg-slate-200 h-1 rounded-full overflow-hidden">
              <div className="bg-emerald-500 h-full w-[88%]" />
            </div>
          </div>
        ) : (
          <div className="flex justify-center" title="Facility PUE: 1.18 (Optimal)">
            <span className="w-2.5 h-2.5 rounded-full bg-emerald-500" />
          </div>
        )}
      </div>
    </aside>
  );
};

