import React, { useRef, useMemo } from 'react';
import * as THREE from 'three';
import { useFrame } from '@react-three/fiber';

interface AirflowProps {
  isPlaying: boolean;
  speedMultiplier?: number;
  showArrows?: boolean;
  showParticles?: boolean;
  density?: 'low' | 'medium' | 'high';
}

// Arrow 3D shape (aerodynamic cone head + glowing cylindrical stem)
const createArrowMesh = (color: string, emissive: string) => {
  return (
    <group>
      {/* Stem */}
      <mesh position={[0, -0.1, 0]}>
        <cylinderGeometry args={[0.022, 0.022, 0.22, 12]} />
        <meshStandardMaterial
          color={color}
          emissive={emissive}
          emissiveIntensity={0.6}
          roughness={0.25}
          transparent
          opacity={0.9}
        />
      </mesh>
      {/* Arrow head cone */}
      <mesh position={[0, 0.08, 0]}>
        <coneGeometry args={[0.075, 0.16, 12]} />
        <meshStandardMaterial
          color={color}
          emissive={emissive}
          emissiveIntensity={0.8}
          roughness={0.2}
          transparent
          opacity={0.95}
        />
      </mesh>
    </group>
  );
};

export const Airflow: React.FC<AirflowProps> = ({
  isPlaying = true,
  speedMultiplier = 1.0,
  showArrows = true,
  showParticles = true,
  density = 'medium',
}) => {
  const coldArrowsGroup = useRef<THREE.Group>(null);
  const hotArrowsGroup = useRef<THREE.Group>(null);
  const coldPointsRef = useRef<THREE.Points>(null);
  const hotPointsRef = useRef<THREE.Points>(null);

  // Setup Arrow instances data
  // Cold arrows in cold aisle (Z between -1.0 and 1.0, X from -5 to +5)
  const coldArrowData = useMemo(() => {
    const list: { x: number; baseZ: number; baseY: number; speed: number; phase: number }[] = [];
    const count = density === 'low' ? 12 : density === 'medium' ? 22 : 36;
    for (let i = 0; i < count; i++) {
      const x = -5.2 + (i / count) * 10.4 + (Math.sin(i) * 0.3);
      const baseZ = (Math.sin(i * 1.7) * 0.7); // centered in cold aisle
      const baseY = (i % 6) * 0.35;
      const speed = 0.6 + (i % 5) * 0.1;
      const phase = (i * 0.28) % Math.PI;
      list.push({ x, baseZ, baseY, speed, phase });
    }
    return list;
  }, [density]);

  // Hot arrows in hot aisles (Behind Row A: Z ~ -3.0, Behind Row B: Z ~ +3.0)
  const hotArrowData = useMemo(() => {
    const list: { x: number; z: number; baseY: number; speed: number; phase: number }[] = [];
    const count = density === 'low' ? 12 : density === 'medium' ? 24 : 36;
    for (let i = 0; i < count; i++) {
      const isRowA = i % 2 === 0;
      const x = -5.0 + ((i >> 1) / (count / 2)) * 10.0;
      const z = isRowA ? -2.95 : 2.95;
      const baseY = 0.4 + (i % 6) * 0.4;
      const speed = 0.7 + (i % 4) * 0.12;
      const phase = (i * 0.35) % Math.PI;
      list.push({ x, z, baseY, speed, phase });
    }
    return list;
  }, [density]);

  // Particle positions for cold air drift
  const particleCount = density === 'low' ? 120 : density === 'medium' ? 260 : 450;

  const [coldParticlePositions, coldSpeeds] = useMemo(() => {
    const pos = new Float32Array(particleCount * 3);
    const spd = new Float32Array(particleCount);
    for (let i = 0; i < particleCount; i++) {
      pos[i * 3 + 0] = -5.5 + Math.random() * 11.0; // X
      pos[i * 3 + 1] = Math.random() * 2.5; // Y
      pos[i * 3 + 2] = -0.9 + Math.random() * 1.8; // Z (cold aisle)
      spd[i] = 0.3 + Math.random() * 0.5;
    }
    return [pos, spd];
  }, [particleCount]);

  const [hotParticlePositions, hotSpeeds] = useMemo(() => {
    const pos = new Float32Array(particleCount * 3);
    const spd = new Float32Array(particleCount);
    for (let i = 0; i < particleCount; i++) {
      const isRowA = Math.random() > 0.5;
      pos[i * 3 + 0] = -5.5 + Math.random() * 11.0; // X
      pos[i * 3 + 1] = 0.3 + Math.random() * 3.2; // Y rising to ceiling
      pos[i * 3 + 2] = isRowA
        ? -2.8 - Math.random() * 0.8 // Behind Row A
        : 2.8 + Math.random() * 0.8; // Behind Row B
      spd[i] = 0.4 + Math.random() * 0.6;
    }
    return [pos, spd];
  }, [particleCount]);

  // Animation frame loop using Three.js clock
  useFrame((state, delta) => {
    if (!isPlaying) return;

    const dt = Math.min(delta, 0.1) * speedMultiplier;
    const time = state.clock.elapsedTime * speedMultiplier;

    // Animate Cold Arrows (rising from floor grilles toward rack intake)
    if (coldArrowsGroup.current && showArrows) {
      coldArrowsGroup.current.children.forEach((child, idx) => {
        const d = coldArrowData[idx];
        if (!d) return;
        // Cycle Y between 0.05 and 2.2
        const progress = (time * d.speed + d.phase) % 1.0;
        const currentY = 0.1 + progress * 2.1;
        // Slight drift towards nearest rack row front as it rises
        const targetZ = d.baseZ > 0 ? 0.9 : -0.9;
        const currentZ = d.baseZ + (targetZ - d.baseZ) * Math.pow(progress, 2);

        child.position.set(d.x, currentY, currentZ);
        // Tilt slightly towards the rack face
        const tilt = (targetZ > 0 ? 0.25 : -0.25) * progress;
        child.rotation.set(tilt, 0, 0);

        // Fade in at floor, fade out near intake
        const opacity = Math.sin(progress * Math.PI);
        child.scale.setScalar(0.7 + opacity * 0.4);
      });
    }

    // Animate Hot Arrows (rising from rear exhaust toward ceiling plenum)
    if (hotArrowsGroup.current && showArrows) {
      hotArrowsGroup.current.children.forEach((child, idx) => {
        const d = hotArrowData[idx];
        if (!d) return;
        const progress = (time * d.speed + d.phase) % 1.0;
        const currentY = 0.3 + progress * 3.2;

        child.position.set(d.x, currentY, d.z);
        // Fade in/out
        const opacity = Math.sin(progress * Math.PI);
        child.scale.setScalar(0.7 + opacity * 0.4);
      });
    }

    // Animate Cold Particles
    if (coldPointsRef.current && showParticles) {
      const geo = coldPointsRef.current.geometry;
      const posAttr = geo.attributes.position as THREE.BufferAttribute;
      const arr = posAttr.array as Float32Array;

      for (let i = 0; i < particleCount; i++) {
        arr[i * 3 + 1] += coldSpeeds[i] * dt * 1.5;
        // Reset when reaches top
        if (arr[i * 3 + 1] > 2.4) {
          arr[i * 3 + 1] = 0.05;
          arr[i * 3 + 0] = -5.5 + Math.random() * 11.0;
          arr[i * 3 + 2] = -0.8 + Math.random() * 1.6;
        }
      }
      posAttr.needsUpdate = true;
    }

    // Animate Hot Particles
    if (hotPointsRef.current && showParticles) {
      const geo = hotPointsRef.current.geometry;
      const posAttr = geo.attributes.position as THREE.BufferAttribute;
      const arr = posAttr.array as Float32Array;

      for (let i = 0; i < particleCount; i++) {
        arr[i * 3 + 1] += hotSpeeds[i] * dt * 1.8;
        // Reset when reaches ceiling
        if (arr[i * 3 + 1] > 3.6) {
          arr[i * 3 + 1] = 0.4;
          const isRowA = Math.random() > 0.5;
          arr[i * 3 + 0] = -5.5 + Math.random() * 11.0;
          arr[i * 3 + 2] = isRowA ? -2.8 - Math.random() * 0.7 : 2.8 + Math.random() * 0.7;
        }
      }
      posAttr.needsUpdate = true;
    }
  });

  return (
    <group>
      {/* COLD AIR ARROWS (Blue/Cyan in Central Cold Aisle) */}
      {showArrows && (
        <group ref={coldArrowsGroup}>
          {coldArrowData.map((d, i) => (
            <group key={`cold-arr-${i}`} position={[d.x, d.baseY, d.baseZ]}>
              {createArrowMesh('#0ea5e9', '#0284c7')}
            </group>
          ))}
        </group>
      )}

      {/* HOT AIR ARROWS (Red/Orange in Hot Aisles behind server racks) */}
      {showArrows && (
        <group ref={hotArrowsGroup}>
          {hotArrowData.map((d, i) => (
            <group key={`hot-arr-${i}`} position={[d.x, d.baseY, d.z]}>
              {createArrowMesh('#ef4444', '#dc2626')}
            </group>
          ))}
        </group>
      )}

      {/* COLD PARTICLES DRIFT (Perforated floor upward stream) */}
      {showParticles && (
        <points ref={coldPointsRef}>
          <bufferGeometry>
            <bufferAttribute
              attach="attributes-position"
              args={[coldParticlePositions, 3]}
            />
          </bufferGeometry>
          <pointsMaterial
            size={0.06}
            color="#38bdf8"
            transparent
            opacity={0.65}
            blending={THREE.NormalBlending}
          />
        </points>
      )}

      {/* HOT PARTICLES DRIFT (Rack exhaust upward stream) */}
      {showParticles && (
        <points ref={hotPointsRef}>
          <bufferGeometry>
            <bufferAttribute
              attach="attributes-position"
              args={[hotParticlePositions, 3]}
            />
          </bufferGeometry>
          <pointsMaterial
            size={0.06}
            color="#f87171"
            transparent
            opacity={0.65}
            blending={THREE.NormalBlending}
          />
        </points>
      )}
    </group>
  );
};

sources.src/components/datacenter/AutomatedFault:
import React from 'react';
import {
  AlertTriangle,
  X,
  Wrench,
  CheckCircle,
  Wind,
  Activity,
  ArrowRight,
  ShieldAlert,
  RotateCcw
} from 'lucide-react';
import { useData } from '../../context/DataContext';

export const AutomatedFaultModal: React.FC = () => {
  const {
    activeCoolerFault,
    dismissCoolerFault,
    remediateCoolerFault,
    setSelectedMachineId,
  } = useData();

  if (!activeCoolerFault) return null;

  const isCritical = activeCoolerFault.severity === 'critical';

  return (
    <div className="fixed inset-0 z-[10000] flex items-center justify-center p-4 bg-slate-900/70 backdrop-blur-sm select-none animate-in fade-in duration-200">
      <div
        className="fixed inset-0"
        onClick={dismissCoolerFault}
      />

      <div className={`relative w-full max-w-lg bg-white rounded-xl shadow-2xl border-2 overflow-hidden z-10 flex flex-col ${
        isCritical ? 'border-rose-500' : 'border-amber-500'
      }`}>
        {/* Top Warning Banner Strip */}
        <div className={`p-4 flex items-center justify-between text-white ${
          isCritical ? 'bg-rose-600' : 'bg-amber-600'
        }`}>
          <div className="flex items-center gap-2.5">
            <div className="p-1.5 bg-white/20 rounded-md animate-pulse">
              <ShieldAlert className="w-5 h-5 text-white" />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <span className="font-mono text-[10px] tracking-wider uppercase font-bold bg-white/20 px-1.5 py-0.5 rounded">
                  AUTOMATED FAULT DETECTION
                </span>
                <span className="font-mono text-xs text-white/90">
                  {activeCoolerFault.code}
                </span>
              </div>
              <h3 className="font-bold text-sm tracking-tight mt-0.5">
                {activeCoolerFault.machineLabel}
              </h3>
            </div>
          </div>

          <button
            onClick={dismissCoolerFault}
            className="p-1 rounded-md text-white/80 hover:text-white hover:bg-white/20 transition-colors"
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        {/* Modal Body */}
        <div className="p-5 space-y-4 text-xs">
          {/* Fault Title & Anomaly description */}
          <div>
            <h4 className="font-bold text-slate-900 text-sm leading-snug">
              {activeCoolerFault.title}
            </h4>
            <p className="text-slate-600 mt-1 leading-relaxed">
              {activeCoolerFault.description}
            </p>
          </div>

          {/* Telemetric Breach Values Grid */}
          <div className="grid grid-cols-2 gap-2.5 p-3 rounded-lg bg-slate-50 border border-slate-200">
            <div>
              <span className="text-[10px] font-mono uppercase text-slate-400 block">
                MEASURED TELEMETRIC VALUE
              </span>
              <span className={`text-base font-bold font-mono ${
                isCritical ? 'text-rose-600' : 'text-amber-600'
              }`}>
                {activeCoolerFault.metricValue}
              </span>
            </div>
            <div>
              <span className="text-[10px] font-mono uppercase text-slate-400 block">
                SAFETY THRESHOLD TOLERANCE
              </span>
              <span className="text-base font-bold font-mono text-slate-700">
                {activeCoolerFault.thresholdValue}
              </span>
            </div>
          </div>

          {/* Recommended Remediation Action */}
          <div className="p-3 rounded-lg bg-blue-50/60 border border-blue-200 space-y-1">
            <span className="font-bold text-blue-950 font-mono text-[11px] uppercase tracking-wider flex items-center gap-1.5">
              <Wrench className="w-3.5 h-3.5 text-blue-600" />
              Automated Prescribed Action
            </span>
            <p className="text-blue-900 text-xs leading-relaxed">
              {activeCoolerFault.recommendedAction}
            </p>
          </div>

          {/* Action Buttons */}
          <div className="flex flex-col sm:flex-row items-center gap-2 pt-2 border-t border-slate-100">
            <button
              onClick={() => {
                remediateCoolerFault(activeCoolerFault.machineId);
              }}
              className="w-full sm:flex-1 flex items-center justify-center gap-1.5 px-3 py-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-md font-semibold text-xs transition-colors shadow-2xs"
            >
              <CheckCircle className="w-4 h-4" />
              <span>Auto-Remediate & Clear Fault</span>
            </button>

            <button
              onClick={() => {
                setSelectedMachineId(activeCoolerFault.machineId);
                dismissCoolerFault();
              }}
              className="w-full sm:w-auto flex items-center justify-center gap-1.5 px-3 py-2 bg-slate-100 hover:bg-slate-200 text-slate-800 rounded-md font-medium text-xs transition-colors"
            >
              <Activity className="w-3.5 h-3.5 text-slate-500" />
              <span>Machine Diagnostics</span>
            </button>

            <button
              onClick={dismissCoolerFault}
              className="w-full sm:w-auto px-3 py-2 text-slate-500 hover:text-slate-700 text-xs transition-colors"
            >
              Acknowledge
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

sources.src/components/datacenter/CoolingPipe.ts:
import React from 'react';
import * as THREE from 'three';

interface CoolingPipeProps {
  showPipes?: boolean;
}

export const CoolingPipe: React.FC<CoolingPipeProps> = ({ showPipes = true }) => {
  if (!showPipes) return null;

  const pipeLength = 17.0;
  const supplyPipeRadius = 0.08;
  const returnPipeRadius = 0.08;
  const supplyY = 3.4;
  const returnY = 3.65;

  return (
    <group>
      {/* --- CHILLED WATER SUPPLY PIPE (Overhead, Light Cyan/Blue) --- */}
      <group position={[0, supplyY, -0.6]}>
        {/* Main horizontal header pipe */}
        <mesh rotation={[0, 0, Math.PI / 2]}>
          <cylinderGeometry args={[supplyPipeRadius, supplyPipeRadius, pipeLength, 20]} />
          <meshStandardMaterial
            color="#38bdf8"
            roughness={0.25}
            metalness={0.7}
          />
        </mesh>

        {/* Flanges along pipe */}
        {[-6, -3, 0, 3, 6].map((fx, i) => (
          <mesh key={i} position={[fx, 0, 0]} rotation={[0, 0, Math.PI / 2]}>
            <cylinderGeometry args={[supplyPipeRadius * 1.35, supplyPipeRadius * 1.35, 0.04, 16]} />
            <meshStandardMaterial color="#0284c7" roughness={0.4} metalness={0.8} />
          </mesh>
        ))}

        {/* Directional Flow Arrow Decals on pipe */}
        {[-4, 0, 4].map((ax, i) => (
          <mesh key={`flow-${i}`} position={[ax, supplyPipeRadius + 0.01, 0]}>
            <boxGeometry args={[0.2, 0.005, 0.06]} />
            <meshBasicMaterial color="#ffffff" />
          </mesh>
        ))}
      </group>

      {/* --- WARM WATER RETURN PIPE (Overhead, Warm Bronze/Amber) --- */}
      <group position={[0, returnY, 0.6]}>
        {/* Main horizontal header pipe */}
        <mesh rotation={[0, 0, Math.PI / 2]}>
          <cylinderGeometry args={[returnPipeRadius, returnPipeRadius, pipeLength, 20]} />
          <meshStandardMaterial
            color="#fb923c"
            roughness={0.25}
            metalness={0.7}
          />
        </mesh>

        {/* Flanges along pipe */}
        {[-6, -3, 0, 3, 6].map((fx, i) => (
          <mesh key={i} position={[fx, 0, 0]} rotation={[0, 0, Math.PI / 2]}>
            <cylinderGeometry args={[returnPipeRadius * 1.35, returnPipeRadius * 1.35, 0.04, 16]} />
            <meshStandardMaterial color="#ea580c" roughness={0.4} metalness={0.8} />
          </mesh>
        ))}
      </group>

      {/* --- VERTICAL PIPE DROPS DOWN TO CRAC UNITS --- */}
      {/* North CRAC Drop (X = -7.5) */}
      <group position={[-7.5, 0, 0]}>
        {/* Supply drop */}
        <mesh position={[0.3, (supplyY + 2.7) / 2, -0.6]}>
          <cylinderGeometry args={[0.06, 0.06, supplyY - 2.7, 16]} />
          <meshStandardMaterial color="#38bdf8" roughness={0.3} metalness={0.7} />
        </mesh>
        {/* Return drop */}
        <mesh position={[-0.3, (returnY + 2.7) / 2, 0.6]}>
          <cylinderGeometry args={[0.06, 0.06, returnY - 2.7, 16]} />
          <meshStandardMaterial color="#fb923c" roughness={0.3} metalness={0.7} />
        </mesh>
      </group>

      {/* South CRAC Drop (X = 7.5) */}
      <group position={[7.5, 0, 0]}>
        {/* Supply drop */}
        <mesh position={[0.3, (supplyY + 2.7) / 2, -0.6]}>
          <cylinderGeometry args={[0.06, 0.06, supplyY - 2.7, 16]} />
          <meshStandardMaterial color="#38bdf8" roughness={0.3} metalness={0.7} />
        </mesh>
        {/* Return drop */}
        <mesh position={[-0.3, (returnY + 2.7) / 2, 0.6]}>
          <cylinderGeometry args={[0.06, 0.06, returnY - 2.7, 16]} />
          <meshStandardMaterial color="#fb923c" roughness={0.3} metalness={0.7} />
        </mesh>
      </group>

      {/* --- CEILING SUSPENSION UNISTRUT HANGERS --- */}
      {[-6, -2, 2, 6].map((hx, i) => (
        <group key={`hanger-${i}`} position={[hx, 3.8, 0]}>
          {/* Ceiling cross strut beam */}
          <mesh position={[0, 0.1, 0]}>
            <boxGeometry args={[0.08, 0.06, 2.0]} />
            <meshStandardMaterial color="#94a3b8" roughness={0.6} metalness={0.5} />
          </mesh>
          {/* Threaded suspension rods */}
          <mesh position={[0, -0.2, -0.6]}>
            <cylinderGeometry args={[0.01, 0.01, 0.5, 8]} />
            <meshStandardMaterial color="#cbd5e1" metalness={0.8} />
          </mesh>
          <mesh position={[0, -0.2, 0.6]}>
            <cylinderGeometry args={[0.01, 0.01, 0.5, 8]} />
            <meshStandardMaterial color="#cbd5e1" metalness={0.8} />
          </mesh>
        </group>
      ))}
    </group>
  );
};

