import React, { useRef, useState } from 'react';
import * as THREE from 'three';
import { useFrame } from '@react-three/fiber';
import { Html } from '@react-three/drei';
import { CRACUnitData } from '../../types';

interface CRACUnitProps {
  data: CRACUnitData;
  showLabels?: boolean;
  onSelect?: (machineId: string) => void;
}

export const CRACUnit: React.FC<CRACUnitProps> = ({
  data,
  showLabels = true,
  onSelect,
}) => {
  const fan1Ref = useRef<THREE.Group>(null);
  const fan2Ref = useRef<THREE.Group>(null);
  const beaconGlowRef = useRef<THREE.Mesh>(null);
  const [isHovered, setIsHovered] = useState(false);

  const isFaulted = data.health !== 'healthy' || !!data.activeFault;
  const isCritical = data.health === 'critical' || data.activeFault?.severity === 'critical';

  // Smooth continuous rotation of internal EC fan impellers
  useFrame((_, delta) => {
    const dt = Math.min(delta, 0.1);
    const speedFactor = data.fanStatus === 'running' ? (data.fanSpeedRpm / 60) * Math.PI * 2 : 0;

    if (fan1Ref.current && speedFactor > 0) {
      fan1Ref.current.rotation.z += speedFactor * dt * 0.4;
    }
    if (fan2Ref.current && speedFactor > 0) {
      fan2Ref.current.rotation.z += speedFactor * dt * 0.4;
    }

    // Pulse beacon light when machine is faulted
    if (beaconGlowRef.current && isFaulted) {
      const s = 1 + Math.sin(Date.now() * 0.008) * 0.28;
      beaconGlowRef.current.scale.set(s, s, s);
    }
  });

  const width = 1.6;
  const height = 2.8;
  const depth = 1.35;

  return (
    <group
      position={data.position}
      rotation={[0, data.rotationY || 0, 0]}
      onClick={(e) => {
        e.stopPropagation();
        onSelect?.(data.id);
      }}
      onPointerOver={(e) => {
        e.stopPropagation();
        setIsHovered(true);
      }}
      onPointerOut={() => setIsHovered(false)}
    >
      {/* Interactive Selection / Hover Wireframe Halo */}
      {isHovered && (
        <group position={[0, height / 2 + 0.1, 0]}>
          <lineSegments>
            <edgesGeometry args={[new THREE.BoxGeometry(width + 0.12, height + 0.22, depth + 0.12)]} />
            <lineBasicMaterial color={isFaulted ? '#ef4444' : '#0284c7'} linewidth={1.5} />
          </lineSegments>
        </group>
      )}

      {/* =========================================================================
          1. HEAVY STRUCTURAL STEEL C-CHANNEL SKID BASE (Gunmetal Steel)
          ========================================================================= */}
      <group position={[0, 0.08, 0]}>
        {/* Main Channel Steel Skid Box */}
        <mesh castShadow receiveShadow>
          <boxGeometry args={[width + 0.04, 0.16, depth + 0.04]} />
          <meshStandardMaterial color="#1e293b" roughness={0.3} metalness={0.7} />
        </mesh>

        {/* Forklift Tine Pockets (Through Base - Precision Industrial Feature) */}
        {[-0.38, 0.38].map((fx, i) => (
          <group key={`fork-pocket-${i}`} position={[fx, 0, 0]}>
            <mesh>
              <boxGeometry args={[0.22, 0.08, depth + 0.06]} />
              <meshStandardMaterial color="#090d16" roughness={0.9} metalness={0.2} />
            </mesh>
            {/* Safety Yellow Outline around Forklift Entry */}
            <mesh position={[0, 0, depth / 2 + 0.032]}>
              <planeGeometry args={[0.26, 0.1]} />
              <meshBasicMaterial color="#facc15" />
            </mesh>
            <mesh position={[0, 0, depth / 2 + 0.033]}>
              <planeGeometry args={[0.22, 0.08]} />
              <meshBasicMaterial color="#090d16" />
            </mesh>
          </group>
        ))}

        {/* 4 Heavy-Duty Neoprene Vibration Dampening Isolation Leveling Feet */}
        {[
          [-width / 2 + 0.1, -depth / 2 + 0.1],
          [width / 2 - 0.1, -depth / 2 + 0.1],
          [-width / 2 + 0.1, depth / 2 - 0.1],
          [width / 2 - 0.1, depth / 2 - 0.1],
        ].map(([px, pz], i) => (
          <group key={`foot-${i}`} position={[px, -0.06, pz]}>
            {/* Steel Leveling Base Foot */}
            <mesh>
              <cylinderGeometry args={[0.075, 0.085, 0.06, 16]} />
              <meshStandardMaterial color="#475569" roughness={0.25} metalness={0.7} />
            </mesh>
            {/* Gold Zinc Plated Threaded Leveling Stud */}
            <mesh position={[0, 0.05, 0]}>
              <cylinderGeometry args={[0.016, 0.016, 0.06, 8]} />
              <meshStandardMaterial color="#f59e0b" roughness={0.2} metalness={0.9} />
            </mesh>
            {/* Black Neoprene Acoustic Isolation Pad */}
            <mesh position={[0, -0.035, 0]}>
              <cylinderGeometry args={[0.09, 0.09, 0.02, 16]} />
              <meshStandardMaterial color="#090d16" roughness={0.95} />
            </mesh>
          </group>
        ))}
      </group>

      {/* =========================================================================
          2. MAIN INDUSTRIAL MACHINE HOUSING CABINET (RAL 7035 Light Grey Enamel)
          ========================================================================= */}
      {/* Light Platinum Machine Enamel Body */}
      <mesh position={[0, height / 2 + 0.16, 0]} castShadow receiveShadow>
        <boxGeometry args={[width, height - 0.16, depth]} />
        <meshStandardMaterial
          color="#e2e8f0"
          roughness={0.28}
          metalness={0.45}
        />
      </mesh>

      {/* Heavy-Gauge Anodized Aluminum Structural Corner Posts (Vertical Beams) */}
      {[
        [-width / 2 + 0.03, -depth / 2 + 0.03],
        [width / 2 - 0.03, -depth / 2 + 0.03],
        [-width / 2 + 0.03, depth / 2 - 0.03],
        [width / 2 - 0.03, depth / 2 - 0.03],
      ].map(([cx, cz], i) => (
        <mesh key={`post-${i}`} position={[cx, height / 2 + 0.16, cz]}>
          <boxGeometry args={[0.07, height - 0.15, 0.07]} />
          <meshStandardMaterial color="#64748b" roughness={0.2} metalness={0.75} />
        </mesh>
      ))}

      {/* Top Roof Cover Cap with Machined Bevel */}
      <mesh position={[0, height + 0.09, 0]}>
        <boxGeometry args={[width + 0.02, 0.05, depth + 0.02]} />
        <meshStandardMaterial color="#cbd5e1" roughness={0.22} metalness={0.65} />
      </mesh>

      {/* 4 Forged Chrome Lifting Eyelet Rings on Roof Corners */}
      {[
        [-width / 2 + 0.14, -depth / 2 + 0.14],
        [width / 2 - 0.14, -depth / 2 + 0.14],
        [-width / 2 + 0.14, depth / 2 - 0.14],
        [width / 2 - 0.14, depth / 2 - 0.14],
      ].map(([ex, ez], i) => (
        <mesh key={`eyelet-${i}`} position={[ex, height + 0.14, ez]} rotation={[0, 0, Math.PI / 2]}>
          <torusGeometry args={[0.036, 0.011, 12, 24]} />
          <meshStandardMaterial color="#ffffff" roughness={0.1} metalness={0.95} />
        </mesh>
      ))}

      {/* =========================================================================
          3. FRONT FACE (+Z): DUAL SPLIT ACCESS DOORS, LOUVERS, HMI, E-STOP
          ========================================================================= */}
      <group position={[0, 0, depth / 2 + 0.008]}>
        {/* Perimeter Acoustic EPDM Rubber Seal Gasket Bead */}
        <mesh position={[0, height / 2 + 0.14, 0]}>
          <planeGeometry args={[width * 0.94, height * 0.88]} />
          <meshStandardMaterial color="#090d16" roughness={0.95} />
        </mesh>

        {/* Dual Hinged Brushed Stainless Steel Service Access Doors */}
        {[-width * 0.235, width * 0.235].map((dx, i) => (
          <group key={`door-${i}`} position={[dx, height / 2 + 0.14, 0.008]}>
            {/* Door Panel */}
            <mesh>
              <boxGeometry args={[width * 0.45, height * 0.86, 0.018]} />
              <meshStandardMaterial color="#f8fafc" roughness={0.2} metalness={0.4} />
            </mesh>

            {/* Industrial Flush Chrome Paddle Latch with Key Lock */}
            <group position={[i === 0 ? width * 0.18 : -width * 0.18, 0, 0.013]}>
              <mesh>
                <boxGeometry args={[0.032, 0.15, 0.012]} />
                <meshStandardMaterial color="#ffffff" roughness={0.06} metalness={0.98} />
              </mesh>
              <mesh position={[0, 0.04, 0.007]}>
                <cylinderGeometry args={[0.007, 0.007, 0.006, 8]} />
                <meshStandardMaterial color="#090d16" roughness={0.3} metalness={0.9} />
              </mesh>
            </group>

            {/* Lower Door Stiffening Relief Press Ribs */}
            {[-0.55, -0.7, -0.85].map((ry, idx) => (
              <mesh key={`rib-${idx}`} position={[0, ry, 0.01]}>
                <boxGeometry args={[width * 0.38, 0.02, 0.006]} />
                <meshStandardMaterial color="#cbd5e1" roughness={0.25} metalness={0.6} />
              </mesh>
            ))}
          </group>
        ))}

        {/* Laser-Etched Brushed Stainless Steel Equipment Nameplate Tag */}
        <group position={[0, height * 0.92, 0.022]}>
          <mesh>
            <boxGeometry args={[0.62, 0.1, 0.006]} />
            <meshStandardMaterial color="#475569" roughness={0.2} metalness={0.8} />
          </mesh>
          <mesh position={[0, 0, 0.004]}>
            <planeGeometry args={[0.58, 0.07]} />
            <meshBasicMaterial color="#0f172a" />
          </mesh>
        </group>

        {/* INTAKE LOUVER CHAMBER (Upper Section) */}
        <group position={[0, height * 0.68, 0.02]}>
          {/* Dark Pleated Air Filter Backing Mat */}
          <mesh position={[0, 0, -0.004]}>
            <planeGeometry args={[width * 0.82, 0.68]} />
            <meshStandardMaterial color="#090d16" roughness={0.9} />
          </mesh>

          {/* Aerodynamic Extruded Aluminum Slanted Louver Blades */}
          {[-0.28, -0.20, -0.12, -0.04, 0.04, 0.12, 0.20, 0.28].map((ly, i) => (
            <mesh key={`louver-${i}`} position={[0, ly, 0.008]} rotation={[0.48, 0, 0]}>
              <boxGeometry args={[width * 0.84, 0.03, 0.022]} />
              <meshStandardMaterial color="#ffffff" roughness={0.16} metalness={0.85} />
            </mesh>
          ))}

          {/* Louver Mounting Frame with 4 Hex Screws */}
          {[
            [-width * 0.4, 0.32],
            [width * 0.4, 0.32],
            [-width * 0.4, -0.32],
            [width * 0.4, -0.32],
          ].map(([hx, hy], idx) => (
            <mesh key={`screw-${idx}`} position={[hx, hy, 0.012]}>
              <cylinderGeometry args={[0.01, 0.01, 0.008, 6]} />
              <meshStandardMaterial color="#94a3b8" roughness={0.1} metalness={0.9} />
            </mesh>
          ))}
        </group>

        {/* VISIBLE DUAL EC CENTRIFUGAL IMPELLER FANS (Inside Behind Louvers) */}
        <group position={[0, height * 0.68, -0.1]}>
          {/* Left Fan */}
          <group position={[-width * 0.22, 0, 0]}>
            <mesh rotation={[Math.PI / 2, 0, 0]}>
              <cylinderGeometry args={[0.11, 0.11, 0.14, 16]} />
              <meshStandardMaterial color="#1e293b" roughness={0.3} metalness={0.8} />
            </mesh>
            <group ref={fan1Ref}>
              {[0, 60, 120, 180, 240, 300].map((deg) => (
                <mesh key={`b1-${deg}`} rotation={[0, 0, (deg * Math.PI) / 180]} position={[0, 0, 0.04]}>
                  <boxGeometry args={[0.032, 0.24, 0.008]} />
                  <meshStandardMaterial color="#0284c7" roughness={0.2} metalness={0.85} />
                </mesh>
              ))}
            </group>
          </group>

          {/* Right Fan */}
          <group position={[width * 0.22, 0, 0]}>
            <mesh rotation={[Math.PI / 2, 0, 0]}>
              <cylinderGeometry args={[0.11, 0.11, 0.14, 16]} />
              <meshStandardMaterial color="#1e293b" roughness={0.3} metalness={0.8} />
            </mesh>
            <group ref={fan2Ref}>
              {[0, 60, 120, 180, 240, 300].map((deg) => (
                <mesh key={`b2-${deg}`} rotation={[0, 0, (deg * Math.PI) / 180]} position={[0, 0, 0.04]}>
                  <boxGeometry args={[0.032, 0.24, 0.008]} />
                  <meshStandardMaterial color="#0284c7" roughness={0.2} metalness={0.85} />
                </mesh>
              ))}
            </group>
          </group>
        </group>

        {/* INDUSTRIAL DIGITAL OPERATOR HMI CONSOLE (Center Panel) */}
        <group position={[0, height * 0.42, 0.024]}>
          {/* Deep Anodized Aluminum Enclosure Bezel */}
          <mesh>
            <boxGeometry args={[0.56, 0.36, 0.024]} />
            <meshStandardMaterial color="#0f172a" roughness={0.2} metalness={0.85} />
          </mesh>

          {/* Active Backlit LCD Screen */}
          <mesh position={[0, 0.03, 0.013]}>
            <planeGeometry args={[0.48, 0.24]} />
            <meshBasicMaterial color={isFaulted ? '#dc2626' : '#0284c7'} />
          </mesh>

          {/* Screen Inner Graphical Telemetry Simulation Lines */}
          <group position={[0, 0.03, 0.014]}>
            <mesh position={[0, 0.07, 0]}>
              <planeGeometry args={[0.42, 0.025]} />
              <meshBasicMaterial color={isFaulted ? '#fee2e2' : '#e0f2fe'} />
            </mesh>
            <mesh position={[-0.1, 0.01, 0]}>
              <planeGeometry args={[0.18, 0.045]} />
              <meshBasicMaterial color={isFaulted ? '#991b1b' : '#0369a1'} />
            </mesh>
            <mesh position={[0.1, 0.01, 0]}>
              <planeGeometry args={[0.18, 0.045]} />
              <meshBasicMaterial color={isFaulted ? '#991b1b' : '#0369a1'} />
            </mesh>
          </group>

          {/* Status Indicator LEDs (Green, Yellow, Red) */}
          {[-0.18, -0.12, -0.06].map((lx, idx) => (
            <mesh key={`led-${idx}`} position={[lx, -0.11, 0.014]}>
              <circleGeometry args={[0.01, 12]} />
              <meshBasicMaterial
                color={
                  idx === 0
                    ? !isFaulted ? '#10b981' : '#064e3b'
                    : idx === 1
                    ? isFaulted && !isCritical ? '#f59e0b' : '#78350f'
                    : isCritical ? '#ef4444' : '#7f1d1d'
                }
              />
            </mesh>
          ))}

          {/* Membrane Control Buttons */}
          {[0.04, 0.12, 0.20].map((bx, idx) => (
            <mesh key={`btn-${idx}`} position={[bx, -0.11, 0.014]}>
              <boxGeometry args={[0.05, 0.024, 0.005]} />
              <meshStandardMaterial color="#475569" roughness={0.3} metalness={0.6} />
            </mesh>
          ))}
        </group>

        {/* INDUSTRIAL EMERGENCY STOP (E-STOP) MUSHROOM BUTTON — CLASSIC MACHINERY FEATURE */}
        <group position={[width * 0.32, height * 0.42, 0.024]}>
          {/* Bright Yellow Circular Safety Collar Plate */}
          <mesh>
            <cylinderGeometry args={[0.05, 0.05, 0.01, 16]} />
            <meshBasicMaterial color="#facc15" />
          </mesh>
          {/* Black Collar Ring */}
          <mesh position={[0, 0, 0.008]}>
            <cylinderGeometry args={[0.038, 0.038, 0.012, 16]} />
            <meshStandardMaterial color="#090d16" roughness={0.8} />
          </mesh>
          {/* Red Mushroom E-Stop Button Cap */}
          <mesh position={[0, 0, 0.02]}>
            <cylinderGeometry args={[0.032, 0.028, 0.02, 16]} />
            <meshStandardMaterial color="#dc2626" roughness={0.2} metalness={0.3} />
          </mesh>
        </group>

        {/* AUTHENTIC INDUSTRIAL WARNING & SAFETY PLACARDS (Lower Section) */}
        {/* ISO 480V 3-Phase Electrical Hazard Decal (Yellow Triangle) */}
        <group position={[-width * 0.24, height * 0.22, 0.02]}>
          <mesh>
            <planeGeometry args={[0.2, 0.1]} />
            <meshBasicMaterial color="#facc15" />
          </mesh>
          <mesh position={[0, 0, 0.002]}>
            <planeGeometry args={[0.18, 0.08]} />
            <meshBasicMaterial color="#090d16" />
          </mesh>
          {/* Yellow Lightning Triangle Center */}
          <mesh position={[0, 0, 0.004]}>
            <planeGeometry args={[0.09, 0.05]} />
            <meshBasicMaterial color="#facc15" />
          </mesh>
        </group>

        {/* Refrigerant & Chilled Water Identification Placard (Blue / White) */}
        <group position={[width * 0.24, height * 0.22, 0.02]}>
          <mesh>
            <planeGeometry args={[0.2, 0.1]} />
            <meshBasicMaterial color="#0284c7" />
          </mesh>
          <mesh position={[0, 0, 0.002]}>
            <planeGeometry args={[0.18, 0.08]} />
            <meshBasicMaterial color="#f8fafc" />
          </mesh>
          <mesh position={[0, 0, 0.004]}>
            <planeGeometry args={[0.14, 0.03]} />
            <meshBasicMaterial color="#0284c7" />
          </mesh>
        </group>
      </group>

      {/* =========================================================================
          4. SIDE PANELS (-X & +X): FILTER ACCESS DOORS, VENTS, LIFTING BRACKETS
          ========================================================================= */}
      {/* Left Side Panel (-X) */}
      <group position={[-width / 2 - 0.006, height / 2 + 0.16, 0]} rotation={[0, -Math.PI / 2, 0]}>
        {/* Recessed Maintenance Access Seam */}
        <mesh>
          <planeGeometry args={[depth * 0.82, height * 0.82]} />
          <meshStandardMaterial color="#cbd5e1" roughness={0.25} metalness={0.5} />
        </mesh>
        {/* Upper Cooling Exhaust Slit Louvers */}
        {[-0.2, -0.1, 0, 0.1, 0.2].map((sy, i) => (
          <mesh key={`side-louver-${i}`} position={[0, height * 0.25 + sy, 0.005]}>
            <boxGeometry args={[depth * 0.6, 0.02, 0.008]} />
            <meshStandardMaterial color="#64748b" roughness={0.3} metalness={0.7} />
          </mesh>
        ))}
        {/* Stainless Steel Hex Bolts along Panel Edge */}
        {[-depth * 0.38, depth * 0.38].map((sx, idx) => (
          <mesh key={`bolt-l-${idx}`} position={[sx, 0, 0.008]}>
            <cylinderGeometry args={[0.012, 0.012, 0.008, 6]} />
            <meshStandardMaterial color="#ffffff" roughness={0.1} metalness={0.9} />
          </mesh>
        ))}
      </group>

      {/* Right Side Panel (+X) */}
      <group position={[width / 2 + 0.006, height / 2 + 0.16, 0]} rotation={[0, Math.PI / 2, 0]}>
        <mesh>
          <planeGeometry args={[depth * 0.82, height * 0.82]} />
          <meshStandardMaterial color="#cbd5e1" roughness={0.25} metalness={0.5} />
        </mesh>
        {/* Side Vents */}
        {[-0.2, -0.1, 0, 0.1, 0.2].map((sy, i) => (
          <mesh key={`side-louver-r-${i}`} position={[0, height * 0.25 + sy, 0.005]}>
            <boxGeometry args={[depth * 0.6, 0.02, 0.008]} />
            <meshStandardMaterial color="#64748b" roughness={0.3} metalness={0.7} />
          </mesh>
        ))}
        {/* Hex Fasteners */}
        {[-depth * 0.38, depth * 0.38].map((sx, idx) => (
          <mesh key={`bolt-r-${idx}`} position={[sx, 0, 0.008]}>
            <cylinderGeometry args={[0.012, 0.012, 0.008, 6]} />
            <meshStandardMaterial color="#ffffff" roughness={0.1} metalness={0.9} />
          </mesh>
        ))}
      </group>

      {/* =========================================================================
          5. REAR PANEL (-Z): CHILLED WATER MANIFOLD, GAUGES, JUNCTION BOX
          ========================================================================= */}
      <group position={[0, height / 2 + 0.16, -depth / 2 - 0.006]} rotation={[0, Math.PI, 0]}>
        {/* Rear Heavy Sheet Metal Access Panel */}
        <mesh>
          <planeGeometry args={[width * 0.9, height * 0.84]} />
          <meshStandardMaterial color="#cbd5e1" roughness={0.25} metalness={0.55} />
        </mesh>

        {/* High Voltage Electrical Conduit Junction Box */}
        <group position={[-width * 0.28, -height * 0.18, 0.05]}>
          <mesh>
            <boxGeometry args={[0.26, 0.32, 0.1]} />
            <meshStandardMaterial color="#475569" roughness={0.25} metalness={0.75} />
          </mesh>
          {/* Metallic Flexible Conduit Hose */}
          <mesh position={[0, -0.22, 0]}>
            <cylinderGeometry args={[0.025, 0.025, 0.16, 12]} />
            <meshStandardMaterial color="#94a3b8" roughness={0.2} metalness={0.9} />
          </mesh>
        </group>
      </group>

      {/* =========================================================================
          6. TOP DISCHARGE PLENUM, WIRE MESH FAN GUARD & PIPING CONNECTIONS
          ========================================================================= */}
      {/* Top Raised Air Discharge Collar Plenum */}
      <group position={[0, height + 0.16, 0]}>
        <mesh>
          <boxGeometry args={[width * 0.88, 0.12, depth * 0.88]} />
