          <meshStandardMaterial color="#ea580c" roughness={0.15} metalness={0.95} />
        </mesh>
        <mesh position={[0.35, 0.24, -0.18]}>
          <cylinderGeometry args={[0.022, 0.022, 0.38, 12]} />
          <meshStandardMaterial color="#ea580c" roughness={0.15} metalness={0.95} />
        </mesh>
      </group>

      {/* =========================================================================
          8. INDUSTRIAL 3-TIER STACK LIGHT SIGNAL BEACON TOWER (Patlite Style)
          ========================================================================= */}
      <group position={[width / 2 - 0.18, height + 0.12, depth / 2 - 0.18]}>
        {/* Polished Stainless Steel Stem */}
        <mesh position={[0, 0.1, 0]}>
          <cylinderGeometry args={[0.016, 0.016, 0.2, 12]} />
          <meshStandardMaterial color="#ffffff" roughness={0.1} metalness={0.95} />
        </mesh>

        {/* Tier 1: Green Tier (Normal Operation) */}
        <mesh position={[0, 0.23, 0]}>
          <cylinderGeometry args={[0.036, 0.036, 0.055, 16]} />
          <meshStandardMaterial
            color="#10b981"
            emissive={!isFaulted ? '#059669' : '#064e3b'}
            emissiveIntensity={!isFaulted ? 1.0 : 0.2}
            roughness={0.2}
          />
        </mesh>

        {/* Tier 2: Amber Tier (Warning / Standby) */}
        <mesh position={[0, 0.295, 0]}>
          <cylinderGeometry args={[0.036, 0.036, 0.055, 16]} />
          <meshStandardMaterial
            color="#f59e0b"
            emissive={isFaulted && !isCritical ? '#d97706' : '#78350f'}
            emissiveIntensity={isFaulted && !isCritical ? 1.2 : 0.2}
            roughness={0.2}
          />
        </mesh>

        {/* Tier 3: Red Tier (Critical Alarm) */}
        <mesh position={[0, 0.36, 0]}>
          <cylinderGeometry args={[0.036, 0.036, 0.055, 16]} />
          <meshStandardMaterial
            color="#ef4444"
            emissive={isCritical ? '#dc2626' : '#7f1d1d'}
            emissiveIntensity={isCritical ? 1.4 : 0.2}
            roughness={0.2}
          />
        </mesh>

        {/* Pulsing Light Halo when Faulted */}
        {isFaulted && (
          <mesh ref={beaconGlowRef} position={[0, 0.36, 0]}>
            <sphereGeometry args={[0.14, 16, 16]} />
            <meshBasicMaterial
              color={isCritical ? '#ff4d4d' : '#fbbf24'}
              transparent
              opacity={0.35}
            />
          </mesh>
        )}
      </group>

      {/* =========================================================================
          9. AUTOMATIC CRAC FAULT NOTIFICATION BADGE
          ========================================================================= */}
      {showLabels && data.activeFault && (
        <Html
          position={[0, height + 0.58, 0]}
          center
          distanceFactor={34}
          zIndexRange={[10, 0]}
          className="pointer-events-auto select-none"
        >
          <div
            onClick={(e) => {
              e.stopPropagation();
              onSelect?.(data.id);
            }}
            className="cursor-pointer bg-rose-600 text-white border border-rose-300 px-2 py-1 rounded shadow-lg flex items-center gap-1.5 animate-bounce hover:scale-105 transition-transform"
          >
            <span className="w-1.5 h-1.5 rounded-full bg-white animate-ping" />
            <div className="flex flex-col text-left">
              <span className="font-mono text-[8px] uppercase font-bold text-rose-200">
                CRAC FAULT • {data.activeFault.code}
              </span>
              <span className="text-[10px] font-bold whitespace-nowrap">
                {data.activeFault.title}
              </span>
            </div>
          </div>
        </Html>
      )}

      {/* =========================================================================
          10. SLEEK MACHINE TELEMETRY PILL (COMPACT, NON-OVERLAPPING)
          ========================================================================= */}
      {showLabels && !data.activeFault && (
        <Html
          position={[0, height + 0.24, 0]}
          center
          distanceFactor={36}
          zIndexRange={[10, 0]}
          className="pointer-events-none select-none"
        >
          <div
            className={`border px-2 py-0.5 rounded-full text-[9px] font-mono whitespace-nowrap shadow-xs flex items-center gap-1.5 ${
              isFaulted
                ? 'bg-rose-950/90 text-rose-100 border-rose-600'
                : 'bg-slate-900/90 text-slate-100 border-slate-700'
            }`}
          >
            <span
              className={`w-1.5 h-1.5 rounded-full ${
                isFaulted ? 'bg-rose-500 animate-ping' : 'bg-emerald-400 animate-pulse'
              }`}
            />
            <span className="font-bold text-white">{data.label}</span>
            <span className="text-slate-400">| {data.supplyTempC}°C</span>
          </div>
        </Html>
      )}
    </group>
  );
};

