import React, { Suspense, useRef, useState, useEffect } from 'react';
import { Canvas, useThree } from '@react-three/fiber';
import { OrbitControls, ContactShadows, Html } from '@react-three/drei';
import * as THREE from 'three';
import type { OrbitControls as OrbitControlsImpl } from 'three-stdlib';
import { useData } from '../../context/DataContext';
import { ServerRack } from './ServerRack';
import { CRACUnit } from './CRACUnit';
import { CoolingPipe } from './CoolingPipe';
import { FloorTiles } from './FloorTiles';
import { Airflow } from './Airflow';
import { SceneControls } from './SceneControls';
import { ThermalLegend } from './ThermalLegend';
import { Maximize2, Minimize2, Loader2, AlertCircle } from 'lucide-react';

interface DataCenterSceneProps {
  isExpanded?: boolean;
  onToggleExpand?: () => void;
  heightClass?: string;
}

// Camera Helper to handle smooth camera presets
const CameraHandler: React.FC<{
  cameraPreset: 'isometric' | 'coldAisle' | 'hotAisle' | 'topDown' | 'coolerFocus' | null;
  onResetComplete: () => void;
  controlsRef: React.RefObject<OrbitControlsImpl | null>;
}> = ({ cameraPreset, onResetComplete, controlsRef }) => {
  const { camera } = useThree();

  useEffect(() => {
    if (!cameraPreset) return;

    if (cameraPreset === 'isometric') {
      camera.position.set(11, 8.5, 12);
      if (controlsRef.current) {
        controlsRef.current.target.set(0, 1.2, 0);
        controlsRef.current.update();
      }
    } else if (cameraPreset === 'coldAisle') {
      camera.position.set(0, 1.7, 5.0);
      if (controlsRef.current) {
        controlsRef.current.target.set(0, 1.2, -0.5);
        controlsRef.current.update();
      }
    } else if (cameraPreset === 'hotAisle') {
      camera.position.set(0, 2.2, -5.5);
      if (controlsRef.current) {
        controlsRef.current.target.set(0, 1.2, -2.2);
        controlsRef.current.update();
      }
    } else if (cameraPreset === 'topDown') {
      camera.position.set(0, 16.5, 0.01);
      if (controlsRef.current) {
        controlsRef.current.target.set(0, 0, 0);
        controlsRef.current.update();
      }
    } else if (cameraPreset === 'coolerFocus') {
      camera.position.set(-5.0, 2.0, 2.0);
      if (controlsRef.current) {
        controlsRef.current.target.set(-7.8, 1.4, 0);
        controlsRef.current.update();
      }
    }

    onResetComplete();
  }, [cameraPreset, camera, controlsRef, onResetComplete]);

  return null;
};

// Tooltip overlay element
const HoverTooltip: React.FC<{
  rackId: string | null;
  racks: ReturnType<typeof useData>['racks'];
  tempUnit: 'C' | 'F';
}> = ({ rackId, racks, tempUnit }) => {
  if (!rackId) return null;
  const rack = racks.find((r) => r.id === rackId);
  if (!rack) return null;

  return (
    <div className="absolute top-4 left-4 z-10 pointer-events-none bg-slate-900/90 backdrop-blur-md text-white text-xs px-3 py-2 rounded-lg shadow-lg border border-slate-700 font-mono space-y-1">
      <div className="flex items-center gap-2">
        <span
          className={`w-2 h-2 rounded-full ${
            rack.health === 'critical'
              ? 'bg-rose-500'
              : rack.health === 'warning'
              ? 'bg-amber-500'
              : 'bg-emerald-500'
          }`}
        />
        <span className="font-bold">{rack.label}</span>
        <span className="text-slate-400">({rack.tenant})</span>
      </div>
      <div className="text-[11px] text-slate-300 flex items-center gap-3">
        <span>Temp: {tempUnit === 'C' ? `${rack.tempC}°C` : `${((rack.tempC * 9) / 5 + 32).toFixed(1)}°F`}</span>
        <span>Power: {rack.powerKw.toFixed(1)} kW</span>
        <span>Storage: {rack.storageUtil}%</span>
      </div>
      {rack.risk && (
        <div className="text-[10px] text-amber-300 font-sans border-t border-slate-700 pt-1">
          ⚠️ {rack.risk.metric.toUpperCase()} Risk: {rack.risk.daysToExhaustion} days to limit
        </div>
      )}
    </div>
  );
};

export const DataCenterScene: React.FC<DataCenterSceneProps> = ({
  isExpanded = false,
  onToggleExpand,
  heightClass = 'h-[520px]',
}) => {
  const {
    filteredRacks,
    cracUnits,
    selectedRackId,
    setSelectedRackId,
    selectedMachineId,
    setSelectedMachineId,
    activeCoolerFault,
    hoveredRackId,
    setHoveredRackId,
    sceneMode,
    setSceneMode,
    isAirflowPlaying,
    setIsAirflowPlaying,
    settings,
    updateSettings,
  } = useData();

  // Completely hide background 3D HTML labels when any modal is open to prevent bleed-through
  const isAnyModalOpen = Boolean(selectedMachineId || activeCoolerFault);
  const shouldShowLabels = settings.showLabels && !isAnyModalOpen;

  const [cameraPreset, setCameraPreset] = useState<'isometric' | 'coldAisle' | 'hotAisle' | 'topDown' | 'coolerFocus' | null>(null);
  const [webglError, setWebglError] = useState(false);
  const controlsRef = useRef<OrbitControlsImpl | null>(null);

  // Check WebGL availability
  useEffect(() => {
    try {
      const canvas = document.createElement('canvas');
      const gl = canvas.getContext('webgl') || canvas.getContext('experimental-webgl');
      if (!gl) {
        setWebglError(true);
      }
    } catch {
      setWebglError(true);
    }
  }, []);

  const handleResetCamera = () => {
    setCameraPreset('isometric');
  };

  if (webglError) {
    return (
      <div className={`w-full ${heightClass} flex flex-col items-center justify-center bg-slate-100 rounded-lg border border-slate-200 p-6 text-center`}>
        <AlertCircle className="w-8 h-8 text-amber-500 mb-2" />
        <h4 className="font-semibold text-slate-800 text-sm">3D Hardware Acceleration Unavailable</h4>
        <p className="text-xs text-slate-500 max-w-sm mt-1">
          WebGL is disabled or unsupported on this device. You can still monitor all metrics, alerts, and forecasts in table view.
        </p>
      </div>
    );
  }

  return (
    <div className={`relative w-full ${isExpanded ? 'h-[750px]' : heightClass} rounded-lg border border-slate-200 bg-slate-50/50 overflow-hidden select-none transition-all duration-200 isolate z-0`}>
      {/* Top Floating Control Strip */}
      <div className="absolute top-3 left-3 right-3 z-10 flex items-center justify-between gap-2 pointer-events-none">
        <div className="pointer-events-auto">
          <SceneControls
            isAirflowPlaying={isAirflowPlaying}
            onToggleAirflow={() => setIsAirflowPlaying((p) => !p)}
            onResetCamera={handleResetCamera}
            onSetCameraPreset={(preset) => setCameraPreset(preset)}
            showArrows={settings.showAirflowArrows}
            onToggleArrows={() => updateSettings({ showAirflowArrows: !settings.showAirflowArrows })}
            showLabels={settings.showLabels}
            onToggleLabels={() => updateSettings({ showLabels: !settings.showLabels })}
            showPipes={settings.showPipes}
            onTogglePipes={() => updateSettings({ showPipes: !settings.showPipes })}
            sceneMode={sceneMode}
            onSelectSceneMode={(mode) => setSceneMode(mode)}
          />
        </div>

        {onToggleExpand && (
          <button
            onClick={onToggleExpand}
            className="pointer-events-auto p-2 bg-white/95 backdrop-blur-md border border-slate-200 rounded-lg text-slate-600 hover:text-slate-900 shadow-sm transition-colors"
            title={isExpanded ? 'Collapse 3D View' : 'Expand 3D View'}
          >
            {isExpanded ? <Minimize2 className="w-4 h-4" /> : <Maximize2 className="w-4 h-4" />}
          </button>
        )}
      </div>

      {/* Hover Tooltip */}
      <HoverTooltip rackId={hoveredRackId} racks={filteredRacks} tempUnit={settings.tempUnit} />

      {/* Bottom Floating Legend & Telemetry status */}
      <div className="absolute bottom-3 left-3 z-10 pointer-events-auto">
        <ThermalLegend sceneMode={sceneMode} tempUnit={settings.tempUnit} />
      </div>

      {/* Bottom Right Hints */}
      <div className="absolute bottom-3 right-3 z-10 pointer-events-none bg-white/80 backdrop-blur-xs border border-slate-200/60 rounded px-2 py-1 text-[10px] font-mono text-slate-500">
        Left Click + Drag: Rotate | Right Click + Drag: Pan | Scroll: Zoom
      </div>

      {/* 3D Canvas */}
      <Canvas
        camera={{ position: [11, 8.5, 12], fov: 42 }}
        shadows
        dpr={[1, 2]}
        gl={{ antialias: true, alpha: true, powerPreference: 'high-performance' }}
        onPointerMissed={() => setSelectedRackId(null)}
      >
        <Suspense
          fallback={
            <Html center>
              <div className="flex items-center gap-2 bg-white/95 px-3 py-2 rounded-lg border border-slate-200 shadow-md text-xs font-mono text-slate-600">
                <Loader2 className="w-4 h-4 text-blue-600 animate-spin" />
                <span>Initializing 3D Facility Scene...</span>
              </div>
            </Html>
          }
        >
          {/* Architectural Crisp Lighting with Studio Specular Highlights */}
          <ambientLight intensity={0.9} />
          <hemisphereLight args={['#ffffff', '#64748b', 1.1]} />
          <directionalLight
            position={[12, 22, 14]}
            intensity={1.5}
            castShadow
            shadow-mapSize-width={1024}
            shadow-mapSize-height={1024}
            shadow-camera-near={0.5}
            shadow-camera-far={40}
            shadow-camera-left={-12}
            shadow-camera-right={12}
            shadow-camera-top={12}
            shadow-camera-bottom={-12}
          />
          <directionalLight position={[-12, 14, -10]} intensity={0.8} />
          <directionalLight position={[0, 12, 16]} intensity={0.6} />

          {/* Camera Handler */}
          <CameraHandler
            cameraPreset={cameraPreset}
            onResetComplete={() => setCameraPreset(null)}
            controlsRef={controlsRef}
          />

          {/* Orbit Controls */}
          <OrbitControls
            ref={controlsRef}
            target={[0, 1.2, 0]}
            maxPolarAngle={Math.PI / 2 - 0.05} // don't go below floor
            minDistance={3.5}
            maxDistance={28}
            enableDamping
            dampingFactor={0.06}
          />

          {/* Raised Floor & Perforated Aisle Grilles */}
          <FloorTiles showTemperature={sceneMode === 'temperature'} />

          {/* Server Racks (Row A and Row B) */}
          <group>
            {filteredRacks.map((rack) => (
              <ServerRack
                key={rack.id}
                rack={rack}
                isSelected={selectedRackId === rack.id}
                isHovered={hoveredRackId === rack.id}
                sceneMode={sceneMode}
                showLabels={shouldShowLabels}
                onSelect={(id) => setSelectedRackId(id)}
                onHover={(id) => setHoveredRackId(id)}
              />
            ))}
          </group>

          {/* CRAC Cooling Units */}
          <group>
            {cracUnits.map((crac) => (
              <CRACUnit
                key={crac.id}
                data={crac}
                showLabels={shouldShowLabels}
                onSelect={(id) => setSelectedMachineId(id)}
              />
            ))}
          </group>

          {/* Overhead Chilled Water & Return Pipes */}
          <CoolingPipe showPipes={settings.showPipes} />

          {/* Animated Cold Intake & Hot Exhaust Airflow */}
          <Airflow
            isPlaying={isAirflowPlaying}
            speedMultiplier={settings.airflowSpeed}
            showArrows={settings.showAirflowArrows}
            showParticles={settings.showParticles}
            density={settings.particleDensity}
          />

          {/* Soft Ground Contact Shadow */}
          <ContactShadows
            position={[0, 0.001, 0]}
            opacity={0.35}
            scale={22}
            blur={1.5}
            far={4}
          />
        </Suspense>
      </Canvas>
    </div>
  );
};

