import React, { useMemo } from 'react';
import * as THREE from 'three';

interface FloorTilesProps {
  showTemperature?: boolean;
}

export const FloorTiles: React.FC<FloorTilesProps> = ({ showTemperature = false }) => {
  // Create raised floor tile grid: 24m x 16m
  const tileCountX = 24;
  const tileCountZ = 16;
  const tileSize = 0.9; // 900mm tiles

  // Generate tile positions and identify perforated tiles in the cold aisle (Z near 0)
  const tiles = useMemo(() => {
    const list: {
      x: number;
      z: number;
      isPerforated: boolean;
      isHotAisle: boolean;
    }[] = [];

    const halfX = tileCountX / 2;
    const halfZ = tileCountZ / 2;

    for (let i = 0; i < tileCountX; i++) {
      for (let j = 0; j < tileCountZ; j++) {
        const x = (i - halfX + 0.5) * tileSize;
        const z = (j - halfZ + 0.5) * tileSize;

        // Cold aisle is located along the middle strip: -1.0 <= z <= 1.0, -6 <= x <= 6
        const isPerforated = Math.abs(z) <= 1.0 && Math.abs(x) <= 6.2;
        // Hot aisle is behind the racks: |z| > 2.8
        const isHotAisle = Math.abs(z) > 2.6 && Math.abs(x) <= 6.2;

        list.push({ x, z, isPerforated, isHotAisle });
      }
    }
    return list;
  }, [tileCountX, tileCountZ, tileSize]);

  return (
    <group position={[0, -0.05, 0]}>
      {/* Base floor slab */}
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, -0.02, 0]} receiveShadow>
        <planeGeometry args={[26, 18]} />
        <meshStandardMaterial
          color="#f1f5f9"
          roughness={0.7}
          metalness={0.1}
        />
      </mesh>

      {/* Grid line indicator for technical floor */}
      <gridHelper
        args={[24, 24, '#cbd5e1', '#e2e8f0']}
        position={[0, 0.005, 0]}
      />

      {/* Raised Floor Tiles */}
      {tiles.map((tile, idx) => {
        let tileColor = '#f8fafc';
        let edgeColor = '#e2e8f0';

        if (tile.isPerforated) {
          // Cold aisle perforated tile (blue tinted ventilation grille)
          tileColor = showTemperature ? '#dbeafe' : '#f0f9ff';
          edgeColor = '#38bdf8';
        } else if (tile.isHotAisle && showTemperature) {
          // Warm aisle tile
          tileColor = '#fef2f2';
          edgeColor = '#fecaca';
        }

        return (
          <group key={idx} position={[tile.x, 0, tile.z]}>
            {/* Tile plate */}
            <mesh receiveShadow position={[0, 0, 0]}>
              <boxGeometry args={[tileSize * 0.96, 0.04, tileSize * 0.96]} />
              <meshStandardMaterial
                color={tileColor}
                roughness={0.6}
                metalness={0.15}
              />
            </mesh>

            {/* Perforated grille pattern for cold aisle */}
            {tile.isPerforated && (
              <group position={[0, 0.025, 0]}>
                {/* Visual vents */}
                {[-0.25, 0, 0.25].map((vx, i) => (
                  <mesh key={i} position={[vx, 0, 0]}>
                    <boxGeometry args={[0.08, 0.005, tileSize * 0.7]} />
                    <meshStandardMaterial color="#0284c7" roughness={0.4} />
                  </mesh>
                ))}
              </group>
            )}
          </group>
        );
      })}

      {/* Cold Aisle Guidance Line Markings */}
      <mesh position={[0, 0.015, -1.15]} rotation={[-Math.PI / 2, 0, 0]}>
        <planeGeometry args={[13, 0.04]} />
        <meshBasicMaterial color="#38bdf8" transparent opacity={0.6} />
      </mesh>
      <mesh position={[0, 0.015, 1.15]} rotation={[-Math.PI / 2, 0, 0]}>
        <planeGeometry args={[13, 0.04]} />
        <meshBasicMaterial color="#38bdf8" transparent opacity={0.6} />
      </mesh>
    </group>
  );
};

import React from 'react';
import {
  Play,
  Pause,
  RotateCcw,
  Wind,
  Flame,
  Activity,
  Tag,
  Layers,
  Camera,
  HardDrive,
  Zap,
  Thermometer,
  Network
} from 'lucide-react';
import { SceneMode } from '../../types';

interface SceneControlsProps {
  isAirflowPlaying: boolean;
  onToggleAirflow: () => void;
  onResetCamera: () => void;
  onSetCameraPreset: (preset: 'isometric' | 'coldAisle' | 'hotAisle' | 'topDown' | 'coolerFocus') => void;
  showArrows: boolean;
  onToggleArrows: () => void;
  showLabels: boolean;
  onToggleLabels: () => void;
  showPipes: boolean;
  onTogglePipes: () => void;
  sceneMode: SceneMode;
  onSelectSceneMode: (mode: SceneMode) => void;
}

export const SceneControls: React.FC<SceneControlsProps> = ({
  isAirflowPlaying,
  onToggleAirflow,
  onResetCamera,
  onSetCameraPreset,
  showArrows,
  onToggleArrows,
  showLabels,
  onToggleLabels,
  showPipes,
  onTogglePipes,
  sceneMode,
  onSelectSceneMode,
}) => {
  return (
    <div className="flex flex-wrap items-center gap-1.5 p-1.5 bg-white/95 backdrop-blur-md border border-slate-200/90 rounded-lg shadow-sm text-xs select-none">
      {/* Airflow Play/Pause */}
      <button
        onClick={onToggleAirflow}
        title={isAirflowPlaying ? 'Pause Airflow Animation' : 'Resume Airflow Animation'}
        className={`flex items-center gap-1 px-2.5 py-1.5 rounded-md font-medium transition-all ${
          isAirflowPlaying
            ? 'bg-blue-50 text-blue-700 hover:bg-blue-100'
            : 'bg-slate-100 text-slate-700 hover:bg-slate-200'
        }`}
      >
        {isAirflowPlaying ? (
          <>
            <Pause className="w-3.5 h-3.5 text-blue-600" />
            <span>Airflow</span>
          </>
        ) : (
          <>
            <Play className="w-3.5 h-3.5 text-slate-600" />
            <span>Paused</span>
          </>
        )}
      </button>

      <div className="h-4 w-px bg-slate-200 mx-0.5" />

      {/* Camera Presets Menu */}
      <div className="flex items-center gap-1">
        <button
          onClick={onResetCamera}
          title="Reset Camera to Default Isometric View"
          className="flex items-center gap-1 px-2 py-1.5 rounded-md text-slate-600 hover:text-slate-900 hover:bg-slate-100 transition-colors"
        >
          <RotateCcw className="w-3.5 h-3.5" />
          <span className="hidden sm:inline">Reset</span>
        </button>

        <button
          onClick={() => onSetCameraPreset('coldAisle')}
          title="Cold Aisle Front-Intake Camera Angle"
          className="px-2 py-1.5 rounded-md text-slate-600 hover:text-slate-900 hover:bg-slate-100 transition-colors font-mono text-[11px]"
        >
          Cold Aisle
        </button>

        <button
          onClick={() => onSetCameraPreset('hotAisle')}
          title="Hot Aisle Exhaust Camera Angle"
          className="px-2 py-1.5 rounded-md text-slate-600 hover:text-slate-900 hover:bg-slate-100 transition-colors font-mono text-[11px]"
        >
          Hot Aisle
        </button>

        <button
          onClick={() => onSetCameraPreset('topDown')}
          title="Top-Down Engineering Floorplan View"
          className="px-2 py-1.5 rounded-md text-slate-600 hover:text-slate-900 hover:bg-slate-100 transition-colors font-mono text-[11px]"
        >
          Top Down
        </button>

        <button
          onClick={() => onSetCameraPreset('coolerFocus')}
          title="Zoom and Orbit Around Metallic Cooler Machine"
          className="px-2 py-1.5 rounded-md text-blue-700 bg-blue-50/90 hover:bg-blue-100 transition-colors font-mono text-[11px] font-semibold flex items-center gap-1"
        >
          <Wind className="w-3 h-3 text-blue-600" />
          <span>Cooler 3D</span>
        </button>
      </div>

      <div className="h-4 w-px bg-slate-200 mx-0.5" />

      {/* Layer Visibility Toggles */}
      <div className="flex items-center gap-0.5">
        <button
          onClick={onToggleArrows}
          title="Toggle 3D Airflow Arrows"
          className={`p-1.5 rounded-md transition-colors ${
            showArrows ? 'bg-sky-50 text-sky-700' : 'text-slate-400 hover:text-slate-600'
          }`}
        >
          <Wind className="w-3.5 h-3.5" />
        </button>

        <button
          onClick={onTogglePipes}
          title="Toggle Overhead Cooling Pipes"
          className={`p-1.5 rounded-md transition-colors ${
            showPipes ? 'bg-indigo-50 text-indigo-700' : 'text-slate-400 hover:text-slate-600'
          }`}
        >
          <Layers className="w-3.5 h-3.5" />
        </button>

        <button
          onClick={onToggleLabels}
          title="Toggle Rack ID Labels"
          className={`p-1.5 rounded-md transition-colors ${
            showLabels ? 'bg-slate-100 text-slate-800' : 'text-slate-400 hover:text-slate-600'
          }`}
        >
          <Tag className="w-3.5 h-3.5" />
        </button>
      </div>

      <div className="h-4 w-px bg-slate-200 mx-0.5" />

      {/* Overlay Modes Dropdown / Segmented control */}
      <div className="flex items-center gap-1 bg-slate-100/80 p-0.5 rounded-md">
        <button
          onClick={() => onSelectSceneMode('normal')}
          className={`px-2 py-1 rounded text-[11px] font-medium transition-colors ${
            sceneMode === 'normal' ? 'bg-white text-slate-900 shadow-xs' : 'text-slate-600 hover:text-slate-900'
          }`}
        >
          Normal
        </button>

        <button
          onClick={() => onSelectSceneMode('temperature')}
          className={`flex items-center gap-1 px-2 py-1 rounded text-[11px] font-medium transition-colors ${
            sceneMode === 'temperature' ? 'bg-white text-rose-700 shadow-xs' : 'text-slate-600 hover:text-slate-900'
          }`}
        >
          <Flame className="w-3 h-3 text-rose-500" />
          <span>Thermal</span>
        </button>

        <button
          onClick={() => onSelectSceneMode('status')}
          className={`flex items-center gap-1 px-2 py-1 rounded text-[11px] font-medium transition-colors ${
            sceneMode === 'status' ? 'bg-white text-emerald-700 shadow-xs' : 'text-slate-600 hover:text-slate-900'
          }`}
        >
          <Activity className="w-3 h-3 text-emerald-500" />
          <span>Health</span>
        </button>

        <button
          onClick={() => onSelectSceneMode('storage')}
          className={`flex items-center gap-1 px-2 py-1 rounded text-[11px] font-medium transition-colors ${
            sceneMode === 'storage' ? 'bg-white text-blue-700 shadow-xs' : 'text-slate-600 hover:text-slate-900'
          }`}
        >
          <HardDrive className="w-3 h-3 text-blue-500" />
          <span>Storage</span>
        </button>

        <button
          onClick={() => onSelectSceneMode('power')}
          className={`flex items-center gap-1 px-2 py-1 rounded text-[11px] font-medium transition-colors ${
            sceneMode === 'power' ? 'bg-white text-amber-700 shadow-xs' : 'text-slate-600 hover:text-slate-900'
          }`}
        >
          <Zap className="w-3 h-3 text-amber-500" />
          <span>Power</span>
        </button>
      </div>
    </div>
  );
};

