import React, { useRef, useState } from 'react';
import * as THREE from 'three';
import { useFrame } from '@react-three/fiber';
import { Html } from '@react-three/drei';
import { RackData, SceneMode } from '../../types';

interface ServerRackProps {
  rack: RackData;
  isSelected: boolean;
  isHovered: boolean;
  sceneMode: SceneMode;
  showLabels: boolean;
  onSelect: (rackId: string) => void;
  onHover: (rackId: string | null) => void;
}

export const ServerRack: React.FC<ServerRackProps> = ({
  rack,
  isSelected,
  isHovered,
  sceneMode,
  showLabels,
  onSelect,
  onHover,
}) => {
  const groupRef = useRef<THREE.Group>(null);
  const [internalHover, setInternalHover] = useState(false);

  // Determine rack color based on current overlay mode
  const getRackVisualColors = () => {
    if (sceneMode === 'temperature') {
      // Temperature Heatmap
      const t = rack.tempC;
      if (t < 22.5) return { body: '#1e293b', face: '#38bdf8', glow: '#0284c7' }; // cool blue
      if (t < 24.0) return { body: '#1e293b', face: '#10b981', glow: '#059669' }; // normal green
      if (t < 26.0) return { body: '#1e293b', face: '#f59e0b', glow: '#d97706' }; // warm amber
      return { body: '#1e293b', face: '#ef4444', glow: '#dc2626' }; // hot red
    }

    if (sceneMode === 'status') {
      if (rack.health === 'critical') return { body: '#1e293b', face: '#f87171', glow: '#ef4444' };
      if (rack.health === 'warning') return { body: '#1e293b', face: '#fbbf24', glow: '#f59e0b' };
      return { body: '#1e293b', face: '#34d399', glow: '#10b981' };
    }

    if (sceneMode === 'storage') {
      const util = rack.storageUtil;
      if (util > 80) return { body: '#1e293b', face: '#ef4444', glow: '#dc2626' };
      if (util > 65) return { body: '#1e293b', face: '#f59e0b', glow: '#d97706' };
      return { body: '#1e293b', face: '#3b82f6', glow: '#2563eb' };
    }

    if (sceneMode === 'power') {
      const util = (rack.powerKw / rack.powerMaxKw) * 100;
      if (util > 85) return { body: '#1e293b', face: '#ef4444', glow: '#dc2626' };
      if (util > 70) return { body: '#1e293b', face: '#f59e0b', glow: '#d97706' };
      return { body: '#1e293b', face: '#10b981', glow: '#059669' };
    }

    if (sceneMode === 'cooling') {
      if (rack.tempC > 25) return { body: '#1e293b', face: '#ef4444', glow: '#dc2626' };
      if (rack.tempC > 23) return { body: '#1e293b', face: '#f59e0b', glow: '#d97706' };
      return { body: '#1e293b', face: '#06b6d4', glow: '#0891b2' };
    }

    if (sceneMode === 'network') {
      const util = (rack.networkGbps / rack.networkMaxGbps) * 100;
      if (util > 80) return { body: '#1e293b', face: '#ef4444', glow: '#dc2626' };
      if (util > 60) return { body: '#1e293b', face: '#f59e0b', glow: '#d97706' };
      return { body: '#1e293b', face: '#6366f1', glow: '#4f46e5' };
    }

    // Default Normal Hardware Mode
    return {
      body: '#1e293b',
      face: '#334155',
      glow: rack.health === 'critical' ? '#ef4444' : rack.health === 'warning' ? '#f59e0b' : '#10b981',
    };
  };

  const colors = getRackVisualColors();

  // Subtle breathing animation for selected rack or risk beacon
  const beaconRef = useRef<THREE.Mesh>(null);
  useFrame((state) => {
    if (beaconRef.current && (isSelected || rack.risk)) {
      const s = 1 + Math.sin(state.clock.elapsedTime * 4) * 0.15;
      beaconRef.current.scale.set(s, s, s);
    }
  });

  const width = 0.9;
  const height = 2.2;
  const depth = 1.1;

  const hasRisk = !!rack.risk;

  return (
    <group
      ref={groupRef}
      position={rack.position}
      rotation={[0, rack.rotationY, 0]}
      onClick={(e) => {
        e.stopPropagation();
        onSelect(rack.id);
      }}
      onPointerOver={(e) => {
        e.stopPropagation();
        setInternalHover(true);
        onHover(rack.id);
      }}
      onPointerOut={() => {
        setInternalHover(false);
        onHover(null);
      }}
    >
      {/* Selection Bounding Bracket / Ring */}
      {isSelected && (
        <group position={[0, height / 2, 0]}>
          <lineSegments>
            <edgesGeometry args={[new THREE.BoxGeometry(width + 0.1, height + 0.08, depth + 0.1)]} />
            <lineBasicMaterial color="#2563eb" linewidth={2} />
          </lineSegments>
          {/* Floor selection decal */}
          <mesh position={[0, -height / 2 + 0.01, 0]} rotation={[-Math.PI / 2, 0, 0]}>
            <ringGeometry args={[0.7, 0.78, 32]} />
            <meshBasicMaterial color="#2563eb" transparent opacity={0.8} />
          </mesh>
        </group>
      )}

      {/* Hover Bounding Bracket */}
      {!isSelected && (isHovered || internalHover) && (
        <group position={[0, height / 2, 0]}>
          <lineSegments>
            <edgesGeometry args={[new THREE.BoxGeometry(width + 0.06, height + 0.04, depth + 0.06)]} />
            <lineBasicMaterial color="#94a3b8" linewidth={1} />
          </lineSegments>
        </group>
      )}

      {/* Main Rack Outer Chassis Frame */}
      <mesh position={[0, height / 2, 0]} castShadow receiveShadow>
        <boxGeometry args={[width, height, depth]} />
        <meshStandardMaterial
          color={colors.body}
          roughness={0.5}
          metalness={0.6}
        />
      </mesh>

      {/* Rack Vertical Corner Rails (Black Anodized Aluminum) */}
      {[
        [-width / 2 + 0.04, -depth / 2 + 0.04],
        [width / 2 - 0.04, -depth / 2 + 0.04],
        [-width / 2 + 0.04, depth / 2 - 0.04],
        [width / 2 - 0.04, depth / 2 - 0.04],
      ].map(([rx, rz], i) => (
        <mesh key={i} position={[rx, height / 2, rz]}>
          <boxGeometry args={[0.06, height, 0.06]} />
          <meshStandardMaterial color="#0f172a" roughness={0.3} metalness={0.8} />
        </mesh>
      ))}

      {/* Top Roof / Cable Tray Entry Plate */}
      <mesh position={[0, height + 0.02, 0]}>
        <boxGeometry args={[width * 0.98, 0.04, depth * 0.98]} />
        <meshStandardMaterial color="#1e293b" roughness={0.4} metalness={0.7} />
      </mesh>

      {/* 8 Server Units inside rack front (+Z face) */}
      <group position={[0, 0, depth / 2 + 0.005]}>
        {rack.servers.map((srv, idx) => {
          const srvHeight = 0.22;
          const srvY = 0.2 + idx * 0.245;

          // Status LED color
          const ledColor =
            srv.status === 'critical'
              ? '#ef4444'
              : srv.status === 'warning'
              ? '#f59e0b'
              : '#10b981';

          return (
            <group key={srv.id} position={[0, srvY, 0]}>
              {/* Server Bezel Faceplate */}
              <mesh position={[0, 0, 0]}>
                <boxGeometry args={[width * 0.88, srvHeight, 0.02]} />
                <meshStandardMaterial
                  color={sceneMode === 'normal' ? '#334155' : colors.face}
                  roughness={0.5}
                  metalness={0.5}
                />
              </mesh>

              {/* Drive bays / vents styling */}
              {[-0.24, -0.08, 0.08].map((dx, di) => (
                <mesh key={di} position={[dx, 0, 0.012]}>
                  <boxGeometry args={[0.13, srvHeight * 0.7, 0.005]} />
                  <meshStandardMaterial color="#1e293b" roughness={0.7} />
                </mesh>
              ))}

              {/* Server Activity & Health LED indicators */}
              <mesh position={[width * 0.35, 0.04, 0.015]}>
                <sphereGeometry args={[0.012, 12, 12]} />
                <meshBasicMaterial color={ledColor} />
              </mesh>
              <mesh position={[width * 0.35, -0.04, 0.015]}>
                <sphereGeometry args={[0.008, 8, 8]} />
                <meshBasicMaterial color="#38bdf8" />
              </mesh>
            </group>
          );
        })}
      </group>

      {/* Rear Exhaust Face (-Z face) */}
      <mesh position={[0, height / 2, -depth / 2 - 0.005]}>
        <planeGeometry args={[width * 0.88, height * 0.9]} />
        <meshStandardMaterial
          color="#0f172a"
          roughness={0.8}
          metalness={0.2}
          wireframe={false}
        />
      </mesh>

      {/* Risk Warning Beacon Indicator on Top */}
      {hasRisk && (
        <group position={[0, height + 0.16, 0]}>
          <mesh ref={beaconRef}>
            <cylinderGeometry args={[0.06, 0.08, 0.1, 16]} />
            <meshStandardMaterial
              color={rack.health === 'critical' ? '#ef4444' : '#f59e0b'}
              emissive={rack.health === 'critical' ? '#dc2626' : '#d97706'}
              emissiveIntensity={0.8}
            />
          </mesh>
          <mesh position={[0, 0.08, 0]}>
            <sphereGeometry args={[0.04, 16, 16]} />
            <meshBasicMaterial color={rack.health === 'critical' ? '#ff6b6b' : '#fcd34d'} />
          </mesh>
        </group>
      )}

      {/* Rack Identifier Badge Label */}
      {showLabels && (
        <Html
          position={[0, height + 0.18, 0]}
          center
          distanceFactor={38}
          zIndexRange={[10, 0]}
          className="pointer-events-none select-none transition-all duration-150"
        >
          <div
            className={`px-1.5 py-0.5 rounded text-[9px] font-mono font-medium tracking-tight flex items-center gap-1 shadow-xs border whitespace-nowrap ${
              isSelected
                ? 'bg-blue-600 text-white border-blue-500 ring-2 ring-blue-300'
                : rack.health === 'critical'
                ? 'bg-rose-50 text-rose-700 border-rose-300'
                : rack.health === 'warning'
                ? 'bg-amber-50 text-amber-700 border-amber-300'
                : 'bg-white/95 text-slate-700 border-slate-200'
            }`}
          >
            <span
              className={`w-1 h-1 rounded-full ${
                rack.health === 'critical'
                  ? 'bg-rose-500 animate-pulse'
                  : rack.health === 'warning'
                  ? 'bg-amber-500'
                  : 'bg-emerald-500'
              }`}
            />
            <span>{rack.label}</span>
            {rack.risk && (
              <span className="text-[7.5px] font-bold px-1 py-0.2 rounded bg-rose-100 text-rose-700 uppercase">
                {rack.risk.metric}
              </span>
            )}
          </div>
        </Html>
      )}
    </group>
  );
};

import React from 'react';
import { SceneMode } from '../../types';

interface ThermalLegendProps {
  sceneMode: SceneMode;
  tempUnit?: 'C' | 'F';
}

export const ThermalLegend: React.FC<ThermalLegendProps> = ({ sceneMode, tempUnit = 'C' }) => {
  if (sceneMode === 'normal') {
    return (
      <div className="bg-white/90 backdrop-blur-sm border border-slate-200/80 rounded-md p-2 text-xs shadow-sm flex items-center gap-3">
        <span className="font-semibold text-slate-700 font-mono text-[11px] uppercase tracking-wider">Airflow Key:</span>
        <div className="flex items-center gap-1.5">
          <span className="w-2.5 h-2.5 rounded-full bg-sky-500 ring-2 ring-sky-200" />
          <span className="text-slate-600 font-medium">Cold Supply (13°C)</span>
        </div>
        <div className="flex items-center gap-1.5">
          <span className="w-2.5 h-2.5 rounded-full bg-rose-500 ring-2 ring-rose-200" />
          <span className="text-slate-600 font-medium">Hot Exhaust (27°C)</span>
        </div>
      </div>
    );
  }

  if (sceneMode === 'temperature') {
    const tMin = tempUnit === 'C' ? '18°C' : '64°F';
    const tMid = tempUnit === 'C' ? '23°C' : '73°F';
    const tMax = tempUnit === 'C' ? '32°C' : '90°F';

    return (
      <div className="bg-white/90 backdrop-blur-sm border border-slate-200/80 rounded-md p-2 text-xs shadow-sm flex flex-col gap-1 min-w-[200px]">
        <div className="flex justify-between items-center text-[10px] font-mono text-slate-500">
          <span className="font-semibold text-slate-700">TEMPERATURE GRADIENT</span>
          <span>{tempUnit === 'C' ? 'Celsius' : 'Fahrenheit'}</span>
        </div>
        <div className="h-2 w-full rounded-sm bg-gradient-to-r from-sky-400 via-emerald-400 via-amber-400 to-rose-600" />
        <div className="flex justify-between text-[10px] font-mono font-medium text-slate-600">
          <span>{tMin} (Cold)</span>
          <span>{tMid} (Target)</span>
          <span>{tMax} (Hot)</span>
        </div>
      </div>
    );
  }

  if (sceneMode === 'status') {
    return (
      <div className="bg-white/90 backdrop-blur-sm border border-slate-200/80 rounded-md p-2 text-xs shadow-sm flex items-center gap-3">
        <span className="font-semibold text-slate-700 font-mono text-[11px] uppercase tracking-wider">Health Status:</span>
        <div className="flex items-center gap-1">
          <span className="w-2 h-2 rounded-full bg-emerald-500" />
          <span className="text-slate-600">Healthy (&lt;75%)</span>
        </div>
        <div className="flex items-center gap-1">
          <span className="w-2 h-2 rounded-full bg-amber-500" />
          <span className="text-slate-600">Warning (75-85%)</span>
        </div>
        <div className="flex items-center gap-1">
          <span className="w-2 h-2 rounded-full bg-rose-500" />
          <span className="text-slate-600">Critical (&gt;85%)</span>
        </div>
      </div>
    );
  }

  // Metric modes (storage, power, cooling, network)
  const metricLabels: Record<string, { name: string; unit: string }> = {
    storage: { name: 'Storage Utilisation', unit: '%' },
    power: { name: 'Power Load Capacity', unit: 'kW' },
    cooling: { name: 'Cooling Thermal Headroom', unit: '°C' },
    network: { name: 'Uplink Bandwidth Saturation', unit: 'Gbps' },
  };

  const current = metricLabels[sceneMode] || { name: 'Capacity Utilisation', unit: '%' };

  return (
    <div className="bg-white/90 backdrop-blur-sm border border-slate-200/80 rounded-md p-2 text-xs shadow-sm flex flex-col gap-1 min-w-[210px]">
      <div className="flex justify-between items-center text-[10px] font-mono text-slate-500">
        <span className="font-semibold text-slate-700 uppercase">{current.name}</span>
        <span>{current.unit}</span>
      </div>
      <div className="h-2 w-full rounded-sm bg-gradient-to-r from-blue-500 via-amber-400 to-rose-600" />
      <div className="flex justify-between text-[10px] font-mono font-medium text-slate-600">
        <span>0%</span>
        <span>75% (Warn)</span>
        <span>85% (Crit)</span>
        <span>100%</span>
      </div>
    </div>
  );
};

sources.src/components/datacenter2d/ColdAirflow2:
/**
 * 2D Technical Cold Airflow Component
 * Straight upward-rising blue chevrons and floating micro-particles.
 * Moves strictly vertically inside the central cold aisle without crossing server racks.
 */

import React from 'react';

interface ColdAirflow2DProps {
  x: number; // Center X
  y: number; // Base Y (origin in cold aisle)
  speedSeconds?: number;
}

export const ColdAirflow2D: React.FC<ColdAirflow2DProps> = ({
  x,
  y,
  speedSeconds = 2.2,
}) => {
  return (
    <g transform={`translate(${x}, ${y})`} className="pointer-events-none select-none">
      <style>{`
        @keyframes coldRiseStraight {
          0% {
            transform: translateY(0px);
            opacity: 0;
          }
          20% {
            opacity: 0.9;
          }
          75% {
            opacity: 0.85;
          }
          100% {
            transform: translateY(-32px);
            opacity: 0;
          }
        }
        @keyframes coldParticleStraight {
          0% {
            transform: translateY(0px);
            opacity: 0;
          }
          30% {
            opacity: 0.8;
          }
          70% {
            opacity: 0.8;
          }
          100% {
            transform: translateY(-38px);
            opacity: 0;
          }
        }
      `}</style>

      {/* Guide Stream Path (Strictly Vertical) */}
      <line
        x1="0"
        y1="0"
        x2="0"
        y2="-34"
        stroke="#7dd3fc"
        strokeWidth="0.8"
        strokeDasharray="2 2"
        opacity="0.35"
      />

      {/* Primary Animated Chevron 1 */}
      <g
        style={{
          animation: `coldRiseStraight ${speedSeconds}s cubic-bezier(0.4, 0, 0.2, 1) infinite`,
        }}
      >
        <path
          d="M -5 5 L 0 0 L 5 5"
          fill="none"
          stroke="#0284c7"
          strokeWidth="1.8"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      </g>

      {/* Secondary Staggered Chevron 2 */}
      <g
        style={{
          animation: `coldRiseStraight ${speedSeconds}s cubic-bezier(0.4, 0, 0.2, 1) infinite`,
          animationDelay: `${speedSeconds * 0.5}s`,
        }}
      >
        <path
          d="M -4 4 L 0 0 L 4 4"
          fill="none"
          stroke="#38bdf8"
          strokeWidth="1.5"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      </g>

      {/* Micro Cold Air Particulates */}
      <circle
        cx="0"
        cy="0"
        r="1.2"
        fill="#0284c7"
        style={{
          animation: `coldParticleStraight ${speedSeconds * 1.1}s ease-in-out infinite`,
          animationDelay: '0.2s',
        }}
      />
    </g>
  );
};

sources.src/components/datacenter2d/CoolingPipe2:
/**
 * 2D Technical Overhead Cooling Pipe Infrastructure Component
 * Straight, parallel, and perfectly aligned chilled water supply (blue)
 * and warm return (orange) pipes with vertical ceiling suspension hangers and continuous CRAC couplings.
 */

import React from 'react';

interface CoolingPipe2DProps {
  leftX?: number; // Left connection X (CRAC A center)
  rightX?: number; // Right connection X (CRAC B center)
  returnY?: number; // Return pipe horizontal Y
  supplyY?: number; // Supply pipe horizontal Y
  cracTopY?: number; // Top of CRAC units where vertical drops connect
}

export const CoolingPipe2D: React.FC<CoolingPipe2DProps> = ({
  leftX = 90,
  rightX = 1010,
  returnY = 46,
  supplyY = 70,
  cracTopY = 110,
}) => {
  const hangerPositions = [210, 320, 430, 540, 650, 760, 870];
  const flangePositions = [265, 485, 705, 925];

  return (
    <g className="pointer-events-none select-none">
      {/* 1. Ceiling Threaded Suspension Rod Hangers */}
      {hangerPositions.map((hx) => (
        <g key={`hanger-${hx}`}>
          {/* Threaded rod from ceiling */}
          <line
            x1={hx}
            y1={16}
            x2={hx}
            y2={supplyY + 12}
            stroke="#94a3b8"
            strokeWidth="1.2"
            strokeDasharray="2 1"
          />
          {/* Ceiling anchor bracket */}
          <rect
            x={hx - 4}
            y={14}
            width={8}
            height={3}
            fill="#334155"
            rx="0.5"
          />
          {/* Horizontal Unistrut Channel Trapeze Bracket */}
          <line
            x1={hx - 9}
            y1={supplyY + 11}
            x2={hx + 9}
            y2={supplyY + 11}
            stroke="#1e293b"
            strokeWidth="2.5"
            strokeLinecap="round"
          />
        </g>
      ))}

      {/* 2. Warm Water Return Pipe (Upper Pipe, Straight Horizontal, Orange #ea580c) */}
      <g>
        {/* Main Straight Horizontal Run */}
        <line
          x1={leftX + 16}
          y1={returnY}
          x2={rightX - 16}
          y2={returnY}
          stroke="#ea580c"
          strokeWidth="7"
          strokeLinecap="round"
        />
        {/* Inner Highlight Line */}
        <line
          x1={leftX + 16}
          y1={returnY - 1.2}
          x2={rightX - 16}
          y2={returnY - 1.2}
          stroke="#fed7aa"
          strokeWidth="1.5"
          opacity="0.8"
        />

        {/* Flanges / Couplings */}
        {flangePositions.map((fx) => (
          <rect
            key={`return-flange-${fx}`}
            x={fx - 2}
            y={returnY - 5}
            width={4}
            height={10}
            rx="1"
            fill="#9a3412"
            stroke="#431407"
            strokeWidth="0.75"
          />
        ))}

        {/* Left Vertical Drop into CRAC A */}
        <path
          d={`M ${leftX + 16} ${returnY} L ${leftX + 16} ${cracTopY - 6}`}
          fill="none"
          stroke="#ea580c"
          strokeWidth="6"
          strokeLinecap="round"
        />

        {/* Right Vertical Drop into CRAC B */}
        <path
          d={`M ${rightX - 16} ${returnY} L ${rightX - 16} ${cracTopY - 6}`}
          fill="none"
          stroke="#ea580c"
          strokeWidth="6"
          strokeLinecap="round"
        />
      </g>

      {/* 3. Chilled Water Supply Pipe (Lower Pipe, Straight Horizontal, Ocean Blue #0284c7) */}
      <g>
        {/* Main Straight Horizontal Run */}
        <line
          x1={leftX - 12}
          y1={supplyY}
          x2={rightX + 12}
          y2={supplyY}
          stroke="#0284c7"
          strokeWidth="8"
          strokeLinecap="round"
        />
        {/* Inner Highlight Line */}
        <line
          x1={leftX - 12}
          y1={supplyY - 1.5}
          x2={rightX + 12}
          y2={supplyY - 1.5}
          stroke="#bae6fd"
          strokeWidth="1.8"
          opacity="0.85"
        />

        {/* Flanges */}
        {flangePositions.map((fx) => (
          <rect
            key={`supply-flange-${fx}`}
            x={fx + 18}
            y={supplyY - 6}
            width={4.5}
            height={12}
            rx="1"
            fill="#0369a1"
            stroke="#082f49"
            strokeWidth="0.75"
          />
        ))}

        {/* Left Vertical Drop into CRAC A */}
        <path
          d={`M ${leftX - 12} ${supplyY} L ${leftX - 12} ${cracTopY - 6}`}
          fill="none"
          stroke="#0284c7"
          strokeWidth="7"
          strokeLinecap="round"
        />

        {/* Right Vertical Drop into CRAC B */}
        <path
          d={`M ${rightX + 12} ${supplyY} L ${rightX + 12} ${cracTopY - 6}`}
          fill="none"
          stroke="#0284c7"
          strokeWidth="7"
          strokeLinecap="round"
        />
      </g>

      {/* 4. Technical Pipe Flow Direction Markers */}
      <g transform={`translate(150, ${returnY - 7})`}>
        <text
          fill="#c2410c"
          fontSize="8"
          fontFamily="ui-monospace, SFMono-Regular, Menlo, monospace"
          fontWeight="bold"
          letterSpacing="0.05em"
        >
          ── CHW-R RETURN 12&quot; [26.8°C] ──▶
        </text>
      </g>
      <g transform={`translate(740, ${supplyY + 14})`}>
        <text
          fill="#0369a1"
          fontSize="8"
          fontFamily="ui-monospace, SFMono-Regular, Menlo, monospace"
          fontWeight="bold"
          letterSpacing="0.05em"
        >
          ◀── CHW-S SUPPLY 14&quot; [13.2°C] ──
        </text>
      </g>
    </g>
  );
};

sources.src/components/datacenter2d/CRACUnit2D.t:
/**
 * 2D Technical CRAC Precision Cooling Unit Component
 * Straight, perfectly vertical precision cooling machine with rotating EC fan,
 * digital temperature readout, horizontal intake louvers, and direct overhead pipe couplings.
 */

import React from 'react';
import { CRAC2DData } from './types2d';
import { ResourceIndicator2D } from './ResourceIndicator2D';

interface CRACUnit2DProps {
  unit: CRAC2DData;
  x: number; // Top-left X
  y: number; // Top-left Y
  width?: number;
  height?: number;
  isSelected: boolean;
  isHovered: boolean;
  onSelect: (unit: CRAC2DData) => void;
  onHover: (unit: CRAC2DData, event: React.MouseEvent) => void;
  onLeave: () => void;
}

export const CRACUnit2D: React.FC<CRACUnit2DProps> = ({
  unit,
  x,
  y,
  width = 90,
  height = 410,
  isSelected,
  isHovered,
  onSelect,
  onHover,
  onLeave,
}) => {
  const depthX = 8;
  const depthY = 6;

  // Fan center on upper chassis
  const fanCenterX = x + width / 2;
  const fanCenterY = y + 54;

  const topFacePoints = `${x},${y} ${x + width},${y} ${x + width + depthX},${y - depthY} ${x + depthX},${y - depthY}`;
  const sideFacePoints = `${x + width},${y} ${x + width + depthX},${y - depthY} ${x + width + depthX},${y + height - depthY} ${x + width},${y + height}`;

  return (
    <g
      className="cursor-pointer transition-all duration-150 select-none group"
      onClick={(e) => {
        e.stopPropagation();
        onSelect(unit);
      }}
      onMouseEnter={(e) => onHover(unit, e)}
      onMouseLeave={onLeave}
    >
      {/* 1. Floor Contact Shadow */}
      <rect
        x={x}
        y={y + height}
        width={width + depthX}
        height={4}
        rx="2"
        fill="rgba(15, 23, 42, 0.1)"
      />

      {/* 2. Selection Halo Glow */}
      {isSelected && (
        <rect
          x={x - 4}
          y={y - depthY - 4}
          width={width + depthX + 8}
          height={height + depthY + 8}
          rx="4"
          fill="rgba(2, 132, 199, 0.1)"
          stroke="#0284c7"
          strokeWidth="1.8"
          strokeDasharray="4 2"
        />
      )}

      {/* 3. Subtle 2.5D Top Roof Facet */}
      <polygon
        points={topFacePoints}
        fill={isHovered ? '#f8fafc' : '#f1f5f9'}
        stroke={isSelected ? '#0284c7' : '#64748b'}
        strokeWidth="0.8"
        strokeLinejoin="round"
      />
      {/* Pipe Stubs on Top */}
      <ellipse
        cx={x + width * 0.35}
        cy={y - depthY * 0.5}
        rx="4.5"
        ry="2.5"
        fill="#0284c7"
        stroke="#0369a1"
        strokeWidth="1"
      />
      <ellipse
        cx={x + width * 0.65}
        cy={y - depthY * 0.5}
        rx="4.5"
        ry="2.5"
        fill="#ea580c"
        stroke="#c2410c"
        strokeWidth="1"
      />

      {/* 4. Subtle 2.5D Right Side Panel */}
      <polygon
        points={sideFacePoints}
        fill={isHovered ? '#e2e8f0' : '#cbd5e1'}
        stroke={isSelected ? '#0284c7' : '#64748b'}
        strokeWidth="0.8"
        strokeLinejoin="round"
      />

      {/* 5. Main Cabinet Front (Strictly Vertical & Horizontal) */}
      <rect
        x={x}
        y={y}
        width={width}
        height={height}
        rx="2"
        fill={isHovered ? '#ffffff' : '#f8fafc'}
        stroke={isSelected ? '#0284c7' : isHovered ? '#0f172a' : '#334155'}
        strokeWidth={isSelected ? '2' : '1.25'}
      />

      {/* Section A: Upper EC Fan Module */}
      <rect
        x={x + 6}
        y={y + 8}
        width={width - 12}
        height={92}
        rx="2"
        fill="#f1f5f9"
        stroke="#64748b"
        strokeWidth="0.8"
      />

      {/* Rotating Fan Impeller (Pure CSS animation) */}
      <g transform={`translate(${fanCenterX}, ${fanCenterY})`}>
        {/* Outer Circular Shroud */}
        <circle
          cx="0"
          cy="0"
          r="24"
          fill="#e2e8f0"
          stroke="#0284c7"
          strokeWidth="1.2"
        />
        {/* 6 Rotating Aerodynamic Impeller Blades */}
        <g className="animate-spin" style={{ animationDuration: '3.5s', transformOrigin: '0px 0px' }}>
          {[0, 60, 120, 180, 240, 300].map((deg) => (
            <path
              key={`crac-blade-${deg}`}
              d="M 0 0 C 4 -8 15 -10 18 -4 C 13 3 6 3 0 0 Z"
              fill="#0284c7"
              opacity="0.9"
              transform={`rotate(${deg})`}
            />
          ))}
          <circle cx="0" cy="0" r="4.5" fill="#0f172a" stroke="#38bdf8" strokeWidth="0.75" />
        </g>
      </g>

      {/* Section B: Machine Digital Readout LCD */}
      <g transform={`translate(${x + 10}, ${y + 108})`}>
        <rect
          x="0"
          y="0"
          width={width - 20}
          height={16}
          rx="2"
          fill="#0f172a"
          stroke="#38bdf8"
          strokeWidth="0.6"
        />
        <text
          x={(width - 20) / 2}
          y="11.5"
          fill="#38bdf8"
          fontSize="9"
          fontFamily="ui-monospace, SFMono-Regular, Menlo, monospace"
          fontWeight="bold"
          textAnchor="middle"
        >
          {unit.supplyTempC.toFixed(1)}°C • {unit.fanSpeedRpm} RPM
        </text>
      </g>

      {/* Section C: Middle Evaporator Coil Inspection Bay */}
      <rect
        x={x + 6}
        y={y + 132}
        width={width - 12}
        height={110}
        rx="2"
        fill="#f8fafc"
        stroke="#94a3b8"
        strokeWidth="0.75"
      />
      {/* Horizontal Coil Tube Fin Lines */}
      {Array.from({ length: 9 }).map((_, cIdx) => (
        <line
          key={`coil-fin-${cIdx}`}
          x1={x + 10}
          y1={y + 142 + cIdx * 11}
          x2={x + width - 10}
          y2={y + 142 + cIdx * 11}
          stroke="#cbd5e1"
          strokeWidth="1"
          strokeDasharray="4 2"
        />
      ))}
      {/* Technical label for coils */}
      <text
        x={x + width / 2}
        y={y + 188}
        fill="#64748b"
        fontSize="7.5"
        fontFamily="ui-monospace, SFMono-Regular, Menlo, monospace"
        fontWeight="600"
        textAnchor="middle"
        letterSpacing="0.08em"
      >
        CHW COIL BLOCK
      </text>

      {/* Section D: Lower Return Air Intake Louver Grilles */}
      <rect
        x={x + 6}
        y={y + 250}
        width={width - 12}
        height={136}
        rx="2"
        fill="#f1f5f9"
        stroke="#64748b"
        strokeWidth="0.8"
      />
      {/* Clean Horizontal Louver Blades */}
      {Array.from({ length: 11 }).map((_, lIdx) => (
        <line
          key={`intake-louver-${lIdx}`}
          x1={x + 12}
          y1={y + 260 + lIdx * 11}
          x2={x + width - 12}
          y2={y + 260 + lIdx * 11}
          stroke="#475569"
          strokeWidth="1.4"
          strokeLinecap="round"
        />
      ))}

      {/* Heavy Machine Floor Base Plate */}
      <rect
        x={x + 4}
        y={y + height - 14}
        width={width - 8}
        height={10}
        rx="1"
        fill="#334155"
      />

      {/* 6. Restrained Status Beacon Dot (Top-Right) */}
      <ResourceIndicator2D
        health={unit.health}
        x={x + width - 8}
        y={y + 6}
        size={3.8}
      />

      {/* 7. Selection Badge (SHOWN ONLY WHEN CLICKED) */}
      {isSelected && (
        <g className="transition-opacity duration-150">
          <line
            x1={x + width / 2}
            y1={y}
            x2={x + width / 2}
            y2={y - 14}
            stroke="#0284c7"
            strokeWidth="1.2"
          />
          <circle cx={x + width / 2} cy={y} r="2" fill="#0284c7" />
          <g transform={`translate(${x + width / 2 - 32}, ${y - 30})`}>
            <rect
              x="0"
              y="0"
              width="64"
              height="16"
              rx="3"
              fill="#0f172a"
              stroke="#0284c7"
              strokeWidth="1"
            />
            <text
              x="32"
              y="11.5"
              fill="#38bdf8"
              fontSize="9"
              fontFamily="ui-monospace, SFMono-Regular, Menlo, monospace"
              fontWeight="bold"
              textAnchor="middle"
            >
              {unit.id}
            </text>
          </g>
        </g>
      )}
    </g>
  );
};

sources.src/components/datacenter2d/DataCenter2D:
/**
 * 2D Technical Data-Centre Scene
 * Straight layout, consistent perspective, zero diagonal tilt,
 * parallel overhead cooling pipes, strictly contained airflow,
 * and zero default floating labels.
 */

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { ServerRack2D } from './ServerRack2D';
import { CRACUnit2D } from './CRACUnit2D';
import { CoolingPipe2D } from './CoolingPipe2D';
import { VentilationGrille2D } from './VentilationGrille2D';
import { ColdAirflow2D } from './ColdAirflow2D';
import { HotAirflow2D } from './HotAirflow2D';
import { SceneControls2D } from './SceneControls2D';
import { SelectedDetailsPanel2D } from './SelectedDetailsPanel2D';
import { Rack2DData, CRAC2DData } from './types2d';
import { useAO02 } from '../../context/AO02Context';
import { Maximize2, Minimize2 } from 'lucide-react';

interface DataCenter2DSceneProps {
  isExpanded?: boolean;
  onToggleExpand?: () => void;
  heightClass?: string;
}

export const DataCenter2DScene: React.FC<DataCenter2DSceneProps> = ({
  isExpanded = false,
  onToggleExpand,
  heightClass = 'h-[580px]',
}) => {
  const { racks: spatialRacks } = useAO02();

  // Scene Controls State
  const [isAnimating, setIsAnimating] = useState<boolean>(true);
  const [showAirflow, setShowAirflow] = useState<boolean>(true);
  const [showTempOverlay, setShowTempOverlay] = useState<boolean>(false);

  // Selection & Hover State
  const [selectedRackId, setSelectedRackId] = useState<string | null>(null);
  const [selectedCRACId, setSelectedCRACId] = useState<string | null>(null);
  const [hoveredRack, setHoveredRack] = useState<Rack2DData | null>(null);
  const [hoveredCRAC, setHoveredCRAC] = useState<CRAC2DData | null>(null);
  const [tooltipPos, setTooltipPos] = useState<{ x: number; y: number } | null>(null);

  const containerRef = useRef<HTMLDivElement>(null);

  // Keyboard shortcut: Escape deselects
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        setSelectedRackId(null);
        setSelectedCRACId(null);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, []);

  // Map spatial telemetry to 2D rack data
  const racksData2D: Rack2DData[] = useMemo(() => {
    return spatialRacks.map((r) => {
      const isCritical = r.status === 'CRITICAL';
      const isWarning = r.status === 'WARNING';
      const health: 'healthy' | 'warning' | 'critical' = isCritical
        ? 'critical'
        : isWarning
        ? 'warning'
        : 'healthy';

      let riskMetric: 'storage' | 'power' | 'cooling' | 'network' | undefined;
      let riskDaysLeft: number | undefined;
      let riskEvidence: string | undefined;
      let recommendedAction: string | undefined;

      if (r.rackId === 'R-04') {
        riskMetric = 'storage';
        riskDaysLeft = 9;
        riskEvidence = 'FlashArray storage pool saturated at 95.2%. Linear growth +4.2 TB/day.';
        recommendedAction = 'Execute volume tiering migration and deduplication quota expand.';
      } else if (r.rackId === 'R-08') {
        riskMetric = 'power';
        riskDaysLeft = 14;
        riskEvidence = 'Rack PDU load at 14.1 kW / 15.0 kW rated breaker capacity.';
        recommendedAction = 'Rebalance non-production batch compute workloads to Hall B.';
      } else if (r.rackId === 'R-09') {
        riskMetric = 'cooling';
        riskDaysLeft = 19;
        riskEvidence = 'Exhaust Delta-T degraded to 27.5°C due to missing rack blanking panels.';
        recommendedAction = 'Install 4U blanking inserts in slots 12-16 to block recirculation.';
      } else if (r.rackId === 'R-02') {
        riskMetric = 'network';
        riskDaysLeft = 21;
        riskEvidence = 'Top-of-Rack 100G uplink sustaining 88 Gbps peak cross-rack ingress.';
        recommendedAction = 'Enable ECMP secondary spine fabric multipath routing.';
      }

      return {
        id: r.rackId,
        label: `Rack ${r.rackId}`,
        row: r.row,
        gridX: r.gridPosition.x,
        gridZ: r.gridPosition.z,
        tenant: r.tenant,
        health,
        powerKw: r.powerLoadKw,
        powerMaxKw: r.maxPowerKw,
        tempC: r.tempC,
        storageUtil: r.storageUtilPct,
        networkGbps: r.networkGbps,
        riskMetric,
        riskDaysLeft,
        riskEvidence,
        recommendedAction,
      };
    });
  }, [spatialRacks]);

  // Dual CRAC Units (Straight, parallel, identical heights)
  const cracUnits2D: CRAC2DData[] = useMemo(() => {
    return [
      {
        id: 'CRAC-01',
        label: 'CRAC Unit A (North)',
        gridX: -360,
        gridZ: 0,
        supplyTempC: 13.2,
        returnTempC: 26.8,
        fanSpeedRpm: 1422,
        loadKw: 58.4,
        capacityKw: 110.0,
        health: 'healthy',
      },
      {
        id: 'CRAC-02',
        label: 'CRAC Unit B (South)',
        gridX: 360,
        gridZ: 0,
        supplyTempC: 13.5,
        returnTempC: 27.4,
        fanSpeedRpm: 1450,
        loadKw: 62.1,
        capacityKw: 110.0,
        health: 'healthy',
      },
    ];
  }, []);

  const rowARacks = racksData2D.filter((r) => r.row === 'Row A');
  const rowBRacks = racksData2D.filter((r) => r.row === 'Row B');

  // Straight column coordinates (6 perfectly spaced columns)
  const columnXCoordinates = [190, 315, 440, 565, 690, 815];
  const rackWidth = 84;
  const rackHeight = 126;

  // Single horizontal baseline for Row A and Row B
  const rowAY = 145;
  const rowBY = 389;

  // Hover handlers
  const handleRackHover = (rack: Rack2DData, e: React.MouseEvent) => {
    setHoveredRack(rack);
    setHoveredCRAC(null);
    if (containerRef.current) {
      const rect = containerRef.current.getBoundingClientRect();
      setTooltipPos({
        x: Math.min(rect.width - 200, Math.max(12, e.clientX - rect.left + 12)),
        y: Math.max(20, e.clientY - rect.top - 12),
      });
    }
  };

  const handleCRACHover = (crac: CRAC2DData, e: React.MouseEvent) => {
    setHoveredCRAC(crac);
    setHoveredRack(null);
    if (containerRef.current) {
      const rect = containerRef.current.getBoundingClientRect();
      setTooltipPos({
        x: Math.min(rect.width - 200, Math.max(12, e.clientX - rect.left + 12)),
        y: Math.max(20, e.clientY - rect.top - 12),
      });
    }
  };

  const handleLeave = () => {
    setHoveredRack(null);
    setHoveredCRAC(null);
    setTooltipPos(null);
  };

  const selectedRack = racksData2D.find((r) => r.id === selectedRackId) || null;
  const selectedCRAC = cracUnits2D.find((c) => c.id === selectedCRACId) || null;

  return (
    <div
      ref={containerRef}
      className={`relative w-full ${heightClass} bg-[#fbfbfa] flex flex-col justify-between overflow-hidden select-none border border-slate-200/90 rounded-lg`}
      onClick={() => {
        setSelectedRackId(null);
        setSelectedCRACId(null);
      }}
    >
      {/* Top Controls Toolbar */}
      <div className="absolute top-2.5 left-2.5 right-2.5 z-20 flex items-center justify-between pointer-events-auto">
        <SceneControls2D
          isAnimating={isAnimating}
          onToggleAnimation={() => setIsAnimating(!isAnimating)}
          showAirflow={showAirflow}
          onToggleAirflow={() => setShowAirflow(!showAirflow)}
          showTempOverlay={showTempOverlay}
          onToggleTempOverlay={() => setShowTempOverlay(!showTempOverlay)}
          onResetSelection={() => {
            setSelectedRackId(null);
            setSelectedCRACId(null);
          }}
          hasSelection={!!selectedRack || !!selectedCRAC}
        />

        {onToggleExpand && (
          <button
            onClick={(e) => {
              e.stopPropagation();
              onToggleExpand();
            }}
            className="hidden sm:flex items-center gap-1.5 p-2 bg-white/90 hover:bg-white text-slate-700 border border-slate-200/80 rounded-lg text-xs font-medium shadow-2xs ml-2"
            title={isExpanded ? 'Collapse scene' : 'Expand full width'}
          >
            {isExpanded ? <Minimize2 className="w-3.5 h-3.5" /> : <Maximize2 className="w-3.5 h-3.5" />}
          </button>
        )}
      </div>

      {/* Master Straight 2D Vector SVG Canvas */}
      <svg
        viewBox="0 0 1100 590"
        className="w-full h-full object-contain cursor-default"
        preserveAspectRatio="xMidYMid meet"
      >
        <defs>
          {/* Subtle straight background grid */}
          <pattern id="dcStraightGrid" width="30" height="30" patternUnits="userSpaceOnUse">
            <path d="M 30 0 L 0 0 0 30" fill="none" stroke="#f1f5f9" strokeWidth="0.8" />
          </pattern>
        </defs>

        {/* 1. Facility Floor Canvas */}
        <rect width="1100" height="590" fill="#fbfbfa" />
        <rect width="1100" height="590" fill="url(#dcStraightGrid)" opacity="0.75" />

        {/* 2. Hot Aisle A (Upper Exhaust Plenum Band) */}
        <g>
          <rect
            x="165"
            y="102"
            width="770"
            height="38"
            rx="3"
            fill="#fff7ed"
            stroke="#fed7aa"
            strokeWidth="0.8"
          />
          <text
            x="550"
            y="125"
            fill="#ea580c"
            fontSize="8.5"
            fontFamily="ui-monospace, SFMono-Regular, Menlo, monospace"
            fontWeight="bold"
            letterSpacing="0.08em"
            textAnchor="middle"
          >
            ── HOT AISLE A RETURN PLENUM • 26.8°C EXHAUST ──
          </text>
        </g>

        {/* 3. Hot Airflow Behind Row A (when enabled) */}
        {showAirflow &&
          isAnimating &&
          columnXCoordinates.map((cx, i) => (
            <HotAirflow2D
              key={`hot-flow-rowA-${i}`}
              x={cx + rackWidth / 2}
              y={138}
              direction="up"
              speedSeconds={2.2 + (i % 3) * 0.3}
            />
          ))}

        {/* 4. Row A Server Racks (R-01 to R-06, perfectly aligned at Y = 145) */}
        {rowARacks.map((rack, i) => {
          const rx = columnXCoordinates[i];
          if (rx === undefined) return null;
          return (
            <ServerRack2D
              key={rack.id}
              rack={rack}
              x={rx}
              y={rowAY}
              width={rackWidth}
              height={rackHeight}
              isSelected={selectedRackId === rack.id}
              isHovered={hoveredRack?.id === rack.id}
              showTempOverlay={showTempOverlay}
              onSelect={(r) => {
                setSelectedRackId(r.id);
                setSelectedCRACId(null);
              }}
              onHover={handleRackHover}
              onLeave={handleLeave}
            />
          );
        })}

        {/* 5. Central Cold Aisle Containment Band */}
        <g>
          <rect
            x="165"
            y="276"
            width="770"
            height="107"
            rx="3"
            fill="#f0f9ff"
            stroke="#bae6fd"
            strokeWidth="0.8"
          />

          {/* Floor Ventilation Grilles (Aligned with rack columns) */}
          {columnXCoordinates.map((cx, i) => (
            <VentilationGrille2D
              key={`cold-grille-${i}`}
              x={cx}
              y={316}
              width={rackWidth}
              height={24}
            />
          ))}

          {/* Cold Aisle Technical Section Label */}
          <text
            x="550"
            y="368"
            fill="#0284c7"
            fontSize="9"
            fontFamily="ui-monospace, SFMono-Regular, Menlo, monospace"
            fontWeight="bold"
            letterSpacing="0.08em"
            textAnchor="middle"
          >
            ── CENTRAL COLD AISLE CONTAINMENT [ASHRAE A1] • 21.8°C SUPPLY AIRFLOW ──
          </text>
        </g>

        {/* 6. Cold Airflow Rising from Floor Grilles (when enabled) */}
        {showAirflow &&
          isAnimating &&
          columnXCoordinates.map((cx, i) => (
            <ColdAirflow2D
              key={`cold-flow-${i}`}
              x={cx + rackWidth / 2}
              y={316}
              speedSeconds={2.1 + (i % 2) * 0.4}
            />
          ))}

        {/* 7. Row B Server Racks (R-07 to R-12, perfectly aligned at Y = 389) */}
        {rowBRacks.map((rack, i) => {
          const rx = columnXCoordinates[i];
          if (rx === undefined) return null;
          return (
            <ServerRack2D
              key={rack.id}
              rack={rack}
              x={rx}
              y={rowBY}
              width={rackWidth}
              height={rackHeight}
              isSelected={selectedRackId === rack.id}
              isHovered={hoveredRack?.id === rack.id}
              showTempOverlay={showTempOverlay}
              onSelect={(r) => {
                setSelectedRackId(r.id);
                setSelectedCRACId(null);
              }}
              onHover={handleRackHover}
              onLeave={handleLeave}
            />
          );
        })}

        {/* 8. Hot Aisle B (Lower Exhaust Plenum Band) */}
        <g>
          <rect
            x="165"
            y="520"
            width="770"
            height="36"
            rx="3"
            fill="#fff7ed"
            stroke="#fed7aa"
            strokeWidth="0.8"
          />
          <text
            x="550"
            y="542"
            fill="#ea580c"
            fontSize="8.5"
            fontFamily="ui-monospace, SFMono-Regular, Menlo, monospace"
            fontWeight="bold"
            letterSpacing="0.08em"
            textAnchor="middle"
          >
            ── HOT AISLE B RETURN PLENUM • 27.4°C EXHAUST ──
          </text>
        </g>

        {/* 9. Hot Airflow from Row B Exhaust (when enabled) */}
        {showAirflow &&
          isAnimating &&
          columnXCoordinates.map((cx, i) => (
            <HotAirflow2D
              key={`hot-flow-rowB-${i}`}
              x={cx + rackWidth / 2}
              y={524}
              direction="down"
              speedSeconds={2.3 + (i % 3) * 0.3}
            />
          ))}

        {/* 10. Precision CRAC Cooling Unit A (Left Flank) */}
        <CRACUnit2D
          unit={cracUnits2D[0]}
          x={48}
          y={110}
          width={90}
          height={444}
          isSelected={selectedCRACId === cracUnits2D[0].id}
          isHovered={hoveredCRAC?.id === cracUnits2D[0].id}
          onSelect={(c) => {
            setSelectedCRACId(c.id);
            setSelectedRackId(null);
          }}
          onHover={handleCRACHover}
          onLeave={handleLeave}
        />

        {/* 11. Precision CRAC Cooling Unit B (Right Flank) */}
        <CRACUnit2D
          unit={cracUnits2D[1]}
          x={962}
          y={110}
          width={90}
          height={444}
          isSelected={selectedCRACId === cracUnits2D[1].id}
          isHovered={hoveredCRAC?.id === cracUnits2D[1].id}
          onSelect={(c) => {
            setSelectedCRACId(c.id);
            setSelectedRackId(null);
          }}
          onHover={handleCRACHover}
          onLeave={handleLeave}
        />

        {/* 12. Overhead Straight Parallel Cooling Pipes & Ceiling Suspension Hangers */}
        <CoolingPipe2D
          leftX={93}
          rightX={1007}
          returnY={46}
          supplyY={70}
          cracTopY={110}
        />
      </svg>

      {/* Hover Tooltip (Lightweight, appears ONLY during mouse hover) */}
      {tooltipPos && (hoveredRack || hoveredCRAC) && (
        <div
          className="absolute z-30 pointer-events-none bg-slate-900/90 text-white text-xs px-2.5 py-1.5 rounded shadow-lg backdrop-blur-xs border border-slate-700/80 transform -translate-y-full transition-all"
          style={{ left: `${tooltipPos.x}px`, top: `${tooltipPos.y}px` }}
        >
          {hoveredRack && (
            <div className="flex items-center gap-2">
              <span
                className={`w-2 h-2 rounded-full ${
                  hoveredRack.health === 'critical'
                    ? 'bg-rose-500'
                    : hoveredRack.health === 'warning'
                    ? 'bg-amber-500'
                    : 'bg-emerald-500'
                }`}
              />
              <span className="font-mono font-bold">{hoveredRack.label}</span>
              <span className="text-slate-400 font-mono text-[11px]">
                {hoveredRack.riskMetric
                  ? `• ${hoveredRack.riskMetric.toUpperCase()} RISK`
                  : `• ${hoveredRack.tempC.toFixed(1)}°C`}
              </span>
            </div>
          )}
          {hoveredCRAC && (
            <div className="flex items-center gap-2">
              <span className="w-2 h-2 rounded-full bg-sky-400" />
              <span className="font-mono font-bold">{hoveredCRAC.label}</span>
              <span className="text-slate-400 font-mono text-[11px]">
                • {hoveredCRAC.supplyTempC}°C Supply
              </span>
            </div>
          )}
        </div>
      )}

      {/* Docked Selection Details Panel (Appears on right side ONLY when an object is clicked) */}
      {(selectedRack || selectedCRAC) && (
        <div className="absolute top-14 right-3 bottom-3 z-30 flex items-start pointer-events-auto">
          <SelectedDetailsPanel2D
            selectedRack={selectedRack}
            selectedCRAC={selectedCRAC}
            onClose={() => {
              setSelectedRackId(null);
              setSelectedCRACId(null);
            }}
          />
        </div>
      )}
    </div>
  );
};

sources.src/components/datacenter2d/HotAirflow2D:
/**
 * 2D Technical Hot Exhaust Airflow Component
 * Straight vertical muted red/coral chevrons and warm thermal particles.
 * Confined strictly within Hot Aisle plenums without crossing server racks.
 */

import React from 'react';

interface HotAirflow2DProps {
  x: number; // Center X
  y: number; // Base Y (origin in hot aisle)
  direction?: 'up' | 'down';
  speedSeconds?: number;
}

export const HotAirflow2D: React.FC<HotAirflow2DProps> = ({
  x,
  y,
  direction = 'up',
  speedSeconds = 2.4,
}) => {
  const isUp = direction === 'up';
  const deltaY = isUp ? -28 : 24;

  return (
    <g transform={`translate(${x}, ${y})`} className="pointer-events-none select-none">
      <style>{`
        @keyframes hotRiseStraight {
          0% {
            transform: translateY(0px);
            opacity: 0;
          }
          20% {
            opacity: 0.85;
          }
          75% {
            opacity: 0.8;
          }
          100% {
            transform: translateY(${deltaY}px);
            opacity: 0;
          }
        }
        @keyframes hotParticleStraight {
          0% {
            transform: translateY(0px);
            opacity: 0;
          }
          30% {
            opacity: 0.75;
          }
          70% {
            opacity: 0.75;
          }
          100% {
            transform: translateY(${deltaY * 1.2}px);
            opacity: 0;
          }
        }
      `}</style>

      {/* Guide Stream Path (Strictly Vertical) */}
      <line
        x1="0"
        y1="0"
        x2="0"
        y2={deltaY}
        stroke="#fca5a5"
        strokeWidth="0.8"
        strokeDasharray="2 2"
        opacity="0.35"
      />

      {/* Primary Animated Chevron 1 */}
      <g
        style={{
          animation: `hotRiseStraight ${speedSeconds}s cubic-bezier(0.4, 0, 0.2, 1) infinite`,
        }}
      >
        <path
          d={isUp ? 'M -5 5 L 0 0 L 5 5' : 'M -5 -5 L 0 0 L 5 -5'}
          fill="none"
          stroke="#ef4444"
          strokeWidth="1.8"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      </g>

      {/* Secondary Staggered Chevron 2 */}
      <g
        style={{
          animation: `hotRiseStraight ${speedSeconds}s cubic-bezier(0.4, 0, 0.2, 1) infinite`,
          animationDelay: `${speedSeconds * 0.5}s`,
        }}
      >
        <path
          d={isUp ? 'M -4 4 L 0 0 L 4 4' : 'M -4 -4 L 0 0 L 4 -4'}
          fill="none"
          stroke="#f87171"
          strokeWidth="1.5"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      </g>

      {/* Thermal Micro Particulate */}
      <circle
        cx="0"
        cy="0"
        r="1.2"
        fill="#dc2626"
        style={{
          animation: `hotParticleStraight ${speedSeconds * 1.1}s ease-in-out infinite`,
          animationDelay: '0.15s',
        }}
      />
    </g>
  );
};

sources.src/components/datacenter2d/ResourceIndi:
/**
 * Resource Health Indicator Dot (Restrained, technical, small)
 * Green: Healthy | Amber: Warning / Approaching limit | Red: Critical risk
 */

import React from 'react';

interface ResourceIndicator2DProps {
  health: 'healthy' | 'warning' | 'critical';
  x: number;
  y: number;
  size?: number;
}

export const ResourceIndicator2D: React.FC<ResourceIndicator2DProps> = ({
  health,
  x,
  y,
  size = 3.5,
}) => {
  const color =
    health === 'critical' ? '#ef4444' : health === 'warning' ? '#f59e0b' : '#10b981';

  return (
    <g transform={`translate(${x}, ${y})`}>
      {/* Outer subtle halo for critical/warning */}
      {health !== 'healthy' && (
        <circle
          r={size + 2}
          fill={color}
          opacity={health === 'critical' ? 0.35 : 0.25}
          className={health === 'critical' ? 'animate-ping' : ''}
          style={{ animationDuration: '3s' }}
        />
      )}
      {/* Core status indicator dot */}
      <circle r={size} fill={color} stroke="#ffffff" strokeWidth="1" />
    </g>
  );
};

sources.src/components/datacenter2d/SceneControl:
/**
 * 2D Technical Isometric Scene Controls & Compact Legend
 * Minimalist floating toolbar with play/pause, airflow toggle, heatmap toggle, and legend.
 */

import React from 'react';
import { Play, Pause, Wind, Thermometer, RotateCcw } from 'lucide-react';

interface SceneControls2DProps {
  isAnimating: boolean;
  onToggleAnimation: () => void;
  showAirflow: boolean;
  onToggleAirflow: () => void;
  showTempOverlay: boolean;
  onToggleTempOverlay: () => void;
  onResetSelection: () => void;
  hasSelection: boolean;
}

export const SceneControls2D: React.FC<SceneControls2DProps> = ({
  isAnimating,
  onToggleAnimation,
  showAirflow,
  onToggleAirflow,
  showTempOverlay,
  onToggleTempOverlay,
  onResetSelection,
  hasSelection,
}) => {
  return (
    <div className="flex flex-wrap items-center justify-between gap-3 p-2 px-3 bg-white/90 backdrop-blur-xs border border-slate-200/80 rounded-lg text-xs shadow-2xs">
      {/* Left: Minimalist Controls */}
      <div className="flex items-center gap-1.5">
        {/* Play / Pause Airflow */}
        <button
          onClick={onToggleAnimation}
          className={`flex items-center gap-1.5 px-2.5 py-1 rounded-md border font-medium transition-colors ${
            isAnimating
              ? 'bg-slate-100 text-slate-800 border-slate-300 hover:bg-slate-200'
              : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50'
          }`}
          title={isAnimating ? 'Pause mechanical animation' : 'Resume animation'}
        >
          {isAnimating ? (
            <>
              <Pause className="w-3 h-3 text-slate-600" />
              <span className="text-[11px]">Pause Flow</span>
            </>
          ) : (
            <>
              <Play className="w-3 h-3 text-blue-600" />
              <span className="text-[11px]">Play Flow</span>
            </>
          )}
        </button>

        {/* Toggle Airflow Vectors */}
        <button
          onClick={onToggleAirflow}
          className={`flex items-center gap-1.5 px-2.5 py-1 rounded-md border font-medium transition-colors ${
            showAirflow
              ? 'bg-sky-50 text-sky-700 border-sky-300'
              : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50'
          }`}
          title="Toggle cold intake and hot exhaust vectors"
        >
          <Wind className="w-3 h-3 text-sky-600" />
          <span className="text-[11px]">Airflow</span>
        </button>

        {/* Toggle Thermal Heatmap */}
        <button
          onClick={onToggleTempOverlay}
          className={`flex items-center gap-1.5 px-2.5 py-1 rounded-md border font-medium transition-colors ${
            showTempOverlay
              ? 'bg-amber-50 text-amber-800 border-amber-300'
              : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50'
          }`}
          title="Toggle thermal temperature heatmap layer"
        >
          <Thermometer className="w-3 h-3 text-amber-600" />
          <span className="text-[11px]">Thermal Overlay</span>
        </button>

        {/* Reset Selection button (when item is selected) */}
        {hasSelection && (
          <button
            onClick={onResetSelection}
            className="flex items-center gap-1.5 px-2 py-1 rounded-md border border-slate-200 text-slate-600 hover:bg-slate-100 transition-colors"
            title="Deselect (Escape)"
          >
            <RotateCcw className="w-3 h-3" />
            <span className="text-[11px]">Deselect</span>
          </button>
        )}
      </div>

      {/* Right: Technical Legend */}
      <div className="flex items-center gap-3 text-[11px] font-mono text-slate-500">
        <div className="flex items-center gap-1.5">
          <span className="w-2 h-2 rounded-full bg-sky-500 inline-block" />
          <span>Cold Aisle (Supply)</span>
        </div>
        <div className="flex items-center gap-1.5">
          <span className="w-2 h-2 rounded-full bg-rose-500 inline-block" />
          <span>Hot Aisle (Exhaust)</span>
        </div>
        <div className="hidden sm:flex items-center gap-1.5 border-l border-slate-200 pl-3">
          <span className="w-2 h-2 rounded-full bg-emerald-500 inline-block" />
          <span>Nominal</span>
          <span className="w-2 h-2 rounded-full bg-amber-500 inline-block ml-1" />
          <span>Warning</span>
          <span className="w-2 h-2 rounded-full bg-rose-500 inline-block ml-1" />
          <span>Critical</span>
        </div>
      </div>
    </div>
  );
};

sources.src/components/datacenter2d/ServerRack2D:
/**
 * 2D Technical Server Rack Component
 * Perfectly straight vertical rack edges and horizontal server shelves.
 * Zero diagonal tilt, consistent sizing, and restrained technical aesthetic.
 */

import React from 'react';
import { Rack2DData } from './types2d';
import { ResourceIndicator2D } from './ResourceIndicator2D';

interface ServerRack2DProps {
  rack: Rack2DData;
  x: number; // Top-left X
  y: number; // Top-left Y
  width?: number;
  height?: number;
  isSelected: boolean;
  isHovered: boolean;
  showTempOverlay?: boolean;
  onSelect: (rack: Rack2DData) => void;
  onHover: (rack: Rack2DData, event: React.MouseEvent) => void;
  onLeave: () => void;
}

export const ServerRack2D: React.FC<ServerRack2DProps> = ({
  rack,
  x,
  y,
  width = 84,
  height = 126,
  isSelected,
  isHovered,
  showTempOverlay = false,
  onSelect,
  onHover,
  onLeave,
}) => {
  const depthX = 7;
  const depthY = 5;
  const numSlots = 6;
  const topMargin = 8;
  const bottomMargin = 8;
  const usableHeight = height - topMargin - bottomMargin;
  const slotHeight = (usableHeight - (numSlots - 1) * 2) / numSlots;

  // Thermal heat-map overlay color calculation
  const getThermalTint = (tempC: number) => {
    if (tempC < 22) return 'rgba(56, 189, 248, 0.2)'; // cool cyan
    if (tempC < 24) return 'rgba(34, 197, 94, 0.16)'; // nominal green
    if (tempC < 26) return 'rgba(245, 158, 11, 0.22)'; // warm amber
    return 'rgba(239, 68, 68, 0.28)'; // hot red
  };

  // 2.5D Top and Right depth facets (strictly straight, front remains rectangular)
  const topFacePoints = `${x},${y} ${x + width},${y} ${x + width + depthX},${y - depthY} ${x + depthX},${y - depthY}`;
  const sideFacePoints = `${x + width},${y} ${x + width + depthX},${y - depthY} ${x + width + depthX},${y + height - depthY} ${x + width},${y + height}`;

  return (
    <g
      className="cursor-pointer transition-all duration-150 select-none group"
      onClick={(e) => {
        e.stopPropagation();
        onSelect(rack);
      }}
      onMouseEnter={(e) => onHover(rack, e)}
      onMouseLeave={onLeave}
    >
      {/* 1. Subtle Floor Contact Shadow */}
      <rect
        x={x}
        y={y + height}
        width={width + depthX}
        height={3}
        rx="1.5"
        fill="rgba(15, 23, 42, 0.08)"
      />

      {/* 2. Selection Halo Glow / Footprint */}
      {isSelected && (
        <rect
          x={x - 3}
          y={y - depthY - 3}
          width={width + depthX + 6}
          height={height + depthY + 6}
          rx="4"
          fill="rgba(37, 99, 235, 0.08)"
          stroke="#2563eb"
          strokeWidth="1.5"
          strokeDasharray="4 2"
        />
      )}

      {/* 3. Subtle 2.5D Top Roof Facet */}
      <polygon
        points={topFacePoints}
        fill={isHovered ? '#f8fafc' : '#f1f5f9'}
        stroke={isSelected ? '#2563eb' : '#64748b'}
        strokeWidth="0.8"
        strokeLinejoin="round"
      />
      {/* Top fan exhaust slots on roof */}
      <line
        x1={x + width * 0.3}
        y1={y - depthY * 0.5}
        x2={x + width * 0.7}
        y2={y - depthY * 0.5}
        stroke="#94a3b8"
        strokeWidth="1"
        strokeDasharray="2 2"
      />

      {/* 4. Subtle 2.5D Right Side Panel */}
      <polygon
        points={sideFacePoints}
        fill={isHovered ? '#e2e8f0' : '#cbd5e1'}
        stroke={isSelected ? '#2563eb' : '#64748b'}
        strokeWidth="0.8"
        strokeLinejoin="round"
      />
      {/* Vertical side louvers */}
      {[0.25, 0.5, 0.75].map((ratio, i) => (
        <line
          key={`side-louver-${i}`}
          x1={x + width + depthX * 0.5}
          y1={y + height * ratio - 10}
          x2={x + width + depthX * 0.5}
          y2={y + height * ratio + 10}
          stroke="#94a3b8"
          strokeWidth="0.75"
        />
      ))}

      {/* 5. Front Chassis Faceplate (Strictly Rectangular, Vertical & Horizontal) */}
      <rect
        x={x}
        y={y}
        width={width}
        height={height}
        rx="2"
        fill={isHovered ? '#ffffff' : '#f8fafc'}
        stroke={isSelected ? '#2563eb' : isHovered ? '#1e293b' : '#334155'}
        strokeWidth={isSelected ? '1.8' : '1.2'}
      />

      {/* Rack Rails (EIA-310 19-inch vertical mounting rails) */}
      <line
        x1={x + 6}
        y1={y + 3}
        x2={x + 6}
        y2={y + height - 3}
        stroke="#cbd5e1"
        strokeWidth="0.75"
      />
      <line
        x1={x + width - 6}
        y1={y + 3}
        x2={x + width - 6}
        y2={y + height - 3}
        stroke="#cbd5e1"
        strokeWidth="0.75"
      />

      {/* Top Cable Entry Vent Strip */}
      <rect
        x={x + 8}
        y={y + 3}
        width={width - 16}
        height={3}
        fill="#e2e8f0"
        rx="0.5"
      />

      {/* 6. Modular Server Unit Shelves (Horizontal Server Blades) */}
      {Array.from({ length: numSlots }).map((_, slotIdx) => {
        const slotY = y + topMargin + slotIdx * (slotHeight + 2);
        const slotW = width - 14;
        const slotX = x + 7;

        // Activity LED status
        const ledColor =
          rack.health === 'critical' && slotIdx === 2
            ? '#ef4444'
            : rack.health === 'warning' && slotIdx === 3
            ? '#f59e0b'
            : '#10b981';

        return (
          <g key={`server-slot-${slotIdx}`}>
            {/* Shelf Blade Chassis */}
            <rect
              x={slotX}
              y={slotY}
              width={slotW}
              height={slotHeight}
              rx="1"
              fill="#ffffff"
              stroke="#94a3b8"
              strokeWidth="0.6"
            />

            {/* Drive Bay / SFF Caddy Tick Marks (Horizontal alignment) */}
            {[0.2, 0.35, 0.5].map((ratio, dIdx) => (
              <line
                key={`bay-${dIdx}`}
                x1={slotX + slotW * ratio}
                y1={slotY + 2}
                x2={slotX + slotW * ratio}
                y2={slotY + slotHeight - 2}
                stroke="#e2e8f0"
                strokeWidth="0.6"
              />
            ))}

            {/* Micro Pull Handle */}
            <line
              x1={slotX + slotW * 0.65}
              y1={slotY + slotHeight / 2}
              x2={slotX + slotW * 0.82}
              y2={slotY + slotHeight / 2}
              stroke="#cbd5e1"
              strokeWidth="1.2"
              strokeLinecap="round"
            />

            {/* Micro Activity LED */}
            <circle
              cx={slotX + slotW - 5}
              cy={slotY + slotHeight / 2}
              r="1.2"
              fill={ledColor}
            />
          </g>
        );
      })}

      {/* Bottom PDU Kickplate */}
      <rect
        x={x + 8}
        y={y + height - 6}
        width={width - 16}
        height={3}
        fill="#e2e8f0"
        rx="0.5"
      />

      {/* 7. Thermal Heat-map Overlay (When Enabled) */}
      {showTempOverlay && (
        <rect
          x={x}
          y={y}
          width={width}
          height={height}
          rx="2"
          fill={getThermalTint(rack.tempC)}
          style={{ mixBlendMode: 'multiply' }}
          pointerEvents="none"
        />
      )}

      {/* 8. Restrained Status Indicator Dot (Top-Left of Rack Frame) */}
      <ResourceIndicator2D
        health={rack.health}
        x={x + 6}
        y={y + 4}
        size={3.2}
      />

      {/* 9. Selected ID Badge (SHOWN ONLY WHEN CLICKED / SELECTED) */}
      {isSelected && (
        <g className="transition-opacity duration-150">
          {/* Vertical Pointer Line */}
          <line
            x1={x + width / 2}
            y1={y}
            x2={x + width / 2}
            y2={y - 14}
            stroke="#2563eb"
            strokeWidth="1.2"
          />
          <circle cx={x + width / 2} cy={y} r="2" fill="#2563eb" />

          {/* Compact ID Pill Badge */}
          <g transform={`translate(${x + width / 2 - 24}, ${y - 30})`}>
            <rect
              x="0"
              y="0"
              width="48"
              height="16"
              rx="3"
              fill="#0f172a"
              stroke="#2563eb"
              strokeWidth="1"
            />
            <text
              x="24"
              y="11.5"
              fill="#ffffff"
              fontSize="9"
              fontFamily="ui-monospace, SFMono-Regular, Menlo, monospace"
              fontWeight="bold"
              textAnchor="middle"
            >
              {rack.id}
            </text>
          </g>
        </g>
      )}
    </g>
  );
};

