/**
 * Individual Server Unit (Simple outlined technical rectangle with subtle faceplate details)
 */

import React from 'react';

interface ServerUnit2DProps {
  x: number;
  y: number;
  width: number;
  height: number;
  unitIndex: number;
  status: 'healthy' | 'warning' | 'critical';
}

export const ServerUnit2D: React.FC<ServerUnit2DProps> = ({
  x,
  y,
  width,
  height,
  unitIndex,
  status,
}) => {
  const ledColor =
    status === 'critical' ? '#ef4444' : status === 'warning' ? '#f59e0b' : '#10b981';

  return (
    <g transform={`translate(${x}, ${y})`}>
      {/* Server Unit Chassis Faceplate */}
      <rect
        width={width}
        height={height}
        fill="#f8fafc"
        stroke="#475569"
        strokeWidth="0.75"
        rx="1"
      />

      {/* Subtle Drive Bay Slots (4 ticks) */}
      {[0.2, 0.4, 0.6, 0.8].map((ratio, i) => (
        <line
          key={`slot-${i}`}
          x1={width * ratio}
          y1={2}
          x2={width * ratio}
          y2={height - 2}
          stroke="#cbd5e1"
          strokeWidth="0.5"
        />
      ))}

      {/* Micro Status Activity LED */}
      <circle
        cx={width - 5}
        cy={height / 2}
        r={1.2}
        fill={ledColor}
      />
    </g>
  );
};

