/**
 * AO-02 Headless Multi-Agent & Telemetry State Provider
 * Encapsulates Layer 1 connectivity, Priority Token Queue, Shared Context Heap,
 * and strict Tenant Isolation boundaries.
 */

import React, { createContext, useContext, useState, useEffect, useMemo, useCallback, ReactNode } from 'react';
import {
  IncidentToken,
  HeapIncidentEnvelope,
  RackSpatialNode,
  CoolingUnitNode,
  KPIMetrics,
  TenantId,
  PipelinePhase
} from '../types/ao02';
import {
  INITIAL_SPATIAL_RACKS,
  INITIAL_COOLING_UNITS,
  INITIAL_ENVELOPES,
  BASELINE_KPIS
} from '../data/mockAO02Dataset';
import { PriorityTokenQueue } from '../store/priorityQueue';
import { SharedContextHeap } from '../store/sharedHeap';

interface AO02ContextType {
  // Tenant Context & RBAC
  currentTenant: TenantId;
  setCurrentTenant: (tenant: TenantId) => void;
  isFacilityOperator: boolean;

  // Spatial Facility Telemetry
  racks: RackSpatialNode[];
  filteredRacks: RackSpatialNode[];
  coolingUnits: CoolingUnitNode[];
  selectedRackId: string | null;
  setSelectedRackId: (id: string | null) => void;
  selectedMachineId: string | null;
  setSelectedMachineId: (id: string | null) => void;

  // Priority Token Queue ("Queue Dataset")
  tokenQueue: PriorityTokenQueue;
  queuedTokens: IncidentToken[];
  selectedTokenId: string | null;
  setSelectedTokenId: (id: string | null) => void;
  enqueueIncident: (rackId: string, tenantId: string, resourceType: any) => boolean;

  // Shared Context Heap ("Heap Memory") & 6-Phase Pipeline
  sharedHeap: SharedContextHeap;
  activeEnvelope: HeapIncidentEnvelope | null;
  filteredEnvelopes: HeapIncidentEnvelope[];
  advanceAgentPhase: (tokenId: string) => void;
  recordHumanDecision: (tokenId: string, approved: boolean, notes: string) => void;

  // Evaluated KPIs & System Metrics
  kpis: KPIMetrics;
  isBackendConnected: boolean;
  activeViewMode: 'spatial' | 'queue' | 'forecasting' | 'audit';
  setActiveViewMode: (mode: 'spatial' | 'queue' | 'forecasting' | 'audit') => void;
}

const AO02Context = createContext<AO02ContextType | undefined>(undefined);

export const AO02Provider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [currentTenant, setCurrentTenant] = useState<TenantId>('All');
  const [selectedRackId, setSelectedRackId] = useState<string | null>('R-04');
  const [selectedMachineId, setSelectedMachineId] = useState<string | null>(null);
  const [selectedTokenId, setSelectedTokenId] = useState<string | null>('T-01');
  const [activeViewMode, setActiveViewMode] = useState<'spatial' | 'queue' | 'forecasting' | 'audit'>('spatial');
  const [isBackendConnected] = useState<boolean>(false); // default to deterministic simulation mode

  // Initialize Priority Queue and Shared Heap singletons
  const tokenQueue = useMemo(() => {
    const q = new PriorityTokenQueue();
    INITIAL_ENVELOPES.forEach((env) => q.enqueue({ ...env.token }));
    return q;
  }, []);

  const sharedHeap = useMemo(() => {
    const heap = new SharedContextHeap();
    INITIAL_ENVELOPES.forEach((env) => {
      heap.putEnvelope({ ...env }, 'SystemInit', 'Baseline incident envelope loaded into Shared Context Heap.');
    });
    return heap;
  }, []);

  const [queueRevision, setQueueRevision] = useState(0);
  const [heapRevision, setHeapRevision] = useState(0);

  const isFacilityOperator = currentTenant === 'All';

  // Strict Tenant-Filtered Racks
  const filteredRacks = useMemo(() => {
    if (currentTenant === 'All') return INITIAL_SPATIAL_RACKS;
    return INITIAL_SPATIAL_RACKS.map((rack) => {
      if (rack.tenant !== currentTenant) {
        // Mask non-owned tenant racks
        return {
          ...rack,
          status: 'HEALTHY' as const,
          activeBadge: undefined,
          activeTokenIds: [],
        };
      }
      return rack;
    });
  }, [currentTenant]);

  // Strict Tenant-Filtered Envelopes
  const filteredEnvelopes = useMemo(() => {
    // depend on heapRevision to reactively update
    void heapRevision;
    return sharedHeap.listEnvelopes(currentTenant, isFacilityOperator);
  }, [sharedHeap, currentTenant, isFacilityOperator, heapRevision]);

  // Active Selected Incident Envelope
  const activeEnvelope = useMemo(() => {
    if (!selectedTokenId) return filteredEnvelopes[0] || null;
    try {
      return sharedHeap.getTenantIsolatedView(selectedTokenId, currentTenant, isFacilityOperator);
    } catch {
      return null;
    }
  }, [sharedHeap, selectedTokenId, currentTenant, isFacilityOperator, heapRevision]);

  // Snapshot of Priority Queue
  const queuedTokens = useMemo(() => {
    void queueRevision;
    const snap = tokenQueue.snapshot();
    if (isFacilityOperator) return snap;
    return snap.filter((t) => t.tenantId === currentTenant);
  }, [tokenQueue, currentTenant, isFacilityOperator, queueRevision]);

  // Advance token through the 6-Phase LangGraph pipeline
  const advanceAgentPhase = useCallback(
    (tokenId: string) => {
      try {
        const envelope = sharedHeap.getEnvelope(tokenId);
        const current = envelope.token.currentPhase;
        let nextPhase: PipelinePhase = current;
        let actor = 'AgentOrchestrator';
        let summary = '';

        if (current === '01_RESOURCE_MONITORING') {
          nextPhase = '02_INCIDENT_REPORTING';
          actor = 'ResourceMonitoringAgent';
          summary = 'Evaluated 12-month trend; dispatched formal ticket to Incident Reporting Gate.';
        } else if (current === '02_INCIDENT_REPORTING') {
          nextPhase = '03_ROOT_CAUSE_ANALYSIS';
          actor = 'IncidentReportingGate';
          summary = 'Enqueued priority token and dispatched payload to RCA Agent.';
        } else if (current === '03_ROOT_CAUSE_ANALYSIS') {
          nextPhase = '04_REMEDIATION_CHECKING';
          actor = 'RCAAgent';
          summary = 'Correlated workload attribution and routed to Remediation Agent.';
        } else if (current === '04_REMEDIATION_CHECKING') {
          nextPhase = '05_RISK_ANALYSIS';
          actor = 'RemediationAgent';
          summary = 'Calculated read-only advisory capacity options; routed to Risk Engine.';
        } else if (current === '05_RISK_ANALYSIS') {
          nextPhase = '06_HUMAN_VERIFICATION';
          actor = 'RiskEngine';
          summary = 'Evaluated blast radius (Low Risk); awaiting operator verification.';
        } else if (current === '06_HUMAN_VERIFICATION') {
          nextPhase = '07_RESOLVED';
          actor = 'HumanOperatorGate';
          summary = 'Operator approved non-invasive capacity plan. Incident resolved.';
        }

        tokenQueue.incrementHop(envelope.token, nextPhase);
        sharedHeap.putEnvelope(envelope, actor, summary);

        setQueueRevision((r) => r + 1);
        setHeapRevision((r) => r + 1);
      } catch (err: any) {
        console.error('Phase advancement error:', err.message);
      }
    },
    [sharedHeap, tokenQueue]
  );

  // Human-in-the-Loop decision recording
  const recordHumanDecision = useCallback(
    (tokenId: string, approved: boolean, notes: string) => {
      sharedHeap.recordHumanVerification(tokenId, approved, notes);
      setHeapRevision((r) => r + 1);
      setQueueRevision((r) => r + 1);
    },
    [sharedHeap]
  );

  // Enqueue a new capacity incident token
  const enqueueIncident = useCallback(
    (rackId: string, tenantId: string, resourceType: any) => {
      const priorityNum = PriorityTokenQueue.computePriorityNumber(resourceType, 92, 1.5);
      const token: IncidentToken = {
        tokenId: `T-${Math.floor(Math.random() * 900 + 100)}`,
        priorityNumber: priorityNum,
        rackId,
        tenantId,
        resourceType,
        currentPhase: '01_RESOURCE_MONITORING',
        hopCount: 0,
        maxAllowedHops: 8,
        createdAt: new Date().toISOString(),
      };

      const ok = tokenQueue.enqueue(token);
      if (ok) {
        setQueueRevision((r) => r + 1);
      }
      return ok;
    },
    [tokenQueue]
  );

  return (
    <AO02Context.Provider
      value={{
        currentTenant,
        setCurrentTenant,
        isFacilityOperator,
        racks: INITIAL_SPATIAL_RACKS,
        filteredRacks,
        coolingUnits: INITIAL_COOLING_UNITS,
        selectedRackId,
        setSelectedRackId,
        selectedMachineId,
        setSelectedMachineId,
        tokenQueue,
        queuedTokens,
        selectedTokenId,
        setSelectedTokenId,
        enqueueIncident,
        sharedHeap,
        activeEnvelope,
        filteredEnvelopes,
        advanceAgentPhase,
        recordHumanDecision,
        kpis: BASELINE_KPIS,
        isBackendConnected,
        activeViewMode,
        setActiveViewMode,
      }}
    >
      {children}
    </AO02Context.Provider>
  );
};

export const useAO02 = (): AO02ContextType => {
  const context = useContext(AO02Context);
  if (!context) {
    throw new Error('useAO02 must be used within an AO02Provider');
  }
  return context;
};

// Pure Headless Hooks for Decoupled Consumption
export const useFacilityTelemetry = () => {
  const { filteredRacks, coolingUnits, selectedRackId, setSelectedRackId, selectedMachineId, setSelectedMachineId } = useAO02();
  return { filteredRacks, coolingUnits, selectedRackId, setSelectedRackId, selectedMachineId, setSelectedMachineId };
};

export const usePriorityTokenQueue = () => {
  const { queuedTokens, selectedTokenId, setSelectedTokenId, enqueueIncident } = useAO02();
  return { queuedTokens, selectedTokenId, setSelectedTokenId, enqueueIncident };
};

export const useAgentPipelineHeap = () => {
  const { activeEnvelope, filteredEnvelopes, advanceAgentPhase, recordHumanDecision } = useAO02();
  return { activeEnvelope, filteredEnvelopes, advanceAgentPhase, recordHumanDecision };
};

export const useTenantIsolationContext = () => {
  const { currentTenant, setCurrentTenant, isFacilityOperator } = useAO02();
  return { currentTenant, setCurrentTenant, isFacilityOperator };
};

