import React, { createContext, useContext, useState, useEffect, useCallback, ReactNode } from 'react';
import {
  RackData,
  CRACUnitData,
  ResourceMetric,
  AlertItem,
  RootCauseIncident,
  AuditLogEntry,
  SettingsState,
  TenantName,
  SceneMode,
  ToastMessage,
  CoolerFault
} from '../types';
import {
  INITIAL_RACKS,
  INITIAL_CRACS,
  INITIAL_RESOURCES,
  INITIAL_ALERTS,
  INITIAL_ROOT_CAUSE,
  INITIAL_AUDIT_LOGS,
  DEFAULT_SETTINGS
} from '../data/mockData';

interface DataContextType {
  racks: RackData[];
  filteredRacks: RackData[];
  cracUnits: CRACUnitData[];
  resources: ResourceMetric[];
  filteredResources: ResourceMetric[];
  alerts: AlertItem[];
  filteredAlerts: AlertItem[];
  rootCause: RootCauseIncident;
  auditLogs: AuditLogEntry[];
  settings: SettingsState;
  updateSettings: (newSettings: Partial<SettingsState>) => void;
  resetSettings: () => void;
  currentTenant: TenantName;
  setCurrentTenant: (tenant: TenantName) => void;
  selectedRackId: string | null;
  setSelectedRackId: (id: string | null) => void;
  selectedMachineId: string | null;
  setSelectedMachineId: (id: string | null) => void;
  hoveredRackId: string | null;
  setHoveredRackId: (id: string | null) => void;
  sceneMode: SceneMode;
  setSceneMode: (mode: SceneMode) => void;
  isAirflowPlaying: boolean;
  setIsAirflowPlaying: (playing: boolean | ((prev: boolean) => boolean)) => void;
  isSimulating: boolean;
  setIsSimulating: (sim: boolean | ((prev: boolean) => boolean)) => void;
  lastUpdated: Date;
  triggerRefresh: () => void;
  acknowledgeAlert: (alertId: string, note?: string) => void;
  resolveAlert: (alertId: string, note?: string) => void;
  addOperatorNote: (alertId: string, text: string) => void;
  applyRecommendation: (actionId: string) => void;
  toasts: ToastMessage[];
  addToast: (title: string, message?: string, type?: 'success' | 'error' | 'info' | 'warning') => void;
  removeToast: (id: string) => void;
  isSearchOpen: boolean;
  setIsSearchOpen: (open: boolean) => void;
  generateSyntheticTelemetry: () => void;
  importCSVData: (rowCount: number) => { accepted: number; rejected: number };
  activeCoolerFault: CoolerFault | null;
  dismissCoolerFault: () => void;
  triggerCoolerFault: (machineId: string, faultType: 'filter' | 'fan' | 'compressor' | 'water') => void;
  remediateCoolerFault: (machineId: string) => void;
}

const DataContext = createContext<DataContextType | undefined>(undefined);

export const DataProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  // Load settings from localStorage if available
  const [settings, setSettings] = useState<SettingsState>(() => {
    try {
      const saved = localStorage.getItem('capacityiq_settings');
      return saved ? { ...DEFAULT_SETTINGS, ...JSON.parse(saved) } : DEFAULT_SETTINGS;
    } catch {
      return DEFAULT_SETTINGS;
    }
  });

  const [currentTenant, setCurrentTenant] = useState<TenantName>('All Tenants');
  const [racks, setRacks] = useState<RackData[]>(INITIAL_RACKS);
  const [cracUnits, setCracUnits] = useState<CRACUnitData[]>(INITIAL_CRACS);
  const [resources, setResources] = useState<ResourceMetric[]>(INITIAL_RESOURCES);
  const [alerts, setAlerts] = useState<AlertItem[]>(INITIAL_ALERTS);
  const [rootCause, setRootCause] = useState<RootCauseIncident>(INITIAL_ROOT_CAUSE);
  const [auditLogs, setAuditLogs] = useState<AuditLogEntry[]>(INITIAL_AUDIT_LOGS);

  const [selectedRackId, setSelectedRackId] = useState<string | null>('rack-04');
  const [selectedMachineId, setSelectedMachineId] = useState<string | null>(null);
  const [hoveredRackId, setHoveredRackId] = useState<string | null>(null);
  const [sceneMode, setSceneMode] = useState<SceneMode>('normal');
  const [isAirflowPlaying, setIsAirflowPlaying] = useState<boolean>(true);
  const [isSimulating, setIsSimulating] = useState<boolean>(true);
  const [lastUpdated, setLastUpdated] = useState<Date>(new Date());
  const [isSearchOpen, setIsSearchOpen] = useState<boolean>(false);
  const [toasts, setToasts] = useState<ToastMessage[]>([]);
  const [activeCoolerFault, setActiveCoolerFault] = useState<CoolerFault | null>(null);

  const addToast = useCallback((title: string, message?: string, type: 'success' | 'error' | 'info' | 'warning' = 'info') => {
    const id = Math.random().toString(36).substring(2, 9);
    setToasts((prev) => [...prev, { id, title, message, type }]);
    setTimeout(() => {
      setToasts((prev) => prev.filter((t) => t.id !== id));
    }, 4500);
  }, []);

  const removeToast = useCallback((id: string) => {
    setToasts((prev) => prev.filter((t) => t.id !== id));
  }, []);

  const updateSettings = useCallback((newSettings: Partial<SettingsState>) => {
    setSettings((prev) => {
      const updated = { ...prev, ...newSettings };
      try {
        localStorage.setItem('capacityiq_settings', JSON.stringify(updated));
      } catch (e) {
        console.error('Could not save settings', e);
      }
      return updated;
    });
    addToast('Settings Updated', 'Preferences saved to local storage.', 'success');
  }, [addToast]);

  const resetSettings = useCallback(() => {
    setSettings(DEFAULT_SETTINGS);
    try {
      localStorage.setItem('capacityiq_settings', JSON.stringify(DEFAULT_SETTINGS));
    } catch (e) {
      console.error(e);
    }
    addToast('Settings Reset', 'Restored system defaults.', 'info');
  }, [addToast]);

  // Automated Cooler Machine Fault Trigger & Watchdog
  const triggerCoolerFault = useCallback((machineId: string, faultType: 'filter' | 'fan' | 'compressor' | 'water') => {
    const target = cracUnits.find((c) => c.id === machineId) || cracUnits[0];

    let fault: CoolerFault;
    if (faultType === 'filter') {
      fault = {
        id: `fault-${Date.now()}`,
        code: 'CRAC-FLT-102',
        machineId: target.id,
        machineLabel: target.label,
        title: 'HEPA Intake Filter Differential Pressure Breach',
        description: 'Particulate obstruction in intake filter pack causing static pressure surge to 178 Pa (threshold 150 Pa).',
        severity: 'warning',
        timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
        component: 'filter',
        metricValue: '178 Pa',
        thresholdValue: '150 Pa',
        recommendedAction: 'Execute automatic pneumatic pulse clean and schedule filter cartridge replacement.'
      };
    } else if (faultType === 'fan') {
      fault = {
        id: `fault-${Date.now()}`,
        code: 'CRAC-FAN-204',
        machineId: target.id,
        machineLabel: target.label,
        title: 'EC Fan Motor 2 Bearing Thermal Overload & RPM Drop',
        description: 'Impeller speed decelerated from 1,420 RPM to 510 RPM. Motor winding temperature exceeded 85°C.',
        severity: 'critical',
        timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
        component: 'fan',
        metricValue: '510 RPM',
        thresholdValue: '1,200 RPM min',
        recommendedAction: 'Switch airflow redundancy to Standby Fan 2 and ramp primary fan bank to 100% capacity.'
      };
    } else if (faultType === 'compressor') {
      fault = {
        id: `fault-${Date.now()}`,
        code: 'CRAC-CMP-301',
        machineId: target.id,
        machineLabel: target.label,
        title: 'Compressor Stage 1 High Discharge Pressure Trip',
        description: 'Condenser circuit pressure peaked at 410 PSI; thermal protection relay actuated.',
        severity: 'critical',
        timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
        component: 'compressor',
        metricValue: '410 PSI',
        thresholdValue: '350 PSI max',
        recommendedAction: 'Engage secondary scroll compressor circuit and verify chilled water valve positioning.'
      };
    } else {
      fault = {
        id: `fault-${Date.now()}`,
        code: 'CRAC-WTR-405',
        machineId: target.id,
        machineLabel: target.label,
        title: 'Chilled Water Plant Flow Rate Loss',
        description: 'Cooling loop inlet flow restricted down to 72 GPM. Supply air temp rising toward 18.2°C.',
        severity: 'critical',
        timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
        component: 'chilled_water',
        metricValue: '72 GPM',
        thresholdValue: '120 GPM min',
        recommendedAction: 'Actuate bypass valve BV-102 and increase secondary circulation pump header pressure.'
      };
    }

    // Update CRAC machine in state
    setCracUnits((prev) =>
      prev.map((c) =>
        c.id === target.id
          ? {
              ...c,
              health: fault.severity === 'critical' ? 'critical' : 'warning',
              status: fault.severity === 'critical' ? 'maintenance' : 'operational',
              fanStatus: faultType === 'fan' ? 'degraded' : c.fanStatus,
              fanSpeedRpm: faultType === 'fan' ? 510 : c.fanSpeedRpm,
              filterPressurePa: faultType === 'filter' ? 178 : c.filterPressurePa,
              chilledWaterFlowGpm: faultType === 'water' ? 72 : c.chilledWaterFlowGpm,
              supplyTempC: faultType === 'water' || faultType === 'compressor' ? 18.2 : c.supplyTempC,
              activeFault: fault
            }
          : c
      )
    );

    // Automatically display the alert popup immediately!
    setActiveCoolerFault(fault);

    // Register into global alert feed
    const newAlert: AlertItem = {
      id: `alt-cooler-${Date.now()}`,
      title: `${target.label}: ${fault.title}`,
      resourceId: target.id,
      resourceName: target.label,
      tenant: 'Facility Infrastructure',
      severity: fault.severity,
      status: 'active',
      timestamp: new Date().toISOString().replace('T', ' ').substring(0, 16),
      predictedExhaustion: 'Immediate (Thermal Runaway Risk)',
      metric: fault.component.toUpperCase(),
      value: fault.metricValue,
      threshold: fault.thresholdValue,
      recommendedAction: fault.recommendedAction,
      operatorNotes: [
        { author: 'Automated Diagnostic Engine', text: `Telemetry threshold breached: ${fault.description}`, time: fault.timestamp }
      ]
    };

    setAlerts((prev) => [newAlert, ...prev]);

    // Register into Audit Log
    setAuditLogs((prev) => [
      {
        id: `aud-${Date.now()}`,
        timestamp: new Date().toISOString().replace('T', ' ').substring(0, 19),
        actor: { name: 'Cooler Hardware Diagnostic Watchdog', role: 'Telemetry Daemon' },
        action: 'MACHINE_FAULT_DETECTED',
        resource: target.label,
        details: `${fault.code}: ${fault.title} (${fault.metricValue})`,
        outcome: fault.severity === 'critical' ? 'failed' : 'warning'
      },
      ...prev
    ]);

    addToast(
      `Machine Fault Detected: ${target.label}`,
      `${fault.title} (${fault.metricValue})`,
      fault.severity === 'critical' ? 'error' : 'warning'
    );
  }, [cracUnits, addToast]);

  const dismissCoolerFault = useCallback(() => {
    setActiveCoolerFault(null);
  }, []);

  const remediateCoolerFault = useCallback((machineId: string) => {
    setCracUnits((prev) =>
      prev.map((c) =>
        c.id === machineId
          ? {
              ...c,
              health: 'healthy',
              status: 'operational',
              fanStatus: 'running',
              fanSpeedRpm: 1420,
              filterPressurePa: 95,
              chilledWaterFlowGpm: 142,
              supplyTempC: 13.2,
              activeFault: null
            }
          : c
      )
    );

    setActiveCoolerFault(null);

    setAuditLogs((prev) => [
      {
        id: `aud-${Date.now()}`,
        timestamp: new Date().toISOString().replace('T', ' ').substring(0, 19),
        actor: { name: 'Current User', role: 'Capacity Engineer' },
        action: 'MACHINE_FAULT_REMEDIATED',
        resource: machineId,
        details: 'Dispatched automated bypass and restored nominal setpoint tolerances',
        outcome: 'success'
      },
      ...prev
    ]);

    addToast('Machine Fault Remediated', 'Cooler restored to nominal operating parameters.', 'success');
  }, [addToast]);

  // Subtle real-time simulation tick
  useEffect(() => {
    if (!isSimulating) return;

    const interval = setInterval(() => {
      setLastUpdated(new Date());

      // Jitter racks
      setRacks((prev) =>
        prev.map((rack) => {
          const pwrDelta = (Math.random() - 0.5) * 0.1;
          const tempDelta = (Math.random() - 0.5) * 0.08;
          const netDelta = (Math.random() - 0.5) * 1.5;

          const newPwr = Math.max(2, Math.min(rack.powerMaxKw, Number((rack.powerKw + pwrDelta).toFixed(2))));
          const newTemp = Math.max(18, Math.min(35, Number((rack.tempC + tempDelta).toFixed(1))));
          const newNet = Math.max(5, Math.min(rack.networkMaxGbps, Math.round(rack.networkGbps + netDelta)));

          return {
            ...rack,
            powerKw: newPwr,
            tempC: newTemp,
            networkGbps: newNet,
          };
        })
      );

      // Jitter CRACs when healthy
      setCracUnits((prev) =>
        prev.map((crac) => {
          if (crac.activeFault) return crac; // don't jitter faulted values
          const fanJitter = Math.round((Math.random() - 0.5) * 8);
          const flowJitter = Number(((Math.random() - 0.5) * 0.5).toFixed(1));
          return {
            ...crac,
            loadKw: Number((crac.loadKw + (Math.random() - 0.5) * 0.2).toFixed(1)),
            airflowCfm: Math.round(crac.airflowCfm + (Math.random() - 0.5) * 40),
            fanSpeedRpm: Math.max(1300, Math.min(1550, crac.fanSpeedRpm + fanJitter)),
            chilledWaterFlowGpm: Math.max(135, Math.min(155, crac.chilledWaterFlowGpm + flowJitter)),
          };
        })
      );
    }, settings.refreshIntervalSec * 1000);

    return () => clearInterval(interval);
  }, [isSimulating, settings.refreshIntervalSec]);

  // Filtered views based on selected tenant
  const filteredRacks = currentTenant === 'All Tenants'
    ? racks
    : racks.filter((r) => r.tenant === currentTenant);

  const filteredResources = currentTenant === 'All Tenants'
    ? resources
    : resources.filter((r) => r.tenant === currentTenant || r.tenant === 'All Tenants');

  const filteredAlerts = currentTenant === 'All Tenants'
    ? alerts
    : alerts.filter((a) => a.tenant === currentTenant || a.tenant === 'All Tenants');

  const triggerRefresh = useCallback(() => {
    setLastUpdated(new Date());
    addToast('Telemetry Synchronized', 'Polled latest capacity metrics across 12 racks and 2 CRAC machines.', 'info');
  }, [addToast]);

  const acknowledgeAlert = useCallback((alertId: string, note?: string) => {
    setAlerts((prev) =>
      prev.map((a) => {
        if (a.id === alertId) {
          const notes = a.operatorNotes || [];
          if (note) {
            notes.push({
              author: 'Operator (Current User)',
              text: note,
              time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
            });
          }
          return { ...a, status: 'acknowledged', operatorNotes: notes };
        }
        return a;
      })
    );

    setAuditLogs((prev) => [
      {
        id: `aud-${Date.now()}`,
        timestamp: new Date().toISOString().replace('T', ' ').substring(0, 19),
        actor: { name: 'Current User', role: 'Capacity Engineer' },
        action: 'ALERT_ACKNOWLEDGED',
        resource: alertId,
        details: note ? `Acknowledged alert: "${note}"` : 'Acknowledged alert without note',
        outcome: 'success'
      },
      ...prev
    ]);

    addToast('Alert Acknowledged', `Alert ${alertId} status marked as acknowledged.`, 'success');
  }, [addToast]);

  const resolveAlert = useCallback((alertId: string, note?: string) => {
    setAlerts((prev) =>
      prev.map((a) => {
        if (a.id === alertId) {
          const notes = a.operatorNotes || [];
          if (note) {
            notes.push({
              author: 'Operator (Current User)',
              text: note,
              time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
            });
          }
          return { ...a, status: 'resolved', operatorNotes: notes };
        }
        return a;
      })
    );

    setAuditLogs((prev) => [
      {
        id: `aud-${Date.now()}`,
        timestamp: new Date().toISOString().replace('T', ' ').substring(0, 19),
        actor: { name: 'Current User', role: 'Capacity Engineer' },
        action: 'ALERT_RESOLVED',
        resource: alertId,
        details: note ? `Resolved alert: "${note}"` : 'Resolved alert',
        outcome: 'success'
      },
      ...prev
    ]);

    addToast('Alert Resolved', `Alert ${alertId} has been resolved and archived.`, 'success');
  }, [addToast]);

  const addOperatorNote = useCallback((alertId: string, text: string) => {
    if (!text.trim()) return;
    setAlerts((prev) =>
      prev.map((a) => {
        if (a.id === alertId) {
          const notes = a.operatorNotes || [];
          return {
            ...a,
            operatorNotes: [
              ...notes,
              {
                author: 'Operator (Current User)',
                text: text.trim(),
                time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
              }
            ]
          };
        }
        return a;
      })
    );
    addToast('Note Appended', 'Operator note saved to alert record.', 'info');
  }, [addToast]);

  const applyRecommendation = useCallback((actionId: string) => {
    setRootCause((prev) => ({
      ...prev,
      recommendedActions: prev.recommendedActions.map((act) =>
        act.id === actionId ? { ...act, status: 'applied' } : act
      )
    }));

    if (actionId === 'act-01' || actionId === 'act-02') {
      setRacks((prev) =>
        prev.map((r) =>
          r.id === 'rack-04'
            ? {
                ...r,
                storageUtil: 72,
                health: 'warning',
                risk: r.risk
                  ? {
                      ...r.risk,
                      currentUtil: 72,
                      daysToExhaustion: 28,
                      evidence: 'Remediation applied: Compression freed 14 TB; buffer extended.',
                      recommendedAction: 'Continue monitoring LZ4 ratio.'
                    }
                  : null
              }
            : r
        )
      );

      setResources((prev) =>
        prev.map((res) =>
          res.id === 'res-stor-01'
            ? {
                ...res,
                currentUsage: 72.0,
                utilPercent: 72.0,
                status: 'warning',
                predictedExhaustionDays: 28,
                predictedDate: '2026-11-25'
              }
            : res
        )
      );
    }

    setAuditLogs((prev) => [
      {
        id: `aud-${Date.now()}`,
        timestamp: new Date().toISOString().replace('T', ' ').substring(0, 19),
        actor: { name: 'Current User', role: 'Capacity Engineer' },
        action: 'REMEDIATION_ACTION_APPLIED',
        resource: 'RCA Action ' + actionId,
        details: 'Applied preventive action policy to telemetry controller',
        outcome: 'success'
      },
      ...prev
    ]);

    addToast('Remediation Applied', 'Capacity mitigation policy dispatched to controller.', 'success');
  }, [addToast]);

  const generateSyntheticTelemetry = useCallback(() => {
    const timestamp = new Date().toISOString().replace('T', ' ').substring(0, 19);
    setAuditLogs((prev) => [
      {
        id: `aud-${Date.now()}`,
        timestamp,
        actor: { name: 'Synthetic Telemetry Generator', role: 'Data Engine' },
        action: 'SYNTHETIC_TELEMETRY_GENERATED',
        resource: 'All 12 Racks & 2 CRAC Machines',
        details: 'Simulated 14,400 high-frequency sensor readings (500Hz burst).',
        outcome: 'success'
      },
      ...prev
    ]);
    triggerRefresh();
    addToast('Synthetic Batch Generated', '14,400 metric tuples generated and validated.', 'success');
  }, [triggerRefresh, addToast]);

  const importCSVData = useCallback((rowCount: number) => {
    const accepted = Math.floor(rowCount * 0.98);
    const rejected = rowCount - accepted;

    setAuditLogs((prev) => [
      {
        id: `aud-${Date.now()}`,
        timestamp: new Date().toISOString().replace('T', ' ').substring(0, 19),
        actor: { name: 'Current User', role: 'Data Administrator' },
        action: 'CSV_DATASET_IMPORTED',
        resource: 'Telemetric Batch File',
        details: `Imported ${accepted} records (${rejected} rejected due to formatting).`,
        outcome: rejected > 0 ? 'warning' : 'success'
      },
      ...prev
    ]);

    addToast(
      'CSV Dataset Processed',
      `Accepted: ${accepted.toLocaleString()} rows | Rejected: ${rejected} rows.`,
      rejected > 0 ? 'warning' : 'success'
    );

    return { accepted, rejected };
  }, [addToast]);

  return (
    <DataContext.Provider
      value={{
        racks,
        filteredRacks,
        cracUnits,
        resources,
        filteredResources,
        alerts,
        filteredAlerts,
        rootCause,
        auditLogs,
        settings,
        updateSettings,
        resetSettings,
        currentTenant,
        setCurrentTenant,
        selectedRackId,
        setSelectedRackId,
        selectedMachineId,
        setSelectedMachineId,
        hoveredRackId,
        setHoveredRackId,
        sceneMode,
        setSceneMode,
        isAirflowPlaying,
        setIsAirflowPlaying,
        isSimulating,
        setIsSimulating,
        lastUpdated,
        triggerRefresh,
        acknowledgeAlert,
        resolveAlert,
        addOperatorNote,
        applyRecommendation,
        toasts,
        addToast,
        removeToast,
        isSearchOpen,
        setIsSearchOpen,
        generateSyntheticTelemetry,
        importCSVData,
        activeCoolerFault,
        dismissCoolerFault,
        triggerCoolerFault,
        remediateCoolerFault,
      }}
    >
      {children}
    </DataContext.Provider>
  );
};

export const useData = () => {
  const context = useContext(DataContext);
  if (!context) {
    throw new Error('useData must be used within a DataProvider');
  }
  return context;
};

