/**
 * AO-02 12-Month Multi-Tenant Telemetry Generator & Deterministic Baseline
 * Racks R-01 to R-12, CRAC Units A/B, Tenants T1/T2/T3, and Pre-configured Incident Tokens.
 */

import {
  IncidentToken,
  HeapIncidentEnvelope,
  RackSpatialNode,
  CoolingUnitNode,
  KPIMetrics,
  TimeSeriesDataPoint
} from '../types/ao02';

// 4 Evaluated AO-02 Performance KPIs
export const BASELINE_KPIS: KPIMetrics = {
  forecastAccuracyPct: 94.2,
  averageLeadTimeWeeks: 3.4,
  falseAlarmSuppressionRatePct: 96.8,
  auditabilityScorePct: 98.5,
};

// Spatial Racks R-01 to R-12
export const INITIAL_SPATIAL_RACKS: RackSpatialNode[] = [
  // Row A (Back Row, Z = -2.2)
  { rackId: 'R-01', row: 'Row A', gridPosition: { x: -5, z: -2.2 }, status: 'HEALTHY', tenant: 'T1', powerLoadKw: 7.2, maxPowerKw: 15.0, tempC: 21.8, storageUtilPct: 44, networkGbps: 32, activeTokenIds: [] },
  { rackId: 'R-02', row: 'Row A', gridPosition: { x: -3, z: -2.2 }, status: 'WARNING', activeBadge: 'NETWORK', tenant: 'T2', powerLoadKw: 9.8, maxPowerKw: 15.0, tempC: 23.4, storageUtilPct: 62, networkGbps: 88, activeTokenIds: ['T-02'] },
  { rackId: 'R-03', row: 'Row A', gridPosition: { x: -1, z: -2.2 }, status: 'HEALTHY', tenant: 'T2', powerLoadKw: 6.5, maxPowerKw: 15.0, tempC: 22.0, storageUtilPct: 51, networkGbps: 28, activeTokenIds: [] },
  { rackId: 'R-04', row: 'Row A', gridPosition: { x: 1, z: -2.2 }, status: 'CRITICAL', activeBadge: 'STORAGE', tenant: 'T1', powerLoadKw: 11.4, maxPowerKw: 15.0, tempC: 24.6, storageUtilPct: 95.2, networkGbps: 64, activeTokenIds: ['T-01'] },
  { rackId: 'R-05', row: 'Row A', gridPosition: { x: 3, z: -2.2 }, status: 'HEALTHY', tenant: 'T3', powerLoadKw: 8.1, maxPowerKw: 15.0, tempC: 22.4, storageUtilPct: 38, networkGbps: 41, activeTokenIds: [] },
  { rackId: 'R-06', row: 'Row A', gridPosition: { x: 5, z: -2.2 }, status: 'HEALTHY', tenant: 'T3', powerLoadKw: 7.8, maxPowerKw: 15.0, tempC: 22.1, storageUtilPct: 45, networkGbps: 35, activeTokenIds: [] },

  // Row B (Front Row, Z = +2.2)
  { rackId: 'R-07', row: 'Row B', gridPosition: { x: -5, z: 2.2 }, status: 'HEALTHY', tenant: 'T2', powerLoadKw: 6.9, maxPowerKw: 15.0, tempC: 21.9, storageUtilPct: 39, networkGbps: 24, activeTokenIds: [] },
  { rackId: 'R-08', row: 'Row B', gridPosition: { x: -3, z: 2.2 }, status: 'CRITICAL', activeBadge: 'POWER', tenant: 'T3', powerLoadKw: 14.1, maxPowerKw: 15.0, tempC: 25.8, storageUtilPct: 71, networkGbps: 76, activeTokenIds: ['T-04'] },
  { rackId: 'R-09', row: 'Row B', gridPosition: { x: -1, z: 2.2 }, status: 'WARNING', activeBadge: 'THERMAL_COOLING', tenant: 'T1', powerLoadKw: 10.2, maxPowerKw: 15.0, tempC: 27.5, storageUtilPct: 78, networkGbps: 58, activeTokenIds: ['T-03'] },
  { rackId: 'R-10', row: 'Row B', gridPosition: { x: 1, z: 2.2 }, status: 'HEALTHY', tenant: 'T2', powerLoadKw: 7.1, maxPowerKw: 15.0, tempC: 22.2, storageUtilPct: 42, networkGbps: 31, activeTokenIds: [] },
  { rackId: 'R-11', row: 'Row B', gridPosition: { x: 3, z: 2.2 }, status: 'HEALTHY', tenant: 'T1', powerLoadKw: 8.4, maxPowerKw: 15.0, tempC: 22.7, storageUtilPct: 59, networkGbps: 45, activeTokenIds: [] },
  { rackId: 'R-12', row: 'Row B', gridPosition: { x: 5, z: 2.2 }, status: 'HEALTHY', tenant: 'T3', powerLoadKw: 6.2, maxPowerKw: 15.0, tempC: 21.5, storageUtilPct: 34, networkGbps: 22, activeTokenIds: [] },
];

// Dual CRAC Precision Cooling Units
export const INITIAL_COOLING_UNITS: CoolingUnitNode[] = [
  {
    unitId: 'CRAC Unit A (North)',
    label: 'CRAC Unit A (North) | 13.2°C supply • 1422 RPM',
    position: [-7.8, 0, 0],
    rotationY: Math.PI * 0.35,
    supplyTempCelsius: 13.2,
    returnTempCelsius: 26.8,
    fanSpeedRpm: 1422,
    status: 'HEALTHY',
  },
  {
    unitId: 'CRAC Unit B (South)',
    label: 'CRAC Unit B (South) | 13.5°C supply',
    position: [7.8, 0, 0],
    rotationY: -Math.PI * 0.25,
    supplyTempCelsius: 13.5,
    returnTempCelsius: 27.4,
    fanSpeedRpm: 1450,
    status: 'HEALTHY',
  },
];

// Seeded Incident Envelopes with Full Provenance Chain
export const INITIAL_ENVELOPES: HeapIncidentEnvelope[] = [
  // Token T-01: R-04 Primary SAN Flash Storage Saturation
  {
    token: {
      tokenId: 'T-01',
      priorityNumber: 12, // High priority
      rackId: 'R-04',
      tenantId: 'T1',
      resourceType: 'STORAGE',
      currentPhase: '05_RISK_ANALYSIS',
      hopCount: 4,
      maxAllowedHops: 8,
      createdAt: new Date(Date.now() - 3600000 * 5).toISOString(),
    },
    telemetry: {
      windowStart: new Date(Date.now() - 3600000 * 24 * 30).toISOString(),
      windowEnd: new Date().toISOString(),
      rackId: 'R-04',
      tenantId: 'T1',
      resourceType: 'STORAGE',
      currentUtilizationPct: 95.2,
      safetyMarginPct: 80.0,
      hardCapacityLimit: 100.0,
      unit: 'TB',
      rawSeriesSha256: '9f86d081884c7d659a2feaa0c55ad015a3bf4f1b2b0b822cd15d6c15b0f00a08',
