/**
 * Generates 12-Month Daily Multi-Tenant Time-Series for Forecasting Charts
 * Includes historical ground-truth curve, regime shifts, and forward projection cone.
 */
export function generate12MonthTimeSeries(
  resourceType: 'STORAGE' | 'POWER' | 'NETWORK' | 'THERMAL_COOLING' = 'STORAGE'
): TimeSeriesDataPoint[] {
  const points: TimeSeriesDataPoint[] = [];
  const totalDays = 365 + 60; // 365 historical days + 60 forecast projection days
  const now = new Date();
  const startDate = new Date(now.getTime() - 365 * 24 * 3600000);

  let baseline = resourceType === 'STORAGE' ? 42 : resourceType === 'POWER' ? 6.8 : resourceType === 'NETWORK' ? 35 : 21.5;
  const growthRate = resourceType === 'STORAGE' ? 0.12 : resourceType === 'POWER' ? 0.015 : resourceType === 'NETWORK' ? 0.08 : 0.012;

  for (let i = 0; i < totalDays; i++) {
    const d = new Date(startDate.getTime() + i * 24 * 3600000);
    const dateStr = d.toISOString().split('T')[0];
    const isForecast = i >= 365;

    // Introduce regime shift at day 290 (~2.5 months ago)
    const isRegimeShift = i === 290;
    const regimeMultiplier = i > 290 ? 1.45 : 1.0;

    // Introduce transient spike at day 330 that resolved within 2 days
    const isTransientSpike = i >= 330 && i <= 332;
    const spikeBump = isTransientSpike ? 24 : 0;

    // Daily seasonal noise
    const noise = (Math.sin(i * 0.2) + Math.cos(i * 0.05)) * 1.5;

    baseline += growthRate * regimeMultiplier;
    const actualVal = Math.min(100, Math.max(10, baseline + noise + spikeBump));

    if (!isForecast) {
      points.push({
        timestamp: d.toISOString(),
        dateStr,
        actualValue: parseFloat(actualVal.toFixed(1)),
        utilizationPct: parseFloat(actualVal.toFixed(1)),
        isRegimeShiftPoint: isRegimeShift,
        isTransientSpikePoint: isTransientSpike,
      });
    } else {
      // Forecast projection with widening confidence cone
      const forecastDaysAhead = i - 365;
      const forecastMean = Math.min(100, baseline + growthRate * regimeMultiplier * forecastDaysAhead);
      const fanSpread = forecastDaysAhead * 0.28;

      points.push({
        timestamp: d.toISOString(),
        dateStr,
        actualValue: parseFloat(actualVal.toFixed(1)),
        utilizationPct: parseFloat(actualVal.toFixed(1)),
        forecastMean: parseFloat(forecastMean.toFixed(1)),
        forecastUpper: parseFloat(Math.min(100, forecastMean + fanSpread).toFixed(1)),
        forecastLower: parseFloat(Math.max(0, forecastMean - fanSpread).toFixed(1)),
      });
    }
  }

  return points;
}

