import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  AlertTriangle,
  CheckCircle,
  Clock,
  Search,
  Check,
  RotateCcw,
  Box,
  TrendingUp,
  MessageSquare,
  Send,
  Building2,
  Calendar,
  XCircle,
  ShieldCheck
} from 'lucide-react';
import { useData } from '../context/DataContext';
import { AlertItem } from '../types';

export const Alerts: React.FC = () => {
  const navigate = useNavigate();
  const {
    filteredAlerts,
    acknowledgeAlert,
    resolveAlert,
    addOperatorNote,
    setSelectedRackId,
    addToast
  } = useData();

  const [selectedAlertId, setSelectedAlertId] = useState<string>('alt-001');
  const [statusFilter, setStatusFilter] = useState<'all' | 'active' | 'acknowledged' | 'resolved'>('all');
  const [severityFilter, setSeverityFilter] = useState<'all' | 'critical' | 'warning' | 'info'>('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [newNoteText, setNewNoteText] = useState('');

  const filtered = filteredAlerts.filter((a) => {
    const matchesStatus = statusFilter === 'all' || a.status === statusFilter;
    const matchesSeverity = severityFilter === 'all' || a.severity === severityFilter;
    const matchesSearch =
      a.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
      a.resourceName.toLowerCase().includes(searchQuery.toLowerCase()) ||
      a.tenant.toLowerCase().includes(searchQuery.toLowerCase());

    return matchesStatus && matchesSeverity && matchesSearch;
  });

  const selectedAlert = filteredAlerts.find((a) => a.id === selectedAlertId) || filtered[0] || null;

  const handleAddNote = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newNoteText.trim() || !selectedAlert) return;
    addOperatorNote(selectedAlert.id, newNoteText.trim());
    setNewNoteText('');
  };

  return (
    <div className="p-4 sm:p-6 space-y-5 max-w-[1600px] mx-auto select-none">
      {/* Top Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3 border-b border-slate-200/80 pb-4">
        <div>
          <h1 className="text-xl font-bold text-slate-900 tracking-tight">
            Capacity Alerts & Early Warnings
          </h1>
          <p className="text-xs text-slate-500 mt-0.5">
            Prioritised operational anomalies detected by continuous capacity forecasting models.
          </p>
        </div>

        <div className="flex items-center gap-2">
          <span className="text-xs font-mono text-slate-500">
            {filteredAlerts.filter((a) => a.status === 'active').length} Active Alerts
          </span>
        </div>
      </div>

      {/* Filter and Search Bar */}
      <div className="flex flex-col md:flex-row items-stretch md:items-center justify-between gap-3 bg-white p-3 rounded-lg border border-slate-200 shadow-2xs">
        <div className="relative flex-1 max-w-sm">
          <Search className="w-3.5 h-3.5 text-slate-400 absolute left-2.5 top-1/2 -translate-y-1/2" />
          <input
            type="text"
            placeholder="Search alerts by title or resource..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-8 pr-3 py-1.5 rounded-md border border-slate-200 text-xs focus:outline-none focus:border-blue-500"
          />
        </div>

        {/* Status Filters */}
        <div className="flex items-center gap-1 text-xs">
          {(['all', 'active', 'acknowledged', 'resolved'] as const).map((st) => (
            <button
              key={st}
              onClick={() => setStatusFilter(st)}
              className={`px-3 py-1 rounded-md capitalize transition-colors font-medium ${
                statusFilter === st
                  ? 'bg-blue-50 text-blue-700 font-semibold border border-blue-200'
                  : 'text-slate-600 hover:bg-slate-100'
              }`}
            >
              {st}
            </button>
          ))}
        </div>

        {/* Severity Filters */}
        <div className="flex items-center gap-1 text-xs">
          {(['all', 'critical', 'warning', 'info'] as const).map((sev) => (
            <button
              key={sev}
              onClick={() => setSeverityFilter(sev)}
              className={`px-2.5 py-1 rounded-md capitalize transition-colors font-medium ${
                severityFilter === sev
                  ? 'bg-slate-900 text-white'
                  : 'text-slate-600 hover:bg-slate-100'
              }`}
            >
              {sev}
            </button>
          ))}
        </div>
      </div>

      {/* Two Column Layout: Alert List + Selected Alert Details Drawer */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-4 items-start">
        {/* Left Column: Alerts List (7 Cols) */}
        <div className="lg:col-span-7 bg-white rounded-lg border border-slate-200 shadow-xs divide-y divide-slate-100 overflow-hidden">
          {filtered.length === 0 ? (
            <div className="p-12 text-center text-slate-400 text-xs space-y-2">
              <CheckCircle className="w-8 h-8 text-emerald-500 mx-auto" />
              <div className="font-semibold text-slate-700">No alerts found</div>
              <p>All monitored capacity limits are within safe operating margins.</p>
            </div>
          ) : (
            filtered.map((alt) => {
              const isSelected = selectedAlert?.id === alt.id;
              return (
                <div
                  key={alt.id}
                  onClick={() => setSelectedAlertId(alt.id)}
                  className={`p-3.5 cursor-pointer transition-colors space-y-2 ${
                    isSelected ? 'bg-blue-50/50 border-l-4 border-l-blue-600' : 'hover:bg-slate-50'
                  }`}
                >
                  <div className="flex items-start justify-between gap-2">
                    <div className="flex items-center gap-2">
                      <span
                        className={`w-2 h-2 rounded-full ${
                          alt.severity === 'critical'
                            ? 'bg-rose-500 animate-pulse'
                            : alt.severity === 'warning'
                            ? 'bg-amber-500'
                            : 'bg-blue-500'
                        }`}
                      />
                      <h4 className="font-semibold text-xs text-slate-900">{alt.title}</h4>
                    </div>

                    <div className="flex items-center gap-1.5 shrink-0">
                      <span
                        className={`text-[10px] font-mono font-bold px-1.5 py-0.2 rounded uppercase ${
                          alt.severity === 'critical'
                            ? 'bg-rose-100 text-rose-800'
                            : alt.severity === 'warning'
                            ? 'bg-amber-100 text-amber-800'
                            : 'bg-slate-100 text-slate-700'
                        }`}
                      >
                        {alt.severity}
                      </span>
                      <span
                        className={`text-[10px] font-mono px-1.5 py-0.2 rounded capitalize ${
                          alt.status === 'active'
                            ? 'bg-rose-50 text-rose-700 border border-rose-200'
                            : alt.status === 'acknowledged'
                            ? 'bg-amber-50 text-amber-700 border border-amber-200'
                            : 'bg-emerald-50 text-emerald-700 border border-emerald-200'
                        }`}
                      >
                        {alt.status}
                      </span>
                    </div>
                  </div>

                  <p className="text-xs text-slate-600 leading-relaxed">
                    {alt.recommendedAction}
                  </p>

                  <div className="flex items-center justify-between text-[11px] font-mono text-slate-500 pt-1">
                    <div className="flex items-center gap-3">
                      <span>{alt.tenant}</span>
                      <span>•</span>
                      <span>{alt.metric}: <strong className="text-slate-800">{alt.value}</strong></span>
                    </div>
                    <span className="text-rose-600 font-semibold">{alt.predictedExhaustion}</span>
                  </div>
                </div>
              );
            })
          )}
        </div>

        {/* Right Column: Selected Alert Detail Panel (5 Cols) */}
        <div className="lg:col-span-5 bg-white rounded-lg border border-slate-200 shadow-xs p-4 space-y-4">
          {selectedAlert ? (
            <>
              {/* Header */}
              <div className="border-b border-slate-100 pb-3 space-y-1.5">
                <div className="flex items-center justify-between">
                  <span className="font-mono text-[10px] uppercase tracking-wider text-slate-400">
                    Incident Record #{selectedAlert.id}
                  </span>
                  <span className="font-mono text-[11px] text-slate-500">
                    {selectedAlert.timestamp}
                  </span>
                </div>
                <h3 className="font-bold text-sm text-slate-900 leading-snug">
                  {selectedAlert.title}
                </h3>
                <div className="flex items-center gap-2 text-xs text-slate-600">
                  <Building2 className="w-3.5 h-3.5 text-slate-400" />
                  <span>Tenant: {selectedAlert.tenant}</span>
                  {selectedAlert.rackId && (
                    <>
                      <span>•</span>
                      <span className="font-mono font-semibold text-blue-600">
                        {selectedAlert.rackId.toUpperCase()}
                      </span>
                    </>
                  )}
                </div>
              </div>

              {/* Status & Exhaustion Banner */}
              <div className="p-3 rounded-lg bg-amber-50/70 border border-amber-200 space-y-2 text-xs">
                <div className="flex justify-between items-center">
                  <span className="font-semibold text-amber-900">Exhaustion Forecast:</span>
                  <span className="font-mono font-bold px-2 py-0.5 rounded bg-amber-200 text-amber-900">
                    {selectedAlert.predictedExhaustion}
                  </span>
                </div>
                <div className="flex justify-between items-center text-[11px] text-slate-600">
                  <span>Current Metric Value:</span>
                  <span className="font-mono font-bold text-slate-900">{selectedAlert.value}</span>
                </div>
                <div className="flex justify-between items-center text-[11px] text-slate-600">
                  <span>Configured Warning Threshold:</span>
                  <span className="font-mono text-slate-700">{selectedAlert.threshold}</span>
                </div>
              </div>

              {/* Recommended Action */}
              <div className="space-y-1.5 text-xs">
                <span className="font-semibold text-slate-800 font-mono text-[11px] uppercase tracking-wider">
                  Recommended Remediation
                </span>
                <p className="text-slate-700 bg-slate-50 p-2.5 rounded-md border border-slate-200 leading-relaxed">
                  {selectedAlert.recommendedAction}
                </p>
              </div>

              {/* Action Buttons: Acknowledge, Resolve, 3D View */}
              <div className="flex flex-wrap items-center gap-2 pt-2 border-t border-slate-100">
                {selectedAlert.status === 'active' && (
                  <button
                    onClick={() => acknowledgeAlert(selectedAlert.id)}
                    className="flex-1 flex items-center justify-center gap-1.5 px-3 py-1.5 bg-amber-600 hover:bg-amber-700 text-white rounded-md text-xs font-medium transition-colors shadow-2xs"
                  >
                    <Check className="w-3.5 h-3.5" />
                    <span>Acknowledge</span>
                  </button>
                )}

                {selectedAlert.status !== 'resolved' && (
                  <button
                    onClick={() => resolveAlert(selectedAlert.id)}
                    className="flex-1 flex items-center justify-center gap-1.5 px-3 py-1.5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-md text-xs font-medium transition-colors shadow-2xs"
                  >
                    <CheckCircle className="w-3.5 h-3.5" />
                    <span>Resolve Alert</span>
                  </button>
                )}

                {selectedAlert.rackId && (
                  <button
                    onClick={() => {
                      setSelectedRackId(selectedAlert.rackId!);
                      navigate('/');
                    }}
                    className="flex items-center gap-1 px-3 py-1.5 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-md text-xs font-medium transition-colors"
                  >
                    <Box className="w-3.5 h-3.5 text-slate-500" />
                    <span>Locate in 3D</span>
                  </button>
                )}

                <button
                  onClick={() => navigate('/root-cause')}
                  className="flex items-center gap-1 px-3 py-1.5 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-md text-xs font-medium transition-colors"
                >
                  <TrendingUp className="w-3.5 h-3.5 text-slate-500" />
                  <span>View RCA</span>
                </button>
              </div>

              {/* Operator Notes History & Add Note form */}
              <div className="pt-3 border-t border-slate-100 space-y-2 text-xs">
                <span className="font-semibold text-slate-800 font-mono text-[11px] uppercase tracking-wider flex items-center gap-1.5">
                  <MessageSquare className="w-3.5 h-3.5 text-slate-400" />
                  Operator Notes ({selectedAlert.operatorNotes?.length || 0})
                </span>

                <div className="space-y-1.5 max-h-36 overflow-y-auto">
                  {selectedAlert.operatorNotes && selectedAlert.operatorNotes.length > 0 ? (
                    selectedAlert.operatorNotes.map((note, i) => (
                      <div key={i} className="p-2 rounded bg-slate-50 border border-slate-100 text-[11px]">
                        <div className="flex justify-between font-mono text-[10px] text-slate-400 mb-0.5">
                          <span className="font-semibold text-slate-700">{note.author}</span>
                          <span>{note.time}</span>
                        </div>
                        <p className="text-slate-700">{note.text}</p>
                      </div>
                    ))
                  ) : (
                    <div className="text-slate-400 italic text-[11px] py-1">
                      No operator notes appended yet.
                    </div>
                  )}
                </div>

                <form onSubmit={handleAddNote} className="flex items-center gap-2 pt-1">
                  <input
                    type="text"
                    placeholder="Add operational notes or change ticket #..."
                    value={newNoteText}
                    onChange={(e) => setNewNoteText(e.target.value)}
                    className="flex-1 px-2.5 py-1.5 rounded-md border border-slate-200 text-xs focus:outline-none focus:border-blue-500"
                  />
                  <button
                    type="submit"
                    disabled={!newNoteText.trim()}
                    className="p-1.5 bg-blue-600 disabled:bg-slate-300 text-white rounded-md transition-colors"
                  >
                    <Send className="w-3.5 h-3.5" />
                  </button>
                </form>
              </div>
            </>
          ) : (
            <div className="p-8 text-center text-slate-400 text-xs">
              Select an alert to review full incident context.
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

sources.src/pages/AuditLogs.tsx:
import React, { useState } from 'react';
import {
  FileText,
  Search,
  Filter,
  Download,
  CheckCircle,
  AlertTriangle,
  XCircle,
  User,
  Cpu
} from 'lucide-react';
import { useData } from '../context/DataContext';

export const AuditLogs: React.FC = () => {
  const { auditLogs, addToast } = useData();
  const [searchQuery, setSearchQuery] = useState('');
  const [outcomeFilter, setOutcomeFilter] = useState<'all' | 'success' | 'warning' | 'failed'>('all');

  const filteredLogs = auditLogs.filter((log) => {
    const matchesSearch =
      log.action.toLowerCase().includes(searchQuery.toLowerCase()) ||
      log.resource.toLowerCase().includes(searchQuery.toLowerCase()) ||
      log.actor.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      log.details.toLowerCase().includes(searchQuery.toLowerCase());

    const matchesOutcome = outcomeFilter === 'all' || log.outcome === outcomeFilter;

    return matchesSearch && matchesOutcome;
  });

  const handleExport = () => {
    const jsonContent = 'data:text/json;charset=utf-8,' + encodeURIComponent(JSON.stringify(filteredLogs, null, 2));
    const link = document.createElement('a');
    link.setAttribute('href', jsonContent);
    link.setAttribute('download', `capacityiq_audit_trail_${new Date().toISOString().substring(0, 10)}.json`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    addToast('Audit Log Exported', 'Downloaded complete forensic log JSON.', 'info');
  };

  return (
    <div className="p-4 sm:p-6 space-y-5 max-w-[1600px] mx-auto select-none">
      {/* Top Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3 border-b border-slate-200/80 pb-4">
        <div>
          <h1 className="text-xl font-bold text-slate-900 tracking-tight">
            Audit Logs & Operational Governance
          </h1>
          <p className="text-xs text-slate-500 mt-0.5">
            Immutable trace of operator acknowledgements, capacity mitigations, and automated forecasting runs.
          </p>
        </div>

        <button
          onClick={handleExport}
          className="flex items-center gap-1.5 px-3 py-1.5 bg-white border border-slate-200 hover:bg-slate-50 text-slate-700 rounded-md text-xs font-medium transition-colors shadow-2xs self-start sm:self-auto"
        >
          <Download className="w-3.5 h-3.5 text-slate-500" />
          <span>Export JSON</span>
        </button>
      </div>

      {/* Filter and Search Bar */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 bg-white p-3 rounded-lg border border-slate-200 shadow-2xs">
        <div className="relative flex-1 max-w-sm">
          <Search className="w-3.5 h-3.5 text-slate-400 absolute left-2.5 top-1/2 -translate-y-1/2" />
          <input
            type="text"
            placeholder="Search audit actions, operators, or target resources..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-8 pr-3 py-1.5 rounded-md border border-slate-200 text-xs focus:outline-none focus:border-blue-500"
          />
        </div>

        <div className="flex items-center gap-1 text-xs">
          {(['all', 'success', 'warning', 'failed'] as const).map((out) => (
            <button
              key={out}
              onClick={() => setOutcomeFilter(out)}
              className={`px-3 py-1 rounded-md capitalize transition-colors font-medium ${
                outcomeFilter === out
                  ? 'bg-slate-900 text-white'
                  : 'text-slate-600 hover:bg-slate-100'
              }`}
            >
              {out}
            </button>
          ))}
        </div>
      </div>

      {/* Audit Log Table */}
      <div className="bg-white rounded-lg border border-slate-200 shadow-xs overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-xs">
            <thead className="bg-slate-50/80 text-[11px] font-mono uppercase text-slate-500 border-b border-slate-200">
              <tr>
                <th className="py-2.5 px-3.5">Timestamp (UTC)</th>
                <th className="py-2.5 px-3.5">Actor / Origin</th>
                <th className="py-2.5 px-3.5">Action Event</th>
                <th className="py-2.5 px-3.5">Resource Target</th>
                <th className="py-2.5 px-3.5">Details & Rationale</th>
                <th className="py-2.5 px-3.5 text-right">Outcome</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredLogs.map((log) => (
                <tr key={log.id} className="hover:bg-slate-50/60 transition-colors">
                  <td className="py-2.5 px-3.5 font-mono text-slate-600 text-[11px]">
                    {log.timestamp}
                  </td>
                  <td className="py-2.5 px-3.5">
                    <div className="flex items-center gap-1.5">
                      <span className="font-semibold text-slate-900">{log.actor.name}</span>
                      <span className="text-[10px] text-slate-400 font-mono">({log.actor.role})</span>
                    </div>
                  </td>
                  <td className="py-2.5 px-3.5 font-mono text-[11px] font-semibold text-blue-700">
                    {log.action}
                  </td>
                  <td className="py-2.5 px-3.5 font-mono text-slate-800 font-medium">
                    {log.resource}
                  </td>
                  <td className="py-2.5 px-3.5 text-slate-600 max-w-md truncate">
                    {log.details}
                  </td>
                  <td className="py-2.5 px-3.5 text-right">
                    <span
                      className={`inline-flex items-center gap-1 px-2 py-0.5 rounded text-[10px] font-mono font-bold uppercase ${
                        log.outcome === 'success'
                          ? 'bg-emerald-50 text-emerald-700 border border-emerald-200'
                          : log.outcome === 'warning'
                          ? 'bg-amber-50 text-amber-700 border border-amber-200'
                          : 'bg-rose-50 text-rose-700 border border-rose-200'
                      }`}
                    >
                      {log.outcome === 'success' && <CheckCircle className="w-3 h-3 text-emerald-500" />}
                      {log.outcome === 'warning' && <AlertTriangle className="w-3 h-3 text-amber-500" />}
                      {log.outcome === 'failed' && <XCircle className="w-3 h-3 text-rose-500" />}
                      {log.outcome}
                    </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

