import React, { useState } from 'react';
import {
  Box,
  Layers,
  Thermometer,
  Zap,
  Wind,
  Filter,
  CheckCircle,
  AlertTriangle,
  Server,
  ArrowRight,
  Sliders
} from 'lucide-react';
import { useData } from '../context/DataContext';
import { DataCenterScene } from '../components/datacenter/DataCenterScene';
import { DataCenter2DScene } from '../components/datacenter2d/DataCenter2DScene';
import { RackDetailDrawer } from '../components/datacenter/RackDetailDrawer';

export const DataCenter: React.FC = () => {
  const {
    filteredRacks,
    cracUnits,
    selectedRackId,
    setSelectedRackId,
    setSelectedMachineId,
    settings,
  } = useData();

  const [activeHall, setActiveHall] = useState('Hall A (Primary Production)');
  const [rowFilter, setRowFilter] = useState<'all' | 'Row A' | 'Row B'>('all');
  const [viewportMode, setViewportMode] = useState<'2d' | '3d'>('2d');

  const selectedRack = filteredRacks.find((r) => r.id === selectedRackId) || null;

  const displayRacks = filteredRacks.filter(
    (r) => rowFilter === 'all' || r.row === rowFilter
  );

  return (
    <div className="p-4 sm:p-6 space-y-5 max-w-[1700px] mx-auto select-none">
      {/* Top Facility Control & Selector Bar */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3 border-b border-slate-200/80 pb-4">
        <div>
          <div className="flex items-center gap-2">
            <h1 className="text-xl font-bold text-slate-900 tracking-tight">
              Data Centre Digital Twin
            </h1>
            <span className="font-mono text-xs px-2 py-0.5 rounded bg-emerald-50 text-emerald-700 border border-emerald-200">
              Facility Environment Live
            </span>
          </div>
          <p className="text-xs text-slate-500 mt-0.5">
            Real-time containment CFD simulation, chilled loop telemetry, and rack rack-level diagnostics.
          </p>
        </div>

        {/* Room / Hall Selector */}
        <div className="flex items-center gap-1.5 bg-slate-100 p-1 rounded-lg text-xs font-medium">
          {['Hall A (Primary Production)', 'Hall B (GPU Cluster)', 'Edge Micro-DC'].map((hall) => (
            <button
              key={hall}
              onClick={() => setActiveHall(hall)}
              className={`px-3 py-1.5 rounded-md transition-all ${
                activeHall === hall
                  ? 'bg-white text-slate-900 shadow-xs font-semibold'
                  : 'text-slate-600 hover:text-slate-900'
              }`}
            >
              {hall}
            </button>
          ))}
        </div>
      </div>

      {/* Facility Environmental Telemetry Gauges */}
      <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-6 gap-3 text-xs">
        <div className="p-3 bg-white rounded-lg border border-slate-200 shadow-2xs">
          <span className="text-[10px] font-mono uppercase text-slate-400">PUE EFFICIENCY</span>
          <div className="mt-1 flex items-baseline gap-1.5">
            <span className="text-lg font-bold font-mono text-emerald-600">1.18</span>
            <span className="text-[10px] text-emerald-700 font-medium">Optimal</span>
          </div>
          <span className="text-[10px] text-slate-400">Industry benchmark 1.45</span>
        </div>

        <div className="p-3 bg-white rounded-lg border border-slate-200 shadow-2xs">
          <span className="text-[10px] font-mono uppercase text-slate-400">FACILITY LOAD</span>
          <div className="mt-1 flex items-baseline gap-1.5">
            <span className="text-lg font-bold font-mono text-slate-900">104.2 kW</span>
            <span className="text-[10px] text-slate-500">/ 180 kW</span>
          </div>
          <span className="text-[10px] text-slate-400">57.8% Busway util</span>
        </div>

        <div
          onClick={() => setSelectedMachineId('crac-01')}
          className="p-3 bg-white rounded-lg border border-slate-200 hover:border-blue-400 cursor-pointer transition-colors shadow-2xs group"
          title="Click to inspect CRAC Machine Diagnostics"
        >
          <div className="flex items-center justify-between">
            <span className="text-[10px] font-mono uppercase text-slate-400 group-hover:text-blue-600">CRAC MACHINE LOAD</span>
            <span className="text-[9px] font-mono text-blue-600 underline">Diagnostics →</span>
          </div>
          <div className="mt-1 flex items-baseline gap-1.5">
            <span className="text-lg font-bold font-mono text-slate-900">117.6 kW</span>
            <span className="text-[10px] text-emerald-600">2 Units</span>
          </div>
          <span className="text-[10px] text-slate-400">170 kW Total • EC Fans</span>
        </div>

        <div className="p-3 bg-white rounded-lg border border-slate-200 shadow-2xs">
          <span className="text-[10px] font-mono uppercase text-slate-400">CHILLED WATER SUPPLY</span>
          <div className="mt-1 flex items-baseline gap-1.5">
            <span className="text-lg font-bold font-mono text-sky-600">13.2°C</span>
            <span className="text-[10px] text-slate-500">Loop A</span>
          </div>
          <span className="text-[10px] text-slate-400">Return: 26.8°C (Δ13.6°)</span>
        </div>

        <div className="p-3 bg-white rounded-lg border border-slate-200 shadow-2xs">
          <span className="text-[10px] font-mono uppercase text-slate-400">COLD AISLE AMBIENT</span>
          <div className="mt-1 flex items-baseline gap-1.5">
            <span className="text-lg font-bold font-mono text-sky-600">22.3°C</span>
            <span className="text-[10px] text-emerald-600">Nominal</span>
          </div>
          <span className="text-[10px] text-slate-400">ASHRAE A1 Compliant</span>
        </div>

        <div className="p-3 bg-white rounded-lg border border-slate-200 shadow-2xs">
          <span className="text-[10px] font-mono uppercase text-slate-400">TOTAL AIRFLOW VOLUME</span>
          <div className="mt-1 flex items-baseline gap-1.5">
            <span className="text-lg font-bold font-mono text-slate-900">29,700</span>
            <span className="text-[10px] text-slate-500">CFM</span>
          </div>
          <span className="text-[10px] text-slate-400">Variable Speed EC Fans</span>
        </div>
      </div>

      {/* Full 3D Interactive Facility Area */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-4">
        {/* Main 3D Canvas */}
        <div className="lg:col-span-8 xl:col-span-9 bg-white rounded-lg border border-slate-200 shadow-xs overflow-hidden">
          <div className="p-3 border-b border-slate-100 flex items-center justify-between bg-slate-50/60">
            <div className="flex items-center gap-2">
              <span className="w-2 h-2 rounded-full bg-emerald-500" />
              <span className="font-semibold text-xs text-slate-800">
                {activeHall} — Multi-Angle Orbit Model
              </span>
            </div>
            <div className="flex items-center gap-2">
              {/* Viewport Mode: 2D View vs 3D View */}
              <div className="flex items-center gap-1 bg-slate-200/80 p-0.5 rounded text-[11px] font-mono">
                <button
                  onClick={() => setViewportMode('2d')}
                  className={`px-2.5 py-1 rounded flex items-center gap-1.5 transition-all cursor-pointer ${
                    viewportMode === '2d'
                      ? 'bg-white text-slate-900 shadow-2xs font-semibold'
                      : 'text-slate-600 hover:text-slate-900'
                  }`}
                >
                  <Layers className="w-3.5 h-3.5 text-blue-600" />
                  <span>2D View</span>
                </button>
                <button
                  onClick={() => setViewportMode('3d')}
                  className={`px-2.5 py-1 rounded flex items-center gap-1.5 transition-all cursor-pointer ${
                    viewportMode === '3d'
                      ? 'bg-white text-slate-900 shadow-2xs font-semibold'
                      : 'text-slate-600 hover:text-slate-900'
                  }`}
                >
                  <Box className="w-3.5 h-3.5" />
                  <span>3D View</span>
                </button>
              </div>

              {/* Row filter (active in 3D facility mode) */}
              {viewportMode === '3d' && (
                <div className="hidden sm:flex items-center gap-1 bg-slate-200/70 p-0.5 rounded text-[11px] font-mono">
                  <button
                    onClick={() => setRowFilter('all')}
                    className={`px-2 py-0.5 rounded ${
                      rowFilter === 'all' ? 'bg-white text-slate-900 shadow-2xs font-semibold' : 'text-slate-600'
                    }`}
                  >
                    Both Rows
                  </button>
                  <button
                    onClick={() => setRowFilter('Row A')}
                    className={`px-2 py-0.5 rounded ${
                      rowFilter === 'Row A' ? 'bg-white text-slate-900 shadow-2xs font-semibold' : 'text-slate-600'
                    }`}
                  >
                    Row A
                  </button>
                  <button
                    onClick={() => setRowFilter('Row B')}
                    className={`px-2 py-0.5 rounded ${
                      rowFilter === 'Row B' ? 'bg-white text-slate-900 shadow-2xs font-semibold' : 'text-slate-600'
                    }`}
                  >
                    Row B
                  </button>
                </div>
              )}
            </div>
          </div>

          {viewportMode === '2d' ? (
            <DataCenter2DScene heightClass="h-[620px]" />
          ) : (
            <DataCenterScene heightClass="h-[620px]" />
          )}
        </div>

        {/* Side Rack Detail or Facility Breakdown */}
        <div className="lg:col-span-4 xl:col-span-3 space-y-3">
          {selectedRack ? (
            <RackDetailDrawer
              rack={selectedRack}
              onClose={() => setSelectedRackId(null)}
              tempUnit={settings.tempUnit}
            />
          ) : (
            <div className="bg-white rounded-lg border border-slate-200 shadow-xs p-3.5 space-y-3">
              <div className="flex items-center justify-between border-b border-slate-100 pb-2">
                <h3 className="font-semibold text-xs text-slate-900 font-mono">
                  FACILITY RACK DIRECTORY ({displayRacks.length})
                </h3>
                <span className="text-[10px] text-slate-400">Click to focus</span>
              </div>

              <div className="space-y-1.5 max-h-[550px] overflow-y-auto pr-1">
                {displayRacks.map((rack) => (
                  <div
                    key={rack.id}
                    onClick={() => setSelectedRackId(rack.id)}
                    className="p-2 rounded-md border border-slate-100 bg-slate-50/50 hover:bg-slate-100/80 cursor-pointer transition-colors flex items-center justify-between text-xs"
                  >
                    <div className="flex items-center gap-2">
                      <span
                        className={`w-2 h-2 rounded-full ${
                          rack.health === 'critical'
                            ? 'bg-rose-500'
                            : rack.health === 'warning'
                            ? 'bg-amber-500'
                            : 'bg-emerald-500'
                        }`}
                      />
                      <div>
                        <div className="font-mono font-bold text-slate-900">{rack.label}</div>
                        <div className="text-[10px] text-slate-400">{rack.tenant} • {rack.row}</div>
                      </div>
                    </div>

                    <div className="text-right text-[11px] font-mono">
                      <div className="text-slate-800 font-semibold">{rack.tempC}°C</div>
                      <div className="text-slate-400">{rack.powerKw.toFixed(1)} kW</div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

