import React, { useState } from 'react';
import {
  Upload,
  Download,
  Database,
  CheckCircle,
  AlertTriangle,
  FileText,
  Sparkles,
  RefreshCw,
  Clock,
  ArrowRight
} from 'lucide-react';
import { useData } from '../context/DataContext';

export const DataManagement: React.FC = () => {
  const { generateSyntheticTelemetry, importCSVData, addToast } = useData();

  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [isUploading, setIsUploading] = useState(false);
  const [acceptedCount, setAcceptedCount] = useState<number>(14280);
  const [rejectedCount, setRejectedCount] = useState<number>(12);
  const [validationStatus, setValidationStatus] = useState<'nominal' | 'warning' | 'idle'>('nominal');

  const [previewRows, setPreviewRows] = useState([
    { timestamp: '2026-10-28 14:15:00', rack_id: 'R-04', sensor_type: 'storage_used_tb', raw_val: '84.0', status: 'VALID' },
    { timestamp: '2026-10-28 14:15:00', rack_id: 'R-08', sensor_type: 'pdu_kw_draw', raw_val: '14.2', status: 'VALID' },
    { timestamp: '2026-10-28 14:15:00', rack_id: 'R-02', sensor_type: 'tor_uplink_gbps', raw_val: '88.0', status: 'VALID' },
    { timestamp: '2026-10-28 14:15:00', rack_id: 'R-09', sensor_type: 'ambient_temp_c', raw_val: '25.1', status: 'VALID' },
    { timestamp: '2026-10-28 14:15:00', rack_id: 'CRAC-01', sensor_type: 'supply_water_c', raw_val: '13.2', status: 'VALID' },
    { timestamp: '2026-10-28 14:14:55', rack_id: 'R-01', sensor_type: 'power_draw_kw', raw_val: '7.2', status: 'VALID' },
  ]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setSelectedFile(file);
      simulateUpload(file.name);
    }
  };

  const simulateUpload = (fileName: string) => {
    setIsUploading(true);
    setTimeout(() => {
      setIsUploading(false);
      const res = importCSVData(4200);
      setAcceptedCount((prev) => prev + res.accepted);
      setRejectedCount((prev) => prev + res.rejected);
      setValidationStatus('nominal');
    }, 900);
  };

  const handleDownloadSample = () => {
    const csvContent =
      'timestamp,rack_id,sensor_type,metric_value,unit,tenant\n' +
      '2026-10-28T14:00:00Z,R-04,storage_used,84.0,TB,Acme Cloud\n' +
      '2026-10-28T14:00:00Z,R-08,pdu_power,14.2,kW,Acme Cloud\n' +
      '2026-10-28T14:00:00Z,R-02,tor_network,88.0,Gbps,FinTech Core\n' +
      '2026-10-28T14:00:00Z,R-09,ambient_temp,25.1,C,RetailStream\n' +
      '2026-10-28T14:00:00Z,CRAC-01,supply_temp,13.2,C,Facility Loop';

    const encodedUri = encodeURI('data:text/csv;charset=utf-8,' + csvContent);
    const link = document.createElement('a');
    link.setAttribute('href', encodedUri);
    link.setAttribute('download', 'capacityiq_telemetry_schema_template.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    addToast('Template Downloaded', 'CapacityIQ standard CSV template generated.', 'info');
  };

  return (
    <div className="p-4 sm:p-6 space-y-5 max-w-[1600px] mx-auto select-none">
      {/* Top Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3 border-b border-slate-200/80 pb-4">
        <div>
          <div className="flex items-center gap-2">
            <h1 className="text-xl font-bold text-slate-900 tracking-tight">
              Data Management & Telemetry Ingestion
            </h1>
            <span className="font-mono text-xs px-2 py-0.5 rounded bg-emerald-50 text-emerald-700 border border-emerald-200">
              Ingestion Active
            </span>
          </div>
          <p className="text-xs text-slate-500 mt-0.5">
            Ingest batch CSV telemetry archives, calibrate schema validators, and run synthetic load tests.
          </p>
        </div>

        <div className="flex items-center gap-2">
          <button
            onClick={generateSyntheticTelemetry}
            className="flex items-center gap-1.5 px-3 py-1.5 bg-blue-600 hover:bg-blue-700 text-white rounded-md text-xs font-medium transition-colors shadow-2xs"
          >
            <Sparkles className="w-3.5 h-3.5" />
            <span>Generate Telemetry Batch</span>
          </button>
          <button
            onClick={handleDownloadSample}
            className="flex items-center gap-1.5 px-3 py-1.5 bg-white border border-slate-200 hover:bg-slate-50 text-slate-700 rounded-md text-xs font-medium transition-colors shadow-2xs"
          >
            <Download className="w-3.5 h-3.5 text-slate-500" />
            <span>Download Sample CSV</span>
          </button>
        </div>
      </div>

      {/* Accepted / Rejected Records Metric Counters */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 text-xs">
        <div className="p-3 bg-white rounded-lg border border-slate-200 shadow-2xs">
          <span className="text-[10px] font-mono uppercase text-slate-400">INGESTION PIPELINE STATUS</span>
          <div className="mt-1 flex items-baseline gap-2">
            <span className="text-lg font-bold font-mono text-emerald-600">OPERATIONAL</span>
          </div>
          <span className="text-[10px] text-slate-500">Latency: 14ms • Streaming active</span>
        </div>

        <div className="p-3 bg-white rounded-lg border border-slate-200 shadow-2xs">
          <span className="text-[10px] font-mono uppercase text-slate-400">ACCEPTED RECORDS</span>
          <div className="mt-1 flex items-baseline gap-2">
            <span className="text-lg font-bold font-mono text-slate-900">
              {acceptedCount.toLocaleString()}
            </span>
            <span className="text-[10px] text-emerald-600 font-medium">99.9% pass</span>
          </div>
          <span className="text-[10px] text-slate-500">Validated against JSON schema</span>
        </div>

        <div className="p-3 bg-white rounded-lg border border-slate-200 shadow-2xs">
          <span className="text-[10px] font-mono uppercase text-slate-400">REJECTED RECORDS</span>
          <div className="mt-1 flex items-baseline gap-2">
            <span className="text-lg font-bold font-mono text-rose-600">
              {rejectedCount}
            </span>
            <span className="text-[10px] text-slate-500">Dead-letter queue</span>
          </div>
          <span className="text-[10px] text-slate-400">Missing ISO timestamps</span>
        </div>

        <div className="p-3 bg-white rounded-lg border border-slate-200 shadow-2xs">
          <span className="text-[10px] font-mono uppercase text-slate-400">INGESTION ENDPOINT</span>
          <div className="mt-1 flex items-baseline gap-2">
            <span className="text-lg font-bold font-mono text-blue-600">/api/v1/telemetry</span>
          </div>
          <span className="text-[10px] text-slate-500">Streaming webhook listener</span>
        </div>
      </div>

      {/* CSV File Upload Dropzone */}
      <div className="bg-white rounded-lg border border-slate-200 shadow-xs p-5 space-y-4">
        <div className="flex items-center justify-between border-b border-slate-100 pb-3">
          <h3 className="font-semibold text-xs text-slate-900 font-mono uppercase tracking-wider">
            Batch CSV Telemetry Import
          </h3>
          <span className="text-[11px] font-mono text-slate-400">
            Accepts UTF-8 comma-separated files up to 50MB
          </span>
        </div>

        <label className="border-2 border-dashed border-slate-200 hover:border-blue-400 rounded-lg p-8 flex flex-col items-center justify-center cursor-pointer transition-colors bg-slate-50/50 hover:bg-blue-50/30">
          <input
            type="file"
            accept=".csv"
            onChange={handleFileChange}
            className="hidden"
          />
          <Upload className="w-8 h-8 text-blue-500 mb-2" />
          <span className="font-semibold text-slate-800 text-xs">
            {selectedFile ? selectedFile.name : 'Click to select CSV or drag file here'}
          </span>
          <span className="text-[11px] text-slate-400 mt-1">
            Required columns: timestamp, rack_id, sensor_type, metric_value, unit, tenant
          </span>
        </label>

        {isUploading && (
          <div className="flex items-center gap-2 text-xs font-mono text-blue-600">
            <RefreshCw className="w-3.5 h-3.5 animate-spin" />
            <span>Parsing CSV rows and validating numerical bounds...</span>
          </div>
        )}
      </div>

      {/* Dataset Preview Table */}
      <div className="bg-white rounded-lg border border-slate-200 shadow-xs overflow-hidden">
        <div className="p-3.5 border-b border-slate-100 flex items-center justify-between bg-slate-50/60">
          <div className="flex items-center gap-2">
            <Database className="w-4 h-4 text-slate-700" />
            <h3 className="font-semibold text-xs text-slate-900">
              Live Dataset Ingestion Buffer Preview
            </h3>
          </div>
          <span className="text-[11px] font-mono text-slate-400">
            Showing recent valid sensor tuples
          </span>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left text-xs font-mono">
            <thead className="bg-slate-50/80 text-[11px] uppercase text-slate-500 border-b border-slate-200">
              <tr>
                <th className="py-2.5 px-3.5">Timestamp (UTC)</th>
                <th className="py-2.5 px-3.5">Target Identifier</th>
                <th className="py-2.5 px-3.5">Sensor Metric Type</th>
                <th className="py-2.5 px-3.5">Raw Telemetric Value</th>
                <th className="py-2.5 px-3.5">Validation Rule Check</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {previewRows.map((row, idx) => (
                <tr key={idx} className="hover:bg-slate-50/60">
                  <td className="py-2.5 px-3.5 text-slate-600">{row.timestamp}</td>
                  <td className="py-2.5 px-3.5 font-bold text-slate-900">{row.rack_id}</td>
                  <td className="py-2.5 px-3.5 text-blue-600">{row.sensor_type}</td>
                  <td className="py-2.5 px-3.5 font-bold text-slate-800">{row.raw_val}</td>
                  <td className="py-2.5 px-3.5 text-emerald-600 flex items-center gap-1 font-semibold">
                    <CheckCircle className="w-3 h-3 text-emerald-500" />
                    <span>{row.status}</span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

