import React, { useState } from 'react';
import {
  ResponsiveContainer,
  ComposedChart,
  Line,
  Area,
  XAxis,
  YAxis,
  Tooltip,
  Legend,
  ReferenceLine,
  CartesianGrid
} from 'recharts';
import {
  TrendingUp,
  AlertTriangle,
  Clock,
  Sparkles,
  Calendar,
  CheckCircle2,
  ShieldAlert,
  ArrowRight,
  Sliders,
  RotateCcw
} from 'lucide-react';
import { useData } from '../context/DataContext';

export const Forecasts: React.FC = () => {
  const { resources, currentTenant } = useData();

  const [selectedResourceId, setSelectedResourceId] = useState<string>('res-stor-01');
  const [horizonDays, setHorizonDays] = useState<number>(14);
  const [whatIfAddition, setWhatIfAddition] = useState<number>(0); // e.g. add 25 TB

  const resource = resources.find((r) => r.id === selectedResourceId) || resources[0];

  // Generate realistic historical and forecasted data with uncertainty band based on horizon
  const generateForecastData = () => {
    const data: {
      date: string;
      historical?: number;
      forecast?: number;
      upperBand?: number;
      lowerBand?: number;
      threshold: number;
    }[] = [];

    const baseUsage = resource.currentUsage;
    const capacity = resource.capacity + whatIfAddition;
    const warningThreshold = capacity * 0.8;
    const dailyGrowth = (resource.growthRateMonthly / 30) * (baseUsage * 0.05);

    // 10 historical days
    for (let i = 10; i >= 0; i--) {
      const d = new Date();
      d.setDate(d.getDate() - i);
      const dateStr = d.toLocaleDateString([], { month: 'short', day: 'numeric' });
      const val = Math.max(10, baseUsage - i * dailyGrowth * (0.9 + Math.sin(i) * 0.15));

      data.push({
        date: dateStr,
        historical: Number(val.toFixed(1)),
        forecast: i === 0 ? Number(val.toFixed(1)) : undefined,
        threshold: Number(warningThreshold.toFixed(1)),
      });
    }

    // Future horizon days
    const steps = horizonDays <= 14 ? horizonDays : Math.min(horizonDays, 30);
    const stepInterval = horizonDays > 30 ? 3 : 1;

    for (let i = 1; i <= steps; i += stepInterval) {
      const d = new Date();
      d.setDate(d.getDate() + i);
      const dateStr = d.toLocaleDateString([], { month: 'short', day: 'numeric' });
      const projected = baseUsage + i * dailyGrowth;
      const uncertainty = (i * 0.45) * dailyGrowth;

      data.push({
        date: dateStr,
        forecast: Number(projected.toFixed(1)),
        upperBand: Number((projected + uncertainty).toFixed(1)),
        lowerBand: Number(Math.max(baseUsage, projected - uncertainty).toFixed(1)),
        threshold: Number(warningThreshold.toFixed(1)),
      });
    }

    return data;
  };

  const chartData = generateForecastData();

  // Calculate adjusted exhaustion days if what-if buffer is applied
  const effectiveExhaustionDays = resource.predictedExhaustionDays
    ? Math.round(
        resource.predictedExhaustionDays *
          (1 + (whatIfAddition / (resource.capacity || 1)) * 2)
      )
    : null;

  return (
    <div className="p-4 sm:p-6 space-y-5 max-w-[1600px] mx-auto select-none">
      {/* Page Title & Subtitle */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3 border-b border-slate-200/80 pb-4">
        <div>
          <div className="flex items-center gap-2">
            <h1 className="text-xl font-bold text-slate-900 tracking-tight">
              Capacity Forecasting & Exhaustion Models
            </h1>
            <span className="font-mono text-xs px-2 py-0.5 rounded bg-blue-50 text-blue-700 border border-blue-200 font-semibold">
              Bayesian Ingestion Model v2.4
            </span>
          </div>
          <p className="text-xs text-slate-500 mt-0.5">
            Predict storage runaways, power circuit tripping, and cooling limits with confidence bands.
          </p>
        </div>

        {/* Forecast Horizon Selector */}
        <div className="flex items-center gap-1.5 bg-slate-100 p-1 rounded-lg text-xs font-mono">
          <span className="text-slate-500 px-2 font-sans font-medium">Horizon:</span>
          {[7, 14, 30, 90].map((days) => (
            <button
              key={days}
              onClick={() => setHorizonDays(days)}
              className={`px-3 py-1 rounded-md transition-all ${
                horizonDays === days
                  ? 'bg-white text-slate-900 shadow-2xs font-bold'
                  : 'text-slate-600 hover:text-slate-900'
              }`}
            >
              {days} Days
            </button>
          ))}
        </div>
      </div>

      {/* Target Resource Selector Cards */}
      <div>
        <div className="text-[11px] font-mono text-slate-400 uppercase tracking-wider mb-2">
          Select Monitored Capacity Stream
        </div>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3">
          {resources.slice(0, 4).map((res) => {
            const isSelected = res.id === selectedResourceId;
            return (
              <div
                key={res.id}
                onClick={() => setSelectedResourceId(res.id)}
                className={`p-3 rounded-lg border cursor-pointer transition-all ${
                  isSelected
                    ? 'bg-blue-50/60 border-blue-500 shadow-xs ring-1 ring-blue-500'
                    : 'bg-white border-slate-200 hover:border-slate-300'
                }`}
              >
                <div className="flex items-center justify-between">
                  <span className="text-[10px] font-mono font-semibold px-1.5 py-0.5 rounded bg-slate-100 text-slate-700 uppercase">
                    {res.type}
                  </span>
                  <span
                    className={`text-[10px] font-mono font-bold px-1.5 py-0.5 rounded ${
                      res.status === 'critical'
                        ? 'bg-rose-100 text-rose-800'
                        : res.status === 'warning'
                        ? 'bg-amber-100 text-amber-800'
                        : 'bg-emerald-100 text-emerald-800'
                    }`}
                  >
                    {res.status.toUpperCase()}
                  </span>
                </div>

                <div className="mt-2 font-medium text-slate-900 text-xs truncate">
                  {res.name}
                </div>

                <div className="mt-2 flex items-baseline justify-between text-xs">
                  <div className="font-mono text-slate-600">
                    <span className="font-bold text-slate-900">{res.currentUsage}</span> / {res.capacity} {res.unit}
                  </div>
                  <div className="font-mono font-bold text-slate-800">{res.utilPercent}%</div>
                </div>

                {res.predictedExhaustionDays && (
                  <div className="mt-2 text-[11px] text-rose-600 font-mono font-medium flex items-center gap-1">
                    <Clock className="w-3 h-3 text-rose-500" />
                    <span>Exhaustion in {res.predictedExhaustionDays} days</span>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>

      {/* Main Forecast Chart & Summary Banner */}
      <div className="bg-white rounded-lg border border-slate-200 shadow-xs p-4 space-y-4">
        {/* Resource Header & Exhaustion Countdown Card */}
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 p-3.5 rounded-lg bg-slate-50 border border-slate-200/80">
          <div>
            <div className="flex items-center gap-2">
              <span
                className={`w-2.5 h-2.5 rounded-full ${
                  resource.status === 'critical'
                    ? 'bg-rose-500 animate-pulse'
                    : resource.status === 'warning'
                    ? 'bg-amber-500'
                    : 'bg-emerald-500'
                }`}
              />
              <h3 className="font-semibold text-slate-900 text-sm">{resource.name}</h3>
              <span className="font-mono text-[11px] text-slate-500">({resource.tenant})</span>
            </div>
            <p className="text-xs text-slate-500 mt-1">
              Estimated exhaustion date: <strong className="text-slate-800">{resource.predictedDate || 'Stable (> 90 days)'}</strong> • Historical growth rate: <strong className="text-slate-800">+{resource.growthRateMonthly}% / month</strong>
            </p>
          </div>

          <div className="flex items-center gap-3">
            <div className="p-2.5 px-3 rounded-md bg-white border border-slate-200 shadow-2xs text-right">
              <div className="text-[10px] font-mono uppercase text-slate-400">ESTIMATED TIME TO LIMIT</div>
              <div className="text-base font-bold font-mono text-rose-600">
                {effectiveExhaustionDays ? `${effectiveExhaustionDays} Days Remaining` : 'No Imminent Risk'}
              </div>
            </div>

            <div className="p-2.5 px-3 rounded-md bg-white border border-slate-200 shadow-2xs text-right">
              <div className="text-[10px] font-mono uppercase text-slate-400">CURRENT UTILISATION</div>
              <div className="text-base font-bold font-mono text-slate-900">
                {resource.utilPercent}%
              </div>
            </div>
          </div>
        </div>

        {/* Analytics Chart Container */}
        <div>
          <div className="flex items-center justify-between text-xs mb-2">
            <span className="font-semibold text-slate-800 text-[11px] font-mono uppercase tracking-wider">
              {resource.type} Consumption Trajectory vs {resource.capacity} {resource.unit} Threshold
            </span>
            <div className="flex items-center gap-4 text-[11px] font-mono text-slate-500">
              <span className="flex items-center gap-1.5">
                <span className="w-3 h-0.5 bg-blue-600 inline-block" />
                Historical Telemetry
              </span>
              <span className="flex items-center gap-1.5">
                <span className="w-3 h-0.5 bg-indigo-600 border-b border-dashed border-indigo-600 inline-block" />
                ML Projected Trend
              </span>
              <span className="flex items-center gap-1.5">
                <span className="w-3 h-2 bg-indigo-100 rounded inline-block" />
                95% Confidence Band
              </span>
              <span className="flex items-center gap-1.5">
                <span className="w-3 h-0.5 bg-rose-500 inline-block" />
                80% Capacity Threshold
              </span>
            </div>
          </div>

          <div className="h-80 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart data={chartData} margin={{ top: 10, right: 20, left: 0, bottom: 5 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" vertical={false} />
                <XAxis
                  dataKey="date"
                  tickLine={false}
                  axisLine={{ stroke: '#e2e8f0' }}
                  tick={{ fontSize: 11, fill: '#64748b' }}
                />
                <YAxis
                  unit={` ${resource.unit}`}
                  domain={[0, (dataMax: number) => Math.ceil(Math.max(dataMax, resource.capacity) * 1.1)]}
                  tickLine={false}
                  axisLine={{ stroke: '#e2e8f0' }}
                  tick={{ fontSize: 11, fill: '#64748b' }}
                />
                <Tooltip
                  content={({ active, payload, label }) => {
                    if (active && payload && payload.length) {
                      return (
                        <div className="bg-slate-900 text-white p-2.5 rounded-md shadow-lg text-xs font-mono space-y-1">
                          <div className="font-bold text-slate-300">{label}</div>
                          {payload.map((entry, idx) => (
                            <div key={idx} className="flex justify-between gap-4">
                              <span style={{ color: entry.color }}>{entry.name}:</span>
                              <span className="font-bold">
                                {entry.value} {resource.unit}
                              </span>
                            </div>
                          ))}
                        </div>
                      );
                    }
                    return null;
                  }}
                />

                {/* Shaded Uncertainty Confidence Interval */}
                <Area
                  type="monotone"
                  dataKey="upperBand"
                  stroke="transparent"
                  fill="#e0e7ff"
                  fillOpacity={0.6}
                  name="Upper Confidence Band"
                />
                <Area
                  type="monotone"
                  dataKey="lowerBand"
                  stroke="transparent"
                  fill="#ffffff"
                  fillOpacity={1.0}
                  name="Lower Confidence Band"
                />

                {/* Capacity Threshold Reference Line */}
                <ReferenceLine
                  y={resource.capacity * 0.8}
                  stroke="#ef4444"
                  strokeDasharray="4 4"
                  strokeWidth={1.5}
                  label={{
                    value: `Warning Limit (${(resource.capacity * 0.8).toFixed(0)} ${resource.unit})`,
                    position: 'top',
                    fill: '#ef4444',
                    fontSize: 10,
                    fontFamily: 'monospace'
                  }}
                />

                {/* Capacity Ceiling */}
                <ReferenceLine
                  y={resource.capacity}
                  stroke="#64748b"
                  strokeWidth={1}
                  label={{
                    value: `Physical Maximum (${resource.capacity} ${resource.unit})`,
                    position: 'insideBottomRight',
                    fill: '#64748b',
                    fontSize: 10,
                    fontFamily: 'monospace'
                  }}
                />

                {/* Historical Actual Usage */}
                <Line
                  type="monotone"
                  dataKey="historical"
                  stroke="#2563eb"
                  strokeWidth={2.5}
                  dot={{ r: 3, fill: '#2563eb' }}
                  activeDot={{ r: 5 }}
                  name="Observed Telemetry"
                />

                {/* Forecast Trend */}
                <Line
                  type="monotone"
                  dataKey="forecast"
                  stroke="#4f46e5"
                  strokeWidth={2.5}
                  strokeDasharray="5 5"
                  dot={{ r: 2.5, fill: '#4f46e5' }}
                  name="Forecasted Trend"
                />
              </ComposedChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Evidence & Machine Learning Explanation */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 pt-2 border-t border-slate-100 text-xs">
          <div className="p-3 rounded-lg bg-slate-50 border border-slate-200/80 space-y-1.5">
            <span className="font-semibold text-slate-800 font-mono text-[11px] uppercase tracking-wider flex items-center gap-1.5">
              <Sparkles className="w-3.5 h-3.5 text-blue-600" />
              Evidence Supporting Projection
            </span>
            <ul className="space-y-1 text-slate-600 list-disc list-inside">
              <li>Daily ingestion rate rose from 1.3 {resource.unit}/day to 4.2 {resource.unit}/day over last 72 hours.</li>
              <li>Peak delta occurred during nightly snapshot iteration at 04:00 UTC.</li>
              <li>Bayesian regression fit score: R² = 0.984 across 1,200 observation epochs.</li>
            </ul>
          </div>

          {/* Interactive What-If Simulator */}
          <div className="p-3 rounded-lg bg-blue-50/50 border border-blue-200 space-y-2">
            <div className="flex items-center justify-between">
              <span className="font-semibold text-blue-900 font-mono text-[11px] uppercase tracking-wider flex items-center gap-1.5">
                <Sliders className="w-3.5 h-3.5 text-blue-600" />
                What-If Capacity Expansion Simulator
              </span>
              {whatIfAddition > 0 && (
                <button
                  onClick={() => setWhatIfAddition(0)}
                  className="text-[11px] text-blue-700 hover:text-blue-900 font-medium flex items-center gap-1"
                >
                  <RotateCcw className="w-3 h-3" />
                  Reset
                </button>
              )}
            </div>

            <div className="space-y-1">
              <div className="flex justify-between text-slate-700 text-xs">
                <span>Simulate Added Headroom:</span>
                <span className="font-mono font-bold text-blue-900">
                  +{whatIfAddition} {resource.unit}
                </span>
              </div>
              <input
                type="range"
                min="0"
                max="50"
                step="5"
                value={whatIfAddition}
                onChange={(e) => setWhatIfAddition(Number(e.target.value))}
                className="w-full accent-blue-600 cursor-pointer"
              />
            </div>

            <p className="text-[11px] text-blue-800">
              Adding {whatIfAddition} {resource.unit} extends buffer by{' '}
              <strong>{Math.round(whatIfAddition * 0.6)} additional days</strong>, delaying exhaustion beyond immediate operational sprint.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

