import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Search,
  Filter,
  Download,
  ArrowUpDown,
  Cpu,
  HardDrive,
  Zap,
  Wind,
  Layers,
  Network,
  Clock,
  ArrowUpRight,
  Box
} from 'lucide-react';
import { useData } from '../context/DataContext';
import { ResourceType, HealthStatus } from '../types';

export const Resources: React.FC = () => {
  const navigate = useNavigate();
  const { filteredResources, setSelectedRackId, addToast } = useData();

  const [searchQuery, setSearchQuery] = useState('');
  const [selectedType, setSelectedType] = useState<string>('All');
  const [selectedStatus, setSelectedStatus] = useState<string>('All');
  const [sortField, setSortField] = useState<'utilPercent' | 'growthRateMonthly' | 'currentUsage'>('utilPercent');
  const [sortAsc, setSortAsc] = useState<boolean>(false);

  // Filter items
  const filtered = filteredResources.filter((res) => {
    const matchesSearch =
      res.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      res.tenant.toLowerCase().includes(searchQuery.toLowerCase()) ||
      res.id.toLowerCase().includes(searchQuery.toLowerCase());

    const matchesType = selectedType === 'All' || res.type === selectedType;
    const matchesStatus = selectedStatus === 'All' || res.status === selectedStatus;

    return matchesSearch && matchesType && matchesStatus;
  });

  // Sort items
  const sorted = [...filtered].sort((a, b) => {
    const valA = a[sortField];
    const valB = b[sortField];
    return sortAsc ? valA - valB : valB - valA;
  });

  const handleExportCSV = () => {
    const headers = ['ID', 'Name', 'Tenant', 'Type', 'CurrentUsage', 'Capacity', 'Unit', 'UtilPercent', 'GrowthRateMonthly', 'Status', 'PredictedExhaustionDays'];
    const rows = sorted.map((r) => [
      r.id,
      `"${r.name}"`,
      `"${r.tenant}"`,
      r.type,
      r.currentUsage,
      r.capacity,
      r.unit,
      r.utilPercent,
      r.growthRateMonthly,
      r.status,
      r.predictedExhaustionDays ?? ''
    ]);

    const csvContent = 'data:text/csv;charset=utf-8,' + [headers.join(','), ...rows.map((e) => e.join(','))].join('\n');
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement('a');
    link.setAttribute('href', encodedUri);
    link.setAttribute('download', `capacityiq_resources_${new Date().toISOString().substring(0, 10)}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);

    addToast('CSV Exported', `Exported ${sorted.length} records.`, 'success');
  };

  const types: ('All' | ResourceType)[] = ['All', 'Storage', 'Compute', 'Power', 'Cooling', 'Network', 'Memory'];

  return (
    <div className="p-4 sm:p-6 space-y-5 max-w-[1600px] mx-auto select-none">
      {/* Top Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3 border-b border-slate-200/80 pb-4">
        <div>
          <h1 className="text-xl font-bold text-slate-900 tracking-tight">
            Resource Monitoring & Inventory
          </h1>
          <p className="text-xs text-slate-500 mt-0.5">
            Real-time utilisation rates, monthly velocity metrics, and rack physical mapping.
          </p>
        </div>

        <button
          onClick={handleExportCSV}
          className="flex items-center gap-1.5 px-3 py-1.5 bg-white border border-slate-200 hover:bg-slate-50 text-slate-700 rounded-md text-xs font-medium transition-colors shadow-2xs self-start sm:self-auto"
        >
          <Download className="w-3.5 h-3.5 text-slate-500" />
          <span>Export CSV</span>
        </button>
      </div>

      {/* Filter and Search Bar */}
      <div className="flex flex-col md:flex-row items-stretch md:items-center justify-between gap-3 bg-white p-3 rounded-lg border border-slate-200 shadow-2xs">
        {/* Search */}
        <div className="relative flex-1 max-w-sm">
          <Search className="w-3.5 h-3.5 text-slate-400 absolute left-2.5 top-1/2 -translate-y-1/2" />
          <input
            type="text"
            placeholder="Search by name, tenant, or ID..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-8 pr-3 py-1.5 rounded-md border border-slate-200 text-xs focus:outline-none focus:border-blue-500"
          />
        </div>

        {/* Type Filter Pills */}
        <div className="flex items-center gap-1 overflow-x-auto text-xs">
          {types.map((t) => (
            <button
              key={t}
              onClick={() => setSelectedType(t)}
              className={`px-2.5 py-1 rounded-md font-medium transition-colors whitespace-nowrap ${
                selectedType === t
                  ? 'bg-blue-50 text-blue-700 font-semibold border border-blue-200'
                  : 'text-slate-600 hover:bg-slate-100'
              }`}
            >
              {t}
            </button>
          ))}
        </div>

        {/* Status Filter */}
        <div className="flex items-center gap-1 text-xs">
          {['All', 'healthy', 'warning', 'critical'].map((st) => (
            <button
              key={st}
              onClick={() => setSelectedStatus(st)}
              className={`px-2.5 py-1 rounded-md capitalize transition-colors ${
                selectedStatus === st
                  ? 'bg-slate-900 text-white font-medium'
                  : 'text-slate-600 hover:bg-slate-100'
              }`}
            >
              {st}
            </button>
          ))}
        </div>
      </div>

      {/* Resources Table */}
      <div className="bg-white rounded-lg border border-slate-200 shadow-xs overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-xs">
            <thead className="bg-slate-50/80 text-[11px] font-mono uppercase text-slate-500 border-b border-slate-200">
              <tr>
                <th className="py-3 px-3.5">Resource ID & Name</th>
                <th className="py-3 px-3.5">Tenant</th>
                <th className="py-3 px-3.5">Type</th>
                <th
                  onClick={() => {
                    setSortField('currentUsage');
                    setSortAsc(!sortAsc);
                  }}
                  className="py-3 px-3.5 cursor-pointer hover:text-slate-900"
                >
                  <div className="flex items-center gap-1">
                    <span>Usage / Capacity</span>
                    <ArrowUpDown className="w-3 h-3" />
                  </div>
                </th>
                <th
                  onClick={() => {
                    setSortField('utilPercent');
                    setSortAsc(!sortAsc);
                  }}
                  className="py-3 px-3.5 cursor-pointer hover:text-slate-900"
                >
                  <div className="flex items-center gap-1">
                    <span>Utilisation</span>
                    <ArrowUpDown className="w-3 h-3" />
                  </div>
                </th>
                <th
                  onClick={() => {
                    setSortField('growthRateMonthly');
                    setSortAsc(!sortAsc);
                  }}
                  className="py-3 px-3.5 cursor-pointer hover:text-slate-900"
                >
                  <div className="flex items-center gap-1">
                    <span>Growth Velocity</span>
                    <ArrowUpDown className="w-3 h-3" />
                  </div>
                </th>
                <th className="py-3 px-3.5">Status</th>
                <th className="py-3 px-3.5">Est. Exhaustion</th>
                <th className="py-3 px-3.5 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {sorted.length === 0 ? (
                <tr>
                  <td colSpan={9} className="py-8 text-center text-slate-400">
                    No resources matched current filters.
                  </td>
                </tr>
              ) : (
                sorted.map((res) => (
                  <tr key={res.id} className="hover:bg-slate-50/70 transition-colors">
                    <td className="py-3 px-3.5 font-medium text-slate-900">
                      <div className="flex flex-col">
                        <span className="font-semibold">{res.name}</span>
                        <span className="text-[10px] font-mono text-slate-400">{res.id}</span>
                      </div>
                    </td>
                    <td className="py-3 px-3.5 text-slate-600 font-mono text-[11px]">
                      {res.tenant}
                    </td>
                    <td className="py-3 px-3.5">
                      <span className="font-mono text-[10px] px-1.5 py-0.5 rounded bg-slate-100 text-slate-700">
                        {res.type}
                      </span>
                    </td>
                    <td className="py-3 px-3.5 font-mono text-slate-700">
                      {res.currentUsage} / {res.capacity} {res.unit}
                    </td>
                    <td className="py-3 px-3.5">
                      <div className="w-32 space-y-1">
                        <div className="flex justify-between text-[11px] font-mono font-bold">
                          <span>{res.utilPercent}%</span>
                        </div>
                        <div className="w-full bg-slate-200 h-1.5 rounded-full overflow-hidden">
                          <div
                            className={`h-full rounded-full ${
                              res.status === 'critical'
                                ? 'bg-rose-500'
                                : res.status === 'warning'
                                ? 'bg-amber-500'
                                : 'bg-emerald-500'
                            }`}
                            style={{ width: `${Math.min(100, res.utilPercent)}%` }}
                          />
                        </div>
                      </div>
                    </td>
                    <td className="py-3 px-3.5 text-slate-700 font-mono text-[11px]">
                      +{res.growthRateMonthly}% / mo
                    </td>
                    <td className="py-3 px-3.5">
                      <span
                        className={`text-[10px] font-mono font-bold px-1.5 py-0.5 rounded uppercase ${
                          res.status === 'critical'
                            ? 'bg-rose-100 text-rose-800'
                            : res.status === 'warning'
                            ? 'bg-amber-100 text-amber-800'
                            : 'bg-emerald-100 text-emerald-800'
                        }`}
                      >
                        {res.status}
                      </span>
                    </td>
                    <td className="py-3 px-3.5 font-mono text-[11px]">
                      {res.predictedExhaustionDays ? (
                        <span className="font-bold text-rose-600">
                          {res.predictedExhaustionDays} days ({res.predictedDate})
                        </span>
                      ) : (
                        <span className="text-slate-400">Nominal (&gt; 90d)</span>
                      )}
                    </td>
                    <td className="py-3 px-3.5 text-right space-x-2">
                      {res.rackId && (
                        <button
                          onClick={() => {
                            setSelectedRackId(res.rackId!);
                            navigate('/');
                          }}
                          className="px-2 py-1 bg-slate-100 hover:bg-slate-200 text-slate-700 font-mono text-[11px] rounded transition-colors inline-flex items-center gap-1"
                        >
                          <Box className="w-3 h-3 text-slate-500" />
                          <span>3D Rack</span>
                        </button>
                      )}
                      <button
                        onClick={() => navigate('/forecasts')}
                        className="px-2 py-1 bg-blue-50 hover:bg-blue-100 text-blue-700 font-medium text-[11px] rounded transition-colors inline-flex items-center gap-1"
                      >
                        <span>Forecast</span>
                        <ArrowUpRight className="w-3 h-3" />
                      </button>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

sources.src/store/priorityQueue.ts:
/**
 * AO-02 Min-Heap Priority Token Queue ("Queue Dataset")
 * Deterministic scheduling of capacity incidents with infinite loop prevention.
 */

import { IncidentToken, ResourceType, PipelinePhase, RESOURCE_CRITICALITY_WEIGHTS } from '../types/ao02';

export class PriorityTokenQueue {
  private heap: IncidentToken[] = [];
  private activeKeys = new Map<string, string>(); // "{rack}:{tenant}:{resource}" -> tokenId

  /**
   * Deterministic priority score computation (1 to 100, lower integer = higher urgency).
   * Combines hardware/software criticality with utilization severity and time-to-exhaustion lead time.
   */
  public static computePriorityNumber(
    resourceType: ResourceType,
    utilizationPct: number,
    leadTimeWeeks: number
  ): number {
    const baseWeight = (RESOURCE_CRITICALITY_WEIGHTS[resourceType] ?? 5) * 10;
    const urgencyBonus = Math.max(0, Math.floor((100 - utilizationPct) / 5));
    const leadTimePenalty = Math.floor(Math.min(leadTimeWeeks, 12) * 2);
    return Math.max(1, baseWeight + urgencyBonus + leadTimePenalty);
  }

  /**
   * Enqueues a token if a token for the same resource, rack, and tenant is not already active.
   * Returns true if enqueued, false if deduplicated.
   */
  public enqueue(token: IncidentToken): boolean {
    const dedupKey = `${token.rackId}:${token.tenantId}:${token.resourceType}`;
    if (this.activeKeys.has(dedupKey)) {
      return false; // Prevent duplicate token flooding
    }

    this.activeKeys.set(dedupKey, token.tokenId);
    this.heap.push(token);
    this.bubbleUp(this.heap.length - 1);
    return true;
  }

  /**
   * Dequeues the highest-priority token (lowest priorityNumber).
   */
  public dequeue(): IncidentToken | null {
    if (this.heap.length === 0) return null;
    const top = this.heap[0];
    const bottom = this.heap.pop()!;
    const dedupKey = `${top.rackId}:${top.tenantId}:${top.resourceType}`;
    this.activeKeys.delete(dedupKey);

    if (this.heap.length > 0) {
      this.heap[0] = bottom;
      this.sinkDown(0);
    }
    return top;
  }

  public peek(): IncidentToken | null {
    return this.heap.length > 0 ? this.heap[0] : null;
  }

  /**
   * Advances token phase and enforces the loop-guard ceiling (maxAllowedHops).
   */
  public incrementHop(token: IncidentToken, nextPhase: PipelinePhase): void {
    token.hopCount += 1;
    if (token.hopCount > token.maxAllowedHops) {
      token.currentPhase = '99_HALTED_LOOP_GUARD';
      throw new Error(`Loop guard triggered for token ${token.tokenId}: exceeded max ${token.maxAllowedHops} hops.`);
    }
    token.currentPhase = nextPhase;
  }

  /**
   * Returns a sorted array of queued tokens for the frontend Priority Queue strip.
   */
  public snapshot(): IncidentToken[] {
    return [...this.heap].sort((a, b) => a.priorityNumber - b.priorityNumber);
  }

  public get size(): number {
    return this.heap.length;
  }

  private bubbleUp(idx: number): void {
    const element = this.heap[idx];
    while (idx > 0) {
      const parentIdx = Math.floor((idx - 1) / 2);
      const parent = this.heap[parentIdx];
      if (element.priorityNumber >= parent.priorityNumber) break;
      this.heap[parentIdx] = element;
      this.heap[idx] = parent;
      idx = parentIdx;
    }
  }

  private sinkDown(idx: number): void {
    const length = this.heap.length;
    const element = this.heap[idx];

    while (true) {
      const leftChildIdx = 2 * idx + 1;
      const rightChildIdx = 2 * idx + 2;
      let swapIdx: number | null = null;

      if (leftChildIdx < length) {
        if (this.heap[leftChildIdx].priorityNumber < element.priorityNumber) {
          swapIdx = leftChildIdx;
        }
      }

      if (rightChildIdx < length) {
        const compareVal = swapIdx === null ? element.priorityNumber : this.heap[leftChildIdx].priorityNumber;
        if (this.heap[rightChildIdx].priorityNumber < compareVal) {
          swapIdx = rightChildIdx;
        }
      }

      if (swapIdx === null) break;
      this.heap[idx] = this.heap[swapIdx];
      this.heap[swapIdx] = element;
      idx = swapIdx;
    }
  }
}

