/**
 * AO-02 Shared Context Heap ("Heap Memory")
 * Central state heap with strict multi-tenant isolation guard and immutable audit trail.
 */

import {
  HeapIncidentEnvelope,
  AuditTrailRecord,
  TenantId,
  PipelinePhase
} from '../types/ao02';

export class SharedContextHeap {
  private store = new Map<string, HeapIncidentEnvelope>();

  /**
   * Writes or updates an incident envelope in the shared heap and records an immutable audit trail entry.
   */
  public putEnvelope(envelope: HeapIncidentEnvelope, actor: string, summary: string): void {
    const auditRecord: AuditTrailRecord = {
      auditId: `audit-${Math.random().toString(36).substring(2, 10)}-${Date.now()}`,
      timestamp: new Date().toISOString(),
      tokenId: envelope.token.tokenId,
      phase: envelope.token.currentPhase,
      actor,
      telemetryHash: envelope.telemetry.rawSeriesSha256,
      decisionSummary: summary,
    };

    envelope.auditTrail.push(auditRecord);
    this.store.set(envelope.token.tokenId, { ...envelope });
  }

  /**
   * Internal retrieval for automated agents.
   */
  public getEnvelope(tokenId: string): HeapIncidentEnvelope {
    const envelope = this.store.get(tokenId);
    if (!envelope) {
      throw new Error(`Incident token '${tokenId}' not found in Shared Context Heap.`);
    }
    return envelope;
  }

  /**
   * Strict Tenant-Isolation Guard (AO-02 Safety Constraint).
   * Ensures Tenant 1 usage is NEVER visible to Tenant 2, while facility operators see attributed global views.
   */
  public getTenantIsolatedView(
    tokenId: string,
    requestingTenant: TenantId,
    isFacilityOperator: boolean = false
  ): HeapIncidentEnvelope {
    const envelope = this.getEnvelope(tokenId);
    if (!isFacilityOperator && requestingTenant !== 'All' && envelope.token.tenantId !== requestingTenant) {
      throw new Error(
        `TENANT ISOLATION BREACH BLOCKED: Tenant '${requestingTenant}' cannot access telemetry or forecasts belonging to Tenant '${envelope.token.tenantId}'.`
      );
    }
    return envelope;
  }

  /**
   * Lists all envelopes filtered by tenant isolation rules.
   */
  public listEnvelopes(requestingTenant: TenantId, isFacilityOperator: boolean = false): HeapIncidentEnvelope[] {
    const all = Array.from(this.store.values());
    if (isFacilityOperator || requestingTenant === 'All') {
      return all;
    }
    return all.filter((env) => env.token.tenantId === requestingTenant);
  }

  /**
   * Human-in-the-Loop decision recording.
   */
  public recordHumanVerification(
    tokenId: string,
    approved: boolean,
    operatorNotes: string,
    operatorId: string = 'Operator-Admin'
  ): HeapIncidentEnvelope {
    const envelope = this.getEnvelope(tokenId);
    envelope.humanApproved = approved;
    envelope.operatorNotes = operatorNotes;
    envelope.token.currentPhase = '07_RESOLVED';

    this.putEnvelope(
      envelope,
      operatorId,
      approved
        ? `Remediation plan approved by human operator. Action queued for scheduling.`
        : `Remediation plan rejected by operator: ${operatorNotes}`
    );

    return envelope;
  }

  public get size(): number {
    return this.store.size;
  }
}

