/**
 * AO-02 Semantic Design Token System
 * Decoupled Theme Layer: Changing colors or reskinning requires editing only this file.
 */

:root {
  /* Surfaces & Elevational Layers */
  --surface-canvas: #f8fafc;
  --surface-canvas-subtle: #f1f5f9;
  --surface-card: #ffffff;
  --surface-card-hover: #f8fafc;
  --surface-header: rgba(255, 255, 255, 0.92);
  --surface-hud: rgba(255, 255, 255, 0.95);
  --surface-hud-dark: rgba(15, 23, 42, 0.92);
  --surface-border: #e2e8f0;
  --surface-border-subtle: #f1f5f9;
  --surface-border-strong: #cbd5e1;

  /* Typography */
  --text-primary: #0f172a;
  --text-secondary: #475569;
  --text-muted: #94a3b8;
  --text-inverted: #ffffff;

  /* Status Tokens */
  --status-healthy: #10b981;
  --status-healthy-bg: #ecfdf5;
  --status-healthy-border: #a7f3d0;
  --status-healthy-text: #065f46;

  --status-warning: #f59e0b;
  --status-warning-bg: #fffbeb;
  --status-warning-border: #fde68a;
  --status-warning-text: #92400e;

  --status-critical: #ef4444;
  --status-critical-bg: #fef2f2;
  --status-critical-border: #fecaca;
  --status-critical-text: #991b1b;

  /* Resource Type Badges */
  --badge-storage: #3b82f6;
  --badge-storage-bg: #eff6ff;
  --badge-storage-border: #bfdbfe;

  --badge-power: #8b5cf6;
  --badge-power-bg: #f5f3ff;
  --badge-power-border: #ddd6fe;

  --badge-cooling: #06b6d4;
  --badge-cooling-bg: #ecfeff;
  --badge-cooling-border: #a5f3fc;

  --badge-network: #f97316;
  --badge-network-bg: #fff7ed;
  --badge-network-border: #fed7aa;

  --badge-vm: #6366f1;
  --badge-vm-bg: #eef2ff;
  --badge-vm-border: #c7d2fe;

  --badge-license: #14b8a6;
  --badge-license-bg: #f0fdfa;
  --badge-license-border: #99f6e4;

  /* Facility Mechanical Pipes & Thermal Overlays */
  --pipe-chilled: #0284c7;
  --pipe-return: #ea580c;
  --pipe-copper: #c2410c;
  --particle-cold: #38bdf8;
  --particle-heat: #ef4444;

  /* Focus & Accents */
  --accent-primary: #2563eb;
  --accent-ring: rgba(37, 99, 235, 0.25);
  --shadow-elevation: 0 1px 3px 0 rgb(0 0 0 / 0.05), 0 1px 2px -1px rgb(0 0 0 / 0.05);
  --shadow-floating: 0 10px 15px -3px rgb(0 0 0 / 0.08), 0 4px 6px -4px rgb(0 0 0 / 0.05);
}

[data-theme='dark'] {
  --surface-canvas: #090d16;
  --surface-canvas-subtle: #0f172a;
  --surface-card: #131b2e;
  --surface-card-hover: #1e293b;
  --surface-header: rgba(15, 23, 42, 0.94);
  --surface-hud: rgba(19, 27, 46, 0.95);
  --surface-hud-dark: rgba(9, 13, 22, 0.96);
  --surface-border: #1e293b;
