sources.src/types/ao02.ts:
/**
 * AO-02: Seeing Trouble Before the Capacity Runs Out
 * Core Domain Models, Priority Token Queue, Shared Context Heap, and Agent Schemas
 */

export type ResourceType =
  | 'STORAGE'
  | 'POWER'
  | 'THERMAL_COOLING'
  | 'NETWORK'
  | 'VM_COMPUTE'
  | 'SOFTWARE_LICENSE';

export type PipelinePhase =
  | '01_RESOURCE_MONITORING'
  | '02_INCIDENT_REPORTING'
  | '03_ROOT_CAUSE_ANALYSIS'
  | '04_REMEDIATION_CHECKING'
  | '05_RISK_ANALYSIS'
  | '06_HUMAN_VERIFICATION'
  | '07_RESOLVED'
  | '99_HALTED_LOOP_GUARD';

export type GateDecision =
  | 'PENDING_REVIEW'
  | 'ALLOW_ADVISORY'
  | 'REQUIRE_HUMAN_APPROVAL'
  | 'BLOCKED'
  | 'APPROVED_BY_OPERATOR'
  | 'REJECTED_BY_OPERATOR';

export type SeverityStatus = 'HEALTHY' | 'WARNING' | 'CRITICAL';

export type TenantId = 'All' | 'T1' | 'T2' | 'T3';

// Base criticality weights for hardware & software functionality prioritization (lower = higher priority)
export const RESOURCE_CRITICALITY_WEIGHTS: Record<ResourceType, number> = {
  POWER: 1,
  THERMAL_COOLING: 2,
  STORAGE: 3,
  NETWORK: 4,
  VM_COMPUTE: 5,
  SOFTWARE_LICENSE: 6,
};

export interface TelemetryWindowSummary {
  windowStart: string;
  windowEnd: string;
  rackId: string;
  tenantId: string;
  resourceType: ResourceType;
  currentUtilizationPct: number;
  safetyMarginPct: number;
  hardCapacityLimit: number;
  unit: string;
  rawSeriesSha256: string;
}

export interface CapacityForecast {
  predictedExhaustionDate: string | null;
  leadTimeWeeks: number;
  confidenceIntervalDays: [number, number]; // [lower bound days, upper bound days]
  forecastConfidenceScore: number; // 0.0 to 1.0
  isTransientSpike: boolean;
  regimeChangeDetected: boolean;
  regimeChangeDescription?: string;
}

export interface RCADiagnosis {
  rootCauseSummary: string;
  attributedTenantId: string;
  drivingWorkloadSignature: string;
  correlatedSignals: string[];
  confidenceScore: number;
  investigationNotes: string;
}

export interface RemediationOption {
  optionId: string;
  title: string;
  recommendedAction: string;
  simulatedPostActionUtilizationPct: number;
  projectedLeadTimeExtensionWeeks: number;
  mutatesLiveFacilityControls: false; // Must always remain false per AO-02 safety rules
}

export interface RiskEvaluation {
  riskScore: number; // 0.0 = low, 1.0 = critical
  blastRadiusSummary: string;
  slaImpactAssessment: string;
  gateDecision: GateDecision;
  selectedOptionId: string;
}

export interface AuditTrailRecord {
  auditId: string;
  timestamp: string;
  tokenId: string;
  phase: PipelinePhase;
  actor: string;
  telemetryHash: string;
  decisionSummary: string;
}

export interface IncidentToken {
  tokenId: string; // e.g., "T-01", "T-02"
  priorityNumber: number; // 1 to 100, lower = higher urgency in min-heap
  rackId: string;
  tenantId: string;
  resourceType: ResourceType;
  currentPhase: PipelinePhase;
  hopCount: number;
  maxAllowedHops: number; // default: 8
  createdAt: string;
}

export interface HeapIncidentEnvelope {
  token: IncidentToken;
  telemetry: TelemetryWindowSummary;
  forecast: CapacityForecast;
  rca?: RCADiagnosis;
  remediationOptions: RemediationOption[];
  riskEvaluation?: RiskEvaluation;
  humanApproved?: boolean | null;
  operatorNotes?: string;
  auditTrail: AuditTrailRecord[];
}

export interface TimeSeriesDataPoint {
  timestamp: string;
  dateStr: string;
  actualValue: number;
  utilizationPct: number;
  forecastMean?: number;
  forecastUpper?: number;
  forecastLower?: number;
  isRegimeShiftPoint?: boolean;
  isTransientSpikePoint?: boolean;
}

export interface RackSpatialNode {
  rackId: string;
  row: 'Row A' | 'Row B';
  gridPosition: { x: number; z: number };
  status: SeverityStatus;
  activeBadge?: ResourceType;
  tenant: string;
  powerLoadKw: number;
  maxPowerKw: number;
  tempC: number;
  storageUtilPct: number;
  networkGbps: number;
  activeTokenIds: string[];
}

export interface CoolingUnitNode {
  unitId: string;
  label: string;
  position: [number, number, number];
  rotationY: number;
  supplyTempCelsius: number;
  returnTempCelsius: number;
  fanSpeedRpm: number;
  status: SeverityStatus;
}

export interface KPIMetrics {
  forecastAccuracyPct: number;
  averageLeadTimeWeeks: number;
  falseAlarmSuppressionRatePct: number;
  auditabilityScorePct: number;
}

sources.src/types/index.ts:
export type HealthStatus = 'healthy' | 'warning' | 'critical';

export type ResourceType = 'Compute' | 'Storage' | 'Memory' | 'Power' | 'Cooling' | 'Network';

export type TenantName = 'All Tenants' | 'Acme Cloud' | 'FinTech Core' | 'HealthTech Alpha' | 'RetailStream';

export type SceneMode = 'normal' | 'temperature' | 'status' | 'storage' | 'power' | 'cooling' | 'network';

export interface ServerUnit {
  id: string;
  unitSlot: number; // e.g. 1 to 8
  model: string;
  status: HealthStatus;
  cpuLoadPercent: number;
  tempC: number;
  powerWatts: number;
}

export interface CapacityRisk {
  metric: 'storage' | 'power' | 'cooling' | 'network' | 'licenses';
  currentUtil: number;
  thresholdUtil: number;
  daysToExhaustion: number;
  predictedExhaustionDate: string;
  trend: 'increasing' | 'stable' | 'decreasing';
  evidence: string;
  recommendedAction: string;
}

export interface RackData {
  id: string;
  label: string;
  row: 'Row A' | 'Row B';
  position: [number, number, number]; // [x, y, z] in Three.js coordinates
  rotationY: number; // facing orientation: 0 or Math.PI
  tenant: string;
  serverCount: number;
  storageUtil: number; // 0 to 100%
  powerKw: number;
  powerMaxKw: number;
  tempC: number;
  tempTargetC: number;
  networkGbps: number;
  networkMaxGbps: number;
  health: HealthStatus;
  risk: CapacityRisk | null;
  servers: ServerUnit[];
}

export interface CoolerFault {
  id: string;
  code: string;
  machineId: string;
  machineLabel: string;
  title: string;
  description: string;
  severity: 'critical' | 'warning';
  timestamp: string;
  component: 'fan' | 'compressor' | 'filter' | 'chilled_water' | 'refrigerant';
  metricValue: string;
  thresholdValue: string;
  recommendedAction: string;
}

export interface CRACUnitData {
  id: string;
  label: string;
  position: [number, number, number];
  rotationY?: number;
  status: 'operational' | 'maintenance' | 'standby';
  coolingCapacityKw: number;
  loadKw: number;
  supplyTempC: number;
  returnTempC: number;
  airflowCfm: number;
  health: HealthStatus;
  fanSpeedRpm: number;
  fanStatus: 'running' | 'degraded' | 'stopped';
  filterPressurePa: number;
  chilledWaterFlowGpm: number;
  compressor1Load: number;
  compressor2Load: number;
  activeFault: CoolerFault | null;
}

export interface ResourceMetric {
  id: string;
  name: string;
  tenant: string;
  type: ResourceType;
  currentUsage: number;
  capacity: number;
  unit: string;
  utilPercent: number;
  growthRateMonthly: number;
  status: HealthStatus;
  predictedExhaustionDays: number | null;
  predictedDate: string | null;
  rackId?: string;
}

export interface AlertItem {
  id: string;
  title: string;
  resourceId: string;
  resourceName: string;
  tenant: string;
  rackId?: string;
  severity: 'critical' | 'warning' | 'info';
  status: 'active' | 'acknowledged' | 'resolved';
  timestamp: string;
  predictedExhaustion: string;
  metric: string;
  value: string;
  threshold: string;
  recommendedAction: string;
  operatorNotes?: { author: string; text: string; time: string }[];
}

export interface RootCauseIncident {
  id: string;
  resourceId: string;
  resourceName: string;
  title: string;
  severity: 'critical' | 'warning';
  detectedAt: string;
  anomalyDescription: string;
  historicalTrend: {
    time: string;
    actual: number;
    predicted: number;
    upperConfidence: number;
    lowerConfidence: number;
    threshold: number;
  }[];
  observedFacts: string[];
  potentialCauses: {
    hypothesis: string;
    probability: number;
    impact: 'High' | 'Medium' | 'Low';
    evidence: string;
  }[];
  recommendedActions: {
    id: string;
    action: string;
    status: 'recommended' | 'applied';
    estimatedImpact: string;
  }[];
}

export interface AuditLogEntry {
  id: string;
  timestamp: string;
  actor: {
    name: string;
    role: string;
    avatar?: string;
  };
  action: string;
  resource: string;
  details: string;
  outcome: 'success' | 'warning' | 'failed';
}

export interface SettingsState {
  capacityWarningThreshold: number; // e.g. 75%
  criticalAlertThreshold: number; // e.g. 90%
  tempUnit: 'C' | 'F';
  airflowSpeed: number; // 0.5 to 2.0
  particleDensity: 'low' | 'medium' | 'high';
  showAirflowArrows: boolean;
  showParticles: boolean;
  showPipes: boolean;
  showLabels: boolean;
  defaultCamera: 'isometric' | 'topdown' | 'aisle';
  refreshIntervalSec: number;
}

export interface ToastMessage {
  id: string;
  title: string;
  message?: string;
  type: 'success' | 'error' | 'info' | 'warning';
}

